-- ============================================================
-- KAGOMA — Migration 9: Course content for the learning platform
--   Modules, lessons, module quizzes and a final assessment,
--   generated from the approved bilingual course manuals.
--
-- Run AFTER 01..10. Safe to re-run: it clears and re-seeds the
-- content tables only. Learner progress and attempts are NOT touched.
-- ============================================================


-- Remove previously seeded content (cascades to lessons/questions/options).
-- ############################################################
--  STOP IF THERE ARE LEARNERS
--
--  Re-seeding deletes the modules and assessments for these courses.
--  Postgres cascades that delete to lesson_progress and to
--  assessment_attempts, so every tick and every exam score for these
--  courses would go with it. Certificates already issued survive;
--  a learner half way through does not.
--
--  While the courses are empty of learners this is harmless, which is
--  why it runs freely now. Once people are studying, it refuses.
--
--  To re-seed anyway, knowing the cost, run this first:
--      set kagoma.allow_reseed = 'yes';
-- ############################################################
do $$
declare n_prog int; n_att int;
begin
  if coalesce(current_setting('kagoma.allow_reseed', true), '') = 'yes' then
    raise notice 'Re-seed override in force; learner progress for these courses will be lost.';
    return;
  end if;

  select count(*) into n_prog
  from public.lesson_progress lp
  join public.lessons l on l.id = lp.lesson_id
  join public.modules m on m.id = l.module_id
  where m.course_id in ('KG-101','KG-102','KG-103','KG-104','KG-105','KG-106','KG-107','KG-108','KG-109','KG-110','KG-111','KG-112','EP-V1','EP-V2','EP-V3','EP-V4','EP-V5','EP-V6','EP-V7','EP-V8');

  select count(*) into n_att
  from public.assessment_attempts at
  join public.assessments a on a.id = at.assessment_id
  where a.course_id in ('KG-101','KG-102','KG-103','KG-104','KG-105','KG-106','KG-107','KG-108','KG-109','KG-110','KG-111','KG-112','EP-V1','EP-V2','EP-V3','EP-V4','EP-V5','EP-V6','EP-V7','EP-V8');

  if n_prog > 0 or n_att > 0 then
    raise exception
      'Refusing to re-seed: % lesson-progress rows and % exam attempts exist for these courses. Re-seeding would delete them. If that is intended, run:  set kagoma.allow_reseed = ''yes'';  and repeat.',
      n_prog, n_att;
  end if;
end $$;

delete from public.assessments where course_id in ('KG-101','KG-102','KG-103','KG-104','KG-105','KG-106','KG-107','KG-108','KG-109','KG-110','KG-111','KG-112','EP-V1','EP-V2','EP-V3','EP-V4','EP-V5','EP-V6','EP-V7','EP-V8');
delete from public.modules     where course_id in ('KG-101','KG-102','KG-103','KG-104','KG-105','KG-106','KG-107','KG-108','KG-109','KG-110','KG-111','KG-112','EP-V1','EP-V2','EP-V3','EP-V4','EP-V5','EP-V6','EP-V7','EP-V8');


-- ---------- KG-101 · Event Security Management ----------
do $$ declare m_KG_101_1 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-101') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-101', 1, 'Fundamentals of Event Security', 'Ishingiro ry''Umutekano w''Ibirori', 'This module establishes what an event security manager is accountable for, the framework within which events are secured, how event types differ in risk, and the legal and stakeholder environment surrounding every event.', 'Iki gice gishyiraho ibyo umuyobozi w''umutekano w''ibirori abazwa, urwego ibirori birindwamo, uko ubwoko bw''ibirori butandukanye mu byago, n''urwego rw''amategeko n''abafatanyabikorwa bakikije buri birori.', 1)
  returning id into m_KG_101_1;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_1, '1.1', 'The Role and Responsibilities of the Event Security Manager', 'Umurimo n''Inshingano z''Umuyobozi w''Umutekano w''Ibirori', 'text', 'The event security manager is accountable for everything that happens to people inside a temporary environment they designed. The responsibilities are: assessing risk before the event; producing a written security plan; determining staffing levels and deploying them; briefing every officer; holding command during the event; coordinating with organisers, authorities and emergency services; making the decision to stop, delay or evacuate; and conducting the review afterwards. The role is distinguished from a supervisor''s by the fact that it is exercised largely before the doors open — most of what determines whether an event is safe has already been decided by the time the first attendee arrives.', 'Umuyobozi w''umutekano w''ibirori abazwa ibyose bibaho ku bantu mu hantu h''igihe gito yateguye. Inshingano ni izi: gusuzuma ibyago mbere y''ibirori; gukora gahunda y''umutekano yanditse; kugena umubare w''abakozi no kubashyira aho; kumenyesha buri mukozi; gufata ubuyobozi mu gihe cy''ibirori; guhuza n''abategura, inzego za Leta n''abatabazi; gufata icyemezo cyo guhagarika, gutinza cyangwa kwimura abantu; no gukora isuzuma nyuma. Uyu murimo utandukanye n''uw''umugenzuzi kubera ko ukorwa cyane mbere y''uko imiryango ifungurwa — ibyinshi bigena niba ibirori bifite umutekano biba byaramaze gufatwa mbere y''uko uwitabiriye wa mbere ageza.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_1, '1.2', 'Event Security Framework and Operational Goals', 'Urwego rw''Umutekano w''Ibirori n''Intego z''Ibikorwa', 'text', 'Event security operates to four goals in a fixed order of priority: protect life; prevent injury; protect property; and enable the event to proceed. That order matters because it resolves every conflict that arises during an event — if allowing the show to continue would risk injury, the order has already answered the question. The framework supporting those goals has four phases: planning before the event, deployment and setup, live operation, and close-out with review. Weakness in any phase undermines the others, and the most commonly under-resourced phase is close-out, which is why the same failures recur across events at the same venue.', 'Umutekano w''ibirori ukora ku ntego enye ku rutonde rudahinduka: kurinda ubuzima; kwirinda ibikomere; kurinda ibintu; no gutuma ibirori bigenda. Urwo rutonde rufite akamaro kuko rukemura amakimbirane yose avuka mu gihe cy''ibirori — niba kwemerera ikirori gukomeza byakwangiza abantu, urutonde rwarasubije icyo kibazo. Urwego rushyigikira izo ntego rufite ibyiciro bine: gutegura mbere y''ibirori, gushyira abakozi no gutunganya, ibikorwa mu gihe cy''ibirori, no gusoza n''isuzuma. Intege nke mu cyiciro icyo ari cyo cyose zangiza ibindi, kandi icyiciro gikunze kubura umutungo ni ugusoza, ni yo mpamvu amakosa amwe asubirwamo mu birori ku hantu hamwe.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_1, '1.3', 'Understanding Event Types, Venues, and Risk Profiles', 'Gusobanukirwa Ubwoko bw''Ibirori, Ahantu n''Imiterere y''Ibyago', 'text', 'Risk profile is determined by the interaction of four variables: the type of event, the venue, the audience and the context. A seated conference of 300 delegates in a hotel carries a different profile from a standing concert of 8,000 in an open field, which differs again from a religious gathering, a sports fixture, a political rally or a private celebration. Audience demographics matter — age distribution, alcohol availability, emotional investment in the outcome. Context matters — is the event politically contested, is a controversial figure attending, has a similar event elsewhere recently had an incident. A plan built from a template rather than from this specific combination is the single most common root cause of event security failure.', 'Imiterere y''ibyago igenwa n''ihuriro ry''ibintu bine: ubwoko bw''ibirori, ahantu, abitabiriye n''imimerere. Inama y''intumwa 300 bicaye mu ihoteri ifite imiterere itandukanye n''igitaramo cy''abantu 8,000 bahagaze mu kibuga gifunguye, na byo bikaba bitandukanye n''iteraniro ry''idini, umukino, iteraniro rya politiki cyangwa ibirori bwite. Imiterere y''abitabiriye ifite akamaro — imyaka, kuboneka kw''inzoga, uko bishyize ku mutima ku bizavamo. Imimerere ifite akamaro — ese ibirori biteje impaka za politiki, ese hari umuntu utera impaka uzitabira, ese ibirori bisa n''ibi ahandi biherutse kugira ikibazo. Gahunda yubatswe ku rugero rusanzwe aho kubakwa kuri iri huriro ryihariye ni yo mpamvu ya mbere ikunze gutera igihombo mu mutekano w''ibirori.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_1, '1.4', 'Legal and Regulatory Requirements for Event Safety', 'Ibisabwa n''Amategeko ku Mutekano w''Ibirori', 'text', 'Events are regulated, and the security manager must establish which requirements apply before planning begins rather than discovering them during an inspection. Typical requirements cover: venue licensing and permitted capacity; fire safety certification and exit provision; the requirement for a written safety or security plan submitted in advance; medical cover ratios; alcohol licensing conditions; noise and hours restrictions; insurance; and the licensing status of the security personnel themselves. Capacity limits in particular are not advisory — exceeding a licensed capacity transfers legal liability entirely to the organiser and to anyone who knowingly permitted it, and the security manager who did not object is included in that.', 'Ibirori bigengwa n''amategeko, kandi umuyobozi w''umutekano agomba kumenya ibisabwa mbere y''uko igenamigambi ritangira aho kubimenya mu gihe cy''igenzura. Ibisabwa bisanzwe birimo: uruhushya rw''ahantu n''umubare wemewe; icyemezo cy''umutekano ku nkongi n''inzira zisohoka; gusaba gahunda y''umutekano yanditse itanzwe mbere; umubare w''abaganga; ibisabwa ku ruhushya rw''inzoga; kugarukira urusaku n''amasaha; ubwishingizi; n''impushya z''abakozi b''umutekano ubwabo. Imipaka y''umubare w''abantu by''umwihariko si inama — kurenga umubare wemewe bwohereza inshingano z''amategeko burundu ku wategura no ku wese wabyemeye abizi, kandi umuyobozi w''umutekano utabyanze abarirwa muri bo.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_1, '1.5', 'Coordination with Local Authorities and Stakeholders', 'Guhuza n''Inzego za Leta n''Abafatanyabikorwa', 'text', 'An event has more stakeholders than its organiser: police, fire service, emergency medical services, the venue owner, transport operators, local authority licensing, neighbouring businesses and residents, and sometimes the performer''s or delegation''s own protection team. Each holds information or authority the security plan depends on. Coordination must occur in a single documented meeting before the event, not through separate conversations, because separate conversations produce a plan in which each party believes something different. The output should be a written record stating who is responsible for what, who holds command over which decision, and how each party will be contacted during the event.', 'Ibirori bifite abafatanyabikorwa benshi kurusha uwabiteguye: polisi, abazimya inkongi, abatabazi ba muganga, nyir''ahantu, abatwara abantu, urwego rutanga impushya, ubucuruzi n''abaturanyi, na rimwe na rimwe itsinda rirwanira umutekano w''umuhanzi cyangwa intumwa. Buri wese afite amakuru cyangwa ububasha gahunda y''umutekano ishingiraho. Guhuza bigomba kubera mu nama imwe yanditse mbere y''ibirori, atari binyuze mu biganiro bitandukanye, kuko ibiganiro bitandukanye bitanga gahunda aho buri ruhande rwizera ikintu gitandukanye. Icyavuyemo kigomba kuba inyandiko ivuga ushinzwe iki, ufite ubuyobozi ku kihe cyemezo, n''uko buri ruhande ruzavugishwa mu gihe cy''ibirori.', 12, 5);
end $$;
do $$ declare m_KG_101_2 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-101') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-101', 2, 'Threat and Risk Assessment', 'Isuzuma ry''Iterabwoba n''Ibyago', 'This module covers the analytical work that precedes every event: identifying what could go wrong, surveying the site, gathering pre-event intelligence, analysing risk and producing the written security plan.', 'Iki gice kigaruka ku murimo wo gusesengura ubanziriza buri birori: kumenya ibyashobora kutagenda neza, gusuzuma ahantu, gukusanya amakuru mbere y''ibirori, gusesengura ibyago no gukora gahunda y''umutekano yanditse.', 2)
  returning id into m_KG_101_2;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_2, '2.1', 'Identifying Potential Threats and Vulnerabilities', 'Kumenya Iterabwoba n''Intege Nke Bishoboka', 'text', 'Threat identification must be systematic rather than intuitive, because intuition consistently over-weights dramatic scenarios and under-weights the mundane ones that actually cause most harm. Work through categories: crowd-related risk such as crush at entry or in front of a stage; behavioural risk including intoxication, disorder and conflict between groups; criminal risk including theft, ticket fraud and unauthorised entry; environmental risk including weather, terrain and structural failure; operational risk including power failure, schedule overrun and vendor non-arrival; and targeted risk where a person, group or the event itself is a deliberate target. Vulnerability is then assessed separately: for each threat, what would allow it to succeed here.', 'Kumenya iterabwoba bigomba gukorwa mu buryo buteguye aho gushingira ku myumvire, kuko imyumvire ihora yibanda ku bintu bikomeye ikirengagiza ibisanzwe ari byo bitera ibyago byinshi. Kora unyuze mu byiciro: ibyago biva ku mbaga nk''ihahamuka ku rwinjiriro cyangwa imbere y''isahani; ibyago by''imyitwarire harimo gusinda, akajagari n''amakimbirane hagati y''amatsinda; ibyago by''ubugizi bwa nabi harimo ubujura, uburiganya bw''amatike no kwinjira mu buryo butemewe; ibyago by''ibidukikije harimo ikirere, ubutaka no kunanirwa kw''inyubako; ibyago by''ibikorwa harimo amashanyarazi ahagarara, gahunda irenza igihe n''abacuruzi batagera; n''ibyago byibasiye aho umuntu, itsinda cyangwa ibirori ubwabyo ari intego. Intege nke noneho zisuzumwa ukwazo: kuri buri terabwoba, ni iki cyatuma ritsinda hano.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_2, '2.2', 'Conducting Site Surveys and Security Mapping', 'Gukora Isuzuma ry''Ahantu n''Ikarita y''Umutekano', 'text', 'A site survey is conducted physically, in the conditions the event will run in — a venue surveyed in daylight tells you little about a night event. Record and measure: every entrance and exit including emergency exits and their width; the usable floor area per zone and the resulting safe capacity; every choke point where a route narrows; surfaces, gradients and trip hazards; lighting coverage; vehicle access routes and turning space for an ambulance or fire appliance; radio coverage dead zones; and the location of utilities and cut-offs. Produce a security map marking all of it, since a written description that cannot be seen on a plan will not be used by anyone under pressure.', 'Isuzuma ry''ahantu rikorwa mu buryo bw''umubiri, mu bihe ibirori bizaberamo — ahantu hasuzumwe ku manywa ntaho hakubwira ku birori byo mu ijoro. Andika kandi upime: buri rwinjiriro n''urusohokerwa harimo n''iz''ibyihutirwa n''ubugari bwazo; ubutaka bushobora gukoreshwa kuri buri gace n''umubare w''umutekano bivamo; buri hantu hagoye aho inzira igabanuka; ubutaka, imisozi n''ahantu bashobora gusitara; aho urumuri rugera; inzira z''imodoka n''umwanya wo guhindukirira ambulance cyangwa imodoka izimya inkongi; aho radio idakora; n''aho ibikorwa remezo n''aho bizimirwa biri. Kora ikarita y''umutekano ugaragaza ibyo byose, kuko ibyanditse bitagaragara ku ikarita bitazakoreshwa n''umuntu uri mu gitutu.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_2, '2.3', 'Intelligence Gathering and Pre-Event Monitoring', 'Gukusanya Amakuru no Gukurikirana Mbere y''Ibirori', 'text', 'Pre-event intelligence answers a specific question: has anything changed since the plan was written. Sources include the organiser''s ticket sales data compared with planned capacity, publicly stated intentions to protest or disrupt, incidents at comparable recent events, weather forecasts, transport disruption affecting arrival patterns, and any change to the performer, speaker or guest list. Monitoring must continue up to and during the event, since the highest-value information often arrives in the final hours — a sold-out uplift, an announced counter-demonstration, or a road closure that will redirect arrivals to a single entrance. All gathering must remain lawful and proportionate, and must respect privacy and data protection requirements.', 'Amakuru yo mbere y''ibirori asubiza ikibazo cyihariye: ese hari icyahindutse kuva gahunda yandikwa. Amasoko arimo amakuru y''amatike yagurishijwe agereranyijwe n''umubare wateganyijwe, ibyifuzo byatangajwe ku mugaragaro byo kwigaragambya cyangwa guhungabanya, ibibazo byabaye mu birori bisa biherutse, iteganyagihe, guhagarara kw''ubwikorezi bigira ingaruka ku baza, n''impinduka iyo ari yo yose ku muhanzi, umuvugizi cyangwa urutonde rw''abatumiwe. Gukurikirana bigomba gukomeza kugeza no mu gihe cy''ibirori, kuko amakuru y''agaciro kanini akenshi aza mu masaha ya nyuma — amatike yiyongereye, itangazo ry''abandi bigaragambya, cyangwa umuhanda wafunzwe uzohereza abaza ku rwinjiriro rumwe. Gukusanya kose kugomba kuguma kwemewe n''amategeko kandi guhuye, kandi kugomba kubahiriza ubwiherero n''ibisabwa ku makuru bwite.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_2, '2.4', 'Risk Analysis and Mitigation Strategies', 'Gusesengura Ibyago n''Ingamba zo Kuzigabanya', 'text', 'Each identified risk is scored on likelihood and impact, and the combination determines priority and the type of response. There are four available strategies. Eliminate: remove the risk entirely, for example by removing a hazardous structure or cancelling a high-risk element. Reduce: lower likelihood or impact through a control such as additional entry lanes or a barrier. Transfer: shift the consequence, typically through insurance or a contractual term. Accept: acknowledge a residual risk formally, in writing, with the reason. Every risk must land in one of these four, and an accepted risk must be documented — an undocumented acceptance is indistinguishable from an oversight when the event is reviewed afterwards.', 'Buri kibazo cyamenyekanye gipimwa ku mahirwe yo kuba n''ingaruka, kandi ihuriro rigena uburemere n''ubwoko bw''igisubizo. Hari ingamba enye zihari. Gukuraho: gukuraho ikibazo burundu, urugero ukuraho inyubako ifite akaga cyangwa uhagarika igice gifite ibyago byinshi. Kugabanya: kugabanya amahirwe cyangwa ingaruka ukoresheje igenzura nk''imirongo y''inyongera yo kwinjira cyangwa urugomero. Kohereza: kwimura ingaruka, akenshi binyuze ku bwishingizi cyangwa ingingo y''amasezerano. Kwemera: kwemera ikibazo gisigaye ku mugaragaro, byanditse, hamwe n''impamvu. Buri kibazo kigomba kugwa muri kimwe muri ibi bine, kandi ikibazo cyemewe kigomba kwandikwa — kwemera kutanditse ntigitandukanywa no kwirengagiza igihe ibirori bisuzumwa nyuma.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_2, '2.5', 'Developing the Event Security Plan', 'Gutegura Gahunda y''Umutekano w''Ibirori', 'text', 'The security plan is the document everything else derives from, and it must be usable by someone who did not write it, under pressure, at night. It should state: the event details and expected attendance; the risk assessment summary and accepted risks; the site map with zones, entrances, exits and assembly points; safe capacity per zone and who monitors it; the staffing plan naming every post, its duties and its relief; the command structure with a named incident commander and deputy; the communication plan including channels and the escalation route; emergency procedures for the foreseeable scenarios; medical and evacuation arrangements; and contact details for every external party. Keep it as short as accuracy allows, because a plan nobody finishes reading is a plan nobody follows.', 'Gahunda y''umutekano ni yo nyandiko ibindi byose bivamo, kandi igomba gushobora gukoreshwa n''umuntu utari uwayanditse, ari mu gitutu, mu ijoro. Igomba kuvuga: amakuru y''ibirori n''abitabiriye biteganyijwe; incamake y''isuzuma ry''ibyago n''ibyemewe; ikarita y''ahantu ifite utugari, inzira zinjirirwa, izisohokerwa n''ahantu ho guhurira; umubare w''umutekano kuri buri gace n''uwukurikirana; gahunda y''abakozi igena buri murimo, inshingano zawo n''uzasimbura; imiterere y''ubuyobozi ifite umuyobozi w''ikibazo wagenwe n''umusimbura; gahunda y''itumanaho harimo imirongo n''inzira yo kuzamura ikibazo; inzira zo gutabara ku bibazo bishobora guteganywa; uburyo bwa muganga n''ubwo kwimuka; n''amakuru yo kuvugisha buri ruhande rwo hanze. Igumishe ngufi uko ukuri kubyemera, kuko gahunda nta muntu uyisoza ari gahunda nta muntu uyikurikiza.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-101', m_KG_101_2, 'Quiz — Threat and Risk Assessment', 'Ikizamini — Isuzuma ry''Iterabwoba n''Ibyago', 'quiz', 70, 2)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why must threat identification be systematic rather than intuitive?', 'Kuki kumenya iterabwoba bigomba gukorwa mu buryo buteguye aho gushingira ku myumvire?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Intuition over-weights dramatic scenarios and under-weights the mundane ones that cause most harm', 'Imyumvire yibanda ku bikomeye ikirengagiza ibisanzwe bitera ibyago byinshi', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The survey must be conducted in the conditions the event will run in', 'Isuzuma rigomba gukorwa mu bihe ibirori bizaberamo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Someone who did not write it can use it under pressure at night', 'Utari uwayanditse ashobora kuyikoresha ari mu gitutu mu ijoro', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An unattended service gate opened for a vehicle', 'Irembo ry''ibikorwa ritarinzwe ryafunguriwe imodoka', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why is a daylight survey inadequate for a night event?', 'Kuki isuzuma ryo ku manywa ridahagije ku birori byo mu ijoro?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A specific location and observed condition, not a general impression', 'Ahantu nyaho n''imiterere yabonetse, atari imyumvire rusange', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Where moving would expose people to the threat', 'Aho kugenda byashyira abantu mu kaga', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A specific change with a named owner and a date', 'Impinduka yihariye ifite uwayishinzwe n''itariki', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The survey must be conducted in the conditions the event will run in', 'Isuzuma rigomba gukorwa mu bihe ibirori bizaberamo', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Name the four risk mitigation strategies.', 'Vuga ingamba enye zo kugabanya ibyago.', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Fatigue degrades judgement and observation measurably', 'Umunaniro ugabanya ubushishozi no kwitegereza bigaragara', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'That of any citizen plus rights delegated by the venue', 'Ubw''umuturage uwo ari we wese n''uburenganzira yahawe n''ahantu', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Eliminate, reduce, transfer, accept', 'Gukuraho, kugabanya, kohereza, kwemera', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Directive — there is no time to build consensus', 'Gutegeka — nta gihe cyo kubaka ubwumvikane', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why must an accepted risk be documented?', 'Kuki ikibazo cyemewe kigomba kwandikwa?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Someone who did not write it can use it under pressure at night', 'Utari uwayanditse ashobora kuyikoresha ari mu gitutu mu ijoro', false, 1);
