  values (q_id, 'An undocumented acceptance is indistinguishable from an oversight at review', 'Kwemera kutanditse ntigitandukanywa no kwirengagiza mu isuzuma', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
