do $$ declare m_KG_101_3 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-101') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-101', 3, 'Crowd Management and Access Control', 'Gucunga Imbaga no Kugenzura Abinjira', 'This module covers the physics and psychology of crowds, and the systems that control who enters, where they may go, and how density is kept below dangerous levels.', 'Iki gice kigaruka ku ifiziki n''imyumvire y''imbaga, na sisitemu zigenzura uwinjira, aho ashobora kujya, n''uko ubwinshi bugumishwa munsi y''urwego rw''akaga.', 3)
  returning id into m_KG_101_3;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_3, '3.1', 'Principles of Crowd Dynamics and Human Behaviour', 'Amahame y''Imyitwarire y''Imbaga n''Iy''Abantu', 'text', 'Past a certain density a crowd stops behaving as a set of individuals and behaves as a single physical mass with its own momentum. Above roughly five persons per square metre, individuals lose the ability to control their own movement; above six, compression injury and progressive collapse become severe risks. Crucially, at that point instruction becomes ineffective — a person who cannot move cannot comply. This is why crowd management is a design problem solved before arrival rather than a control problem solved during the event. Behaviourally, crowds take their emotional cue from the most authoritative visible response, which makes a manager''s and officers'' visible composure an operational instrument rather than a personal quality.', 'Ubwinshi burenze urugero runaka, imbaga ihagarika kwitwara nk''ihuriro ry''abantu ku giti cyabo ikitwara nk''ikintu kimwe cy''umubiri gifite umuvuduko wacyo. Hejuru y''abantu batanu ho hafi kuri metero kare, abantu batakaza ubushobozi bwo kwigenzura umuvuduko wabo; hejuru y''batandatu, ibikomere byo gukandwa no kugwa gukurikirana biba ibyago bikomeye. Icy''ingenzi, muri icyo gihe amabwiriza ahinduka atagira akamaro — umuntu udashobora kugenda ntashobora gukurikiza. Ni yo mpamvu gucunga imbaga ari ikibazo cy''igenamiterere gikemurwa mbere y''uko bageza aho kuba ikibazo cy''igenzura gikemurwa mu gihe cy''ibirori. Mu myitwarire, imbaga ikura imyumvire yayo ku gisubizo kigaragara gifite ubushobozi kurusha ibindi, bigatuma gutuza kugaragara kw''umuyobozi n''abakozi kuba igikoresho cy''akazi aho kuba imico yabo bwite.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_3, '3.2', 'Ticketing, Entry Points, and Screening Procedures', 'Amatike, Inzira Zinjirirwa n''Inzira zo Kugenzura', 'text', 'Entry is the highest-risk period of most events, because arrival is concentrated and queue density can exceed safe levels outside the venue where nobody is monitoring it. The number of entry lanes must be calculated against the expected arrival rate before the event, not adjusted on the day, since the only remedies available on the day are rushing screening or accepting a dangerous queue. Screening must be applied identically to every attendee, with the prohibited item list briefed to every officer. Ticket validation should be separated from screening where volume allows, so that a ticket dispute does not stop a screening lane. Always plan a secondary entry that can be opened if the primary reaches capacity.', 'Kwinjira ni cyo gihe gifite ibyago byinshi mu birori byinshi, kuko abaza baba begeranye kandi ubwinshi bw''umurongo bushobora kurenga urwego rw''umutekano hanze y''ahantu aho nta muntu ubukurikirana. Umubare w''imirongo yo kwinjira ugomba kubarwa ugereranyije n''umuvuduko w''abaza mbere y''ibirori, atari guhindurwa uwo munsi, kuko ibisubizo byonyine bihari uwo munsi ari ukwihuta mu igenzura cyangwa kwemera umurongo ufite akaga. Igenzura rigomba gukoreshwa kimwe kuri buri witabiriye, urutonde rw''ibibujijwe rukamenyeshwa buri mukozi. Kugenzura amatike bigomba gutandukanywa n''igenzura aho umubare ubyemera, kugira ngo impaka z''itike zitahagarika umurongo w''igenzura. Buri gihe teganya urwinjiriro rwa kabiri rushobora gufungurwa niba urwa mbere rwuzuye.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_3, '3.3', 'Credentialing and VIP Access Protocols', 'Uruhushya n''Inzira zo Kwinjiza Abakomeye', 'text', 'A credentialing system establishes visually, at a distance, who may be in which zone. It works only if each credential type is instantly distinguishable, every officer has been briefed on exactly what each permits, and the system is enforced without exception including for people who appear senior. Credentials should be issued against a register, be non-transferable, and expire at the end of the event. For VIP access, agree the arrival route, the holding area, the movement plan and the departure route in advance with any accompanying protection team, and brief the officers on the route rather than on the identity of the guest, since emphasising who the guest is increases the chance of a leak.', 'Sisitemu y''uruhushya ishyiraho mu buryo bugaragara, uri kure, uwemerewe kuba mu kihe gace. Ikora gusa niba buri bwoko bw''uruhushya butandukanywa ako kanya, buri mukozi yamenyeshejwe neza icyo buri rumwe rwemerera, kandi sisitemu ikubahirizwa nta kirengagizwa harimo n''abagaragara ko ari abakuru. Impushya zigomba gutangwa hakurikijwe igitabo, ntizihererekanywe, kandi zikarangira ku iherezo ry''ibirori. Ku kwinjiza abakomeye, mwumvikane mbere ku nzira azanyuramo, ahantu ategerereza, gahunda y''imigendere n''inzira azagendera hamwe n''itsinda rirwanira umutekano riri kumwe na we, kandi umenyeshe abakozi inzira aho kubamenyesha uwo mushyitsi ari nde, kuko kwibanda ku kuba ari nde byongera amahirwe yo kumeneka.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_3, '3.4', 'Perimeter and Backstage Security', 'Umutekano w''Umurongo w''Inyuma n''Inyuma y''Isahani', 'text', 'The perimeter defines the event and everything inside it depends on that line holding. It must be continuous, with every deliberate opening staffed and every unintended opening — a gap in fencing, an unsecured gate, a low wall — identified in the site survey and closed. Backstage and operational areas require stricter control than the public area, because a person who reaches backstage is unobserved and adjacent to performers, equipment and cabling. The most common breach at events is not a person climbing a fence but a person walking through a service gate opened for a vehicle and left unattended, which makes gate discipline more important than fence height.', 'Umurongo w''inyuma usobanura ibirori kandi ibiri imbye byose bishingira ku kuba uwo murongo uhagaze. Ugomba kuba ukomeza, buri cyuho cyagenwe kigira abakozi kandi buri cyuho kitagenwe — icyuho mu rugomero, irembo ritarinzwe, urukuta rugufi — kikamenyekana mu isuzuma ry''ahantu kikaziba. Inyuma y''isahani n''ahantu h''ibikorwa hasaba igenzura rikomeye kurusha ah''abantu bose, kuko umuntu ugera inyuma y''isahani ataba areberwa kandi aba yegereye abahanzi, ibikoresho n''insinga. Ikibazo gikunze kubaho mu birori si umuntu wurira urugomero ahubwo ni umuntu unyura mu irembo ry''ibikorwa ryafunguriwe imodoka rikaba risigaye ritarinzwe, bigatuma umurava ku marembo ufite akamaro kurusha uburebure bw''urugomero.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_3, '3.5', 'Managing Bottlenecks and High-Density Areas', 'Gucunga Ahantu Hagoye n''Ahantu Hafite Ubwinshi', 'text', 'Bottlenecks are identified in the site survey and managed by design first: widen the route, split the flow, separate entry from exit, or remove the attraction that concentrates people at that point. Where a bottleneck cannot be removed, it must be staffed and monitored from an elevated position, because density problems are frequently invisible from within the crowd. Monitoring reports must state a specific location and observed condition rather than a general impression, since a report that the crowd is large is not actionable while a report that the area in front of the left barrier has reached standing-contact density and people are raising arms allows an immediate targeted decision. Never allow a barrier line to fully enclose an area without a staffed pressure release point.', 'Ahantu hagoye hamenyekana mu isuzuma ry''ahantu kandi hacungwa mbere na mbere n''igenamiterere: gukuza inzira, kugabanya imigendekere, gutandukanya kwinjira no gusohoka, cyangwa gukuraho ikintu gikurura abantu aho hantu. Aho ahantu hagoye hadashobora gukurwaho, hagomba kugira abakozi kandi hagakurikiranwa hava ahantu hazamutse, kuko ibibazo by''ubwinshi akenshi bitagaragara uri mu mbaga. Raporo zo gukurikirana zigomba kuvuga ahantu nyaho n''imiterere yabonetse aho gutanga imyumvire rusange, kuko raporo ivuga ko imbaga ari nini idakorwaho mu gihe raporo ivuga ko agace kari imbere y''urugomero rwo ibumoso kageze ku bwinshi bwo guhagarara bakorana kandi abantu bazamura amaboko ituma hafatwa icyemezo cyihuse cyibanze. Ntukemerere umurongo w''inzitizi gukikiza agace burundu nta hantu hafite abakozi ho kurekura igitutu.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-101', m_KG_101_3, 'Quiz — Crowd Management and Access Control', 'Ikizamini — Gucunga Imbaga no Kugenzura Abinjira', 'quiz', 70, 3)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'At approximately what density do individuals lose control of their own movement?', 'Ni ku buhe bwinshi ho hafi abantu batakaza ubushobozi bwo kwigenzura umuvuduko?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Above roughly five persons per square metre', 'Hejuru y''abantu batanu ho hafi kuri metero kare', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Intuition over-weights dramatic scenarios and under-weights the mundane ones that cause most harm', 'Imyumvire yibanda ku bikomeye ikirengagiza ibisanzwe bitera ibyago byinshi', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An undocumented acceptance is indistinguishable from an oversight at review', 'Kwemera kutanditse ntigitandukanywa no kwirengagiza mu isuzuma', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An unattended service gate opened for a vehicle', 'Irembo ry''ibikorwa ritarinzwe ryafunguriwe imodoka', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why must entry lanes be calculated before the event?', 'Kuki imirongo yo kwinjira igomba kubarwa mbere y''ibirori?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A specific location and observed condition, not a general impression', 'Ahantu nyaho n''imiterere yabonetse, atari imyumvire rusange', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Where moving would expose people to the threat', 'Aho kugenda byashyira abantu mu kaga', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A specific change with a named owner and a date', 'Impinduka yihariye ifite uwayishinzwe n''itariki', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The only remedies on the day are rushing screening or accepting a dangerous queue', 'Ibisubizo byonyine uwo munsi ni ukwihuta mu igenzura cyangwa kwemera umurongo w''akaga', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What is the most common perimeter breach at events?', 'Ni ikihe kibazo gikunze kubaho ku murongo w''inyuma mu birori?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Fatigue degrades judgement and observation measurably', 'Umunaniro ugabanya ubushishozi no kwitegereza bigaragara', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'That of any citizen plus rights delegated by the venue', 'Ubw''umuturage uwo ari we wese n''uburenganzira yahawe n''ahantu', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An unattended service gate opened for a vehicle', 'Irembo ry''ibikorwa ritarinzwe ryafunguriwe imodoka', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Directive — there is no time to build consensus', 'Gutegeka — nta gihe cyo kubaka ubwumvikane', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What makes a crowd density report actionable?', 'Ni iki gituma raporo y''ubwinshi bw''imbaga ikorwaho?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An undocumented acceptance is indistinguishable from an oversight at review', 'Kwemera kutanditse ntigitandukanywa no kwirengagiza mu isuzuma', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A specific location and observed condition, not a general impression', 'Ahantu nyaho n''imiterere yabonetse, atari imyumvire rusange', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is cancelled for everyone who observed', 'Rirakurwaho kuri buri wese wabibonye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Intuition over-weights dramatic scenarios and under-weights the mundane ones that cause most harm', 'Imyumvire yibanda ku bikomeye ikirengagiza ibisanzwe bitera ibyago byinshi', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 5, 'mcq', 'What must every barrier line include?', 'Ni iki buri murongo w''inzitizi ugomba kubamo?', 1, 5) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A staffed pressure release point', 'Ahantu hafite abakozi ho kurekura igitutu', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Someone who did not write it can use it under pressure at night', 'Utari uwayanditse ashobora kuyikoresha ari mu gitutu mu ijoro', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An unattended service gate opened for a vehicle', 'Irembo ry''ibikorwa ritarinzwe ryafunguriwe imodoka', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
