do $$ declare m_KG_101_6 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-101') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-101', 6, 'Ethical Conduct and Professional Standards', 'Imyitwarire y''Ubunyangamugayo n''Amabwiriza y''Umwuga', 'This final module covers how an event security professional conducts themselves: the ethical code, de-escalation and lawful use of force, professional image, accountability, and continuing development.', 'Iki gice cya nyuma kigaruka ku myitwarire y''umunyamwuga w''umutekano w''ibirori: amategeko y''ubunyangamugayo, kugabanya ubushyuhe no gukoresha imbaraga mu mategeko, ishusho y''umwuga, kwibazwa, n''iterambere rihoraho.', 6)
  returning id into m_KG_101_6;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_6, '6.1', 'Code of Ethics and Public Interaction', 'Amategeko y''Ubunyangamugayo n''Ihuriro n''Abaturage', 'text', 'An event security officer interacts with thousands of members of the public, most of whom have done nothing wrong and are simply attending an event they paid for. The ethical requirements follow from that. Treat every attendee equally regardless of appearance, nationality, gender or perceived status. Never use position for personal benefit, free access or preferential treatment for friends. Never accept a gift or payment for admitting someone. Never discuss an attendee or an incident publicly or on social media. Apply the rules to yourself and colleagues as strictly as to the public — an officer bypassing a control they enforce on others has cancelled it for everyone who observed.', 'Umukozi w''umutekano w''ibirori avugana n''abantu ibihumbi, benshi muri bo nta cyo bakoze kandi baje mu birori bishyuye. Ibisabwa mu bunyangamugayo bikurikira ibyo. Fata buri witabiriye kimwe utitaye ku ko agaragara, igihugu, igitsina cyangwa urwego rukekwa. Ntukigere ukoresha umwanya wawe ku nyungu zawe, kwinjira ku buntu cyangwa kugirira neza incuti. Ntukigere wakira impano cyangwa amafaranga yo kwinjiza umuntu. Ntukigere uvuga ku witabiriye cyangwa ku kibazo ku mugaragaro cyangwa ku mbuga. Kurikiza amategeko kuri wowe no ku bo mukorana nk''uko ubikurikiza ku baturage — umukozi usimbuka igenzura akurikiza ku bandi aba yarivanyeho kuri buri wese wabibonye.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_6, '6.2', 'De-escalation Techniques and Use of Force Principles', 'Uburyo bwo Kugabanya Ubushyuhe n''Amahame yo Gukoresha Imbaraga', 'text', 'De-escalation follows four steps in order. Listen fully without interrupting, because interruption is itself an escalation. Acknowledge the person''s frustration explicitly, which concedes nothing but reliably lowers the temperature. Act within your authority to resolve what can be resolved. Refer anything beyond it promptly, telling the person exactly what will happen next. Move the interaction away from an audience where possible, since an audience makes it much harder for the other person to back down. On use of force: an event security officer holds no authority beyond that of any citizen plus rights delegated by the venue. Force must be lawful, reasonable, proportionate, a last resort, and must cease the moment the threat ceases.', 'Kugabanya ubushyuhe bikurikiza intambwe enye ku rutonde. Umva byose udahagarika ijambo, kuko guhagarika ijambo ubwabyo ari ukongera ubushyuhe. Emera uburakari bw''uwo muntu mu magambo agaragara, bitatanga ikintu ariko bigabanya ubushyuhe buri gihe. Kora mu bubasha bwawe ukemure ibishobora gukemuka. Ohereza ikirengeje vuba, ubwira uwo muntu neza icyo kizakurikiraho. Kura ikiganiro aho abantu bareba bishoboka, kuko abareba batuma bigora uwo muntu gusubira inyuma. Ku gukoresha imbaraga: umukozi w''umutekano w''ibirori nta bubasha afite burenze ubw''umuturage uwo ari we wese n''uburenganzira yahawe n''ahantu. Imbaraga zigomba kuba zemewe, zishyize mu gaciro, zihuye n''akaga, ari bwo buryo bwa nyuma, kandi zigomba guhagarara ako kanya akaga kavuyeho.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_6, '6.3', 'Professional Image and Representation', 'Ishusho y''Umwuga no Guhagararira Ikigo', 'text', 'At an event the officer is the most visible representative of both the security company and the organiser, and attendees form a judgement of both within seconds. That judgement rests on appearance, bearing and manner: uniform clean and complete, posture upright, hands visible, a calm even tone, and greeting first rather than waiting to be approached. Officers should be visible enough to reassure and to deter, without appearing confrontational. Behaviour that damages the image disproportionately includes: using a phone on post, sitting when the post requires standing, watching the performance instead of the crowd, and gathering in groups to talk. Each is minor individually and each is noticed by hundreds of people.', 'Mu birori umukozi ni we uhagarariye cyane ikigo cy''umutekano n''utegura, kandi abitabiriye bafata icyemezo kuri byombi mu masegonda. Icyo cyemezo gishingira ku myambarire, imyifatire n''imigirire: umwenda usukuye kandi wuzuye, uhagaze wemye, amaboko agaragara, ijwi rituje rihamye, no gusuhuza mbere aho gutegereza ko begerwa. Abakozi bagomba kugaragara bihagije kugira ngo batuze kandi bakumire, batagaragara nk''abashaka guhangana. Imyitwarire yangiza ishusho cyane irimo: gukoresha telefoni ku murimo, kwicara aho umurimo usaba guhagarara, kureba igitaramo aho kureba imbaga, no guteranira mu matsinda kugira ngo baganire. Buri kimwe ni gito ku giti cyacyo kandi buri kimwe kibonwa n''abantu amagana.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_6, '6.4', 'Accountability and Legal Responsibilities', 'Kwibazwa n''Inshingano z''Amategeko', 'text', 'Accountability in event security is evidenced or it does not exist. Every significant action and decision should be recorded: the capacity monitoring log, the incident report, the decision to open a secondary entrance, the refusal of entry and its reason, the time an emergency service was called. These records protect the officer as much as the organisation — an officer who acted correctly but recorded nothing is in a weaker position than one who acted imperfectly and documented it fully. Legal responsibilities include the duty of care toward attendees, compliance with licensed capacity, lawful use of force, respect for privacy and data protection, and honest reporting. An officer who exceeds their authority exposes themselves criminally and the organisation civilly.', 'Kwibazwa mu mutekano w''ibirori kwerekanwa cyangwa ntikubaho. Buri gikorwa n''icyemezo gikomeye bigomba kwandikwa: igitabo cyo gukurikirana umubare, raporo y''ikibazo, icyemezo cyo gufungura urwinjiriro rwa kabiri, kwima umuntu kwinjira n''impamvu, isaha abatabazi bahamagariwe. Izi nyandiko zirinda umukozi nk''uko zirinda ikigo — umukozi wakoze neza ariko ntiyandike ikintu ari mu mwanya mubi kurusha uwakoze atari byiza akabyandika byuzuye. Inshingano z''amategeko zirimo inshingano yo kwita ku bitabiriye, kubahiriza umubare wemewe, gukoresha imbaraga mu mategeko, kubahiriza ubwiherero n''amakuru bwite, no gutanga raporo z''ukuri. Umukozi urenga ububasha bwe yiteza ibyago by''ubushinjacyaha kandi agateza ikigo ibirego.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_101_6, '6.5', 'Continuous Improvement and Professional Development', 'Gukomeza Kunoza n''Iterambere ry''Umwuga', 'text', 'Event security offers a clear progression: officer, team leader, event supervisor, event security manager, and from there into venue security management, safety officer roles, or independent consultancy in event planning. Development is driven by three things. Certification: recognised qualifications, first aid, fire safety and crowd safety credentials improve mobility and earning capacity substantially. Range: working across event types — concerts, conferences, sport, religious gatherings, political events — builds judgement that no single venue can. Documentation: keep a record of events worked, roles held, incidents managed and plans written, because a portfolio is what distinguishes a candidate at interview from someone who simply lists years of experience.', 'Umutekano w''ibirori utanga inzira igaragara: umukozi, umuyobozi w''itsinda, umugenzuzi w''ibirori, umuyobozi w''umutekano w''ibirori, kandi uhereye aho ukajya mu micungire y''umutekano w''ahantu, imirimo y''ushinzwe umutekano, cyangwa ubujyanama bwigenga mu gutegura ibirori. Iterambere riterwa n''ibintu bitatu. Ibyemezo: ibyemezo byemewe, ubufasha bwa mbere, umutekano ku nkongi n''ibyemezo by''umutekano w''imbaga byongera cyane ubushobozi bwo kwimuka n''uwo kwinjiza. Ubugari: gukorera ubwoko butandukanye bw''ibirori — ibitaramo, inama, imikino, amateraniro y''amadini, ibirori bya politiki — byubaka ubushishozi nta hantu hamwe hashobora kubwubaka. Inyandiko: bika inyandiko y''ibirori wakoreye, imirimo wagize, ibibazo wacyuye na gahunda wanditse, kuko ububiko ari bwo butandukanya ukandida mu kiganiro n''utondeka imyaka gusa.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-101', m_KG_101_6, 'Quiz — Ethical Conduct and Professional Standards', 'Ikizamini — Imyitwarire y''Ubunyangamugayo n''Amabwiriza y''Umwuga', 'quiz', 70, 6)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Name the four steps of de-escalation.', 'Vuga intambwe enye zo kugabanya ubushyuhe.', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Listen, Acknowledge, Act, Refer', 'Kumva, Kwemera, Gukora, Kohereza', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Intuition over-weights dramatic scenarios and under-weights the mundane ones that cause most harm', 'Imyumvire yibanda ku bikomeye ikirengagiza ibisanzwe bitera ibyago byinshi', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An undocumented acceptance is indistinguishable from an oversight at review', 'Kwemera kutanditse ntigitandukanywa no kwirengagiza mu isuzuma', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The only remedies on the day are rushing screening or accepting a dangerous queue', 'Ibisubizo byonyine uwo munsi ni ukwihuta mu igenzura cyangwa kwemera umurongo w''akaga', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What authority does an event security officer hold?', 'Ni ubuhe bubasha umukozi w''umutekano w''ibirori afite?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An unattended service gate opened for a vehicle', 'Irembo ry''ibikorwa ritarinzwe ryafunguriwe imodoka', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Ambiguity about who holds decision authority', 'Kutamenya ufite ububasha bwo gufata icyemezo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To support — clearing routes, crowd control, information — not to keep directing', 'Gushyigikira — gufungura inzira, kugenzura imbaga, gutanga amakuru — atari gukomeza kuyobora', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'That of any citizen plus rights delegated by the venue', 'Ubw''umuturage uwo ari we wese n''uburenganzira yahawe n''ahantu', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Why does an officer bypassing a control damage it for everyone?', 'Kuki umukozi usimbuka igenzura arivanaho kuri buri wese?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A specific location and observed condition', 'Ahantu nyaho n''imiterere yabonetse', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Listen, Acknowledge, Act, Refer', 'Kumva, Kwemera, Gukora, Kohereza', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is cancelled for everyone who observed', 'Rirakurwaho kuri buri wese wabibonye', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A specific change with a named owner and a date', 'Impinduka yihariye ifite uwayishinzwe n''itariki', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why must significant decisions be recorded?', 'Kuki ibyemezo bikomeye bigomba kwandikwa?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An undocumented acceptance is indistinguishable from an oversight at review', 'Kwemera kutanditse ntigitandukanywa no kwirengagiza mu isuzuma', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Accountability is evidenced or it does not exist — records protect the officer too', 'Kwibazwa kwerekanwa cyangwa ntikubaho — inyandiko zirinda n''umukozi', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'That of any citizen plus rights delegated by the venue', 'Ubw''umuturage uwo ari we wese n''uburenganzira yahawe n''ahantu', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Intuition over-weights dramatic scenarios and under-weights the mundane ones that cause most harm', 'Imyumvire yibanda ku bikomeye ikirengagiza ibisanzwe bitera ibyago byinshi', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 5, 'mcq', 'What distinguishes a candidate at interview in this field?', 'Ni iki gitandukanya ukandida mu kiganiro cy''akazi muri uru rwego?', 1, 5) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A documented portfolio, not a list of years', 'Ububiko bwanditse, atari urutonde rw''imyaka', true, 1);
