do $$ declare m_KG_102_2 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-102') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-102', 2, 'Crowd Risk Assessment and Capacity Planning', 'Isuzuma ry''Ibyago by''Imbaga no Kubara Ubushobozi', 'This module covers the analytical work done before anyone arrives: surveying the site, identifying choke points, calculating safe capacity from measurement, and producing a crowd management plan.', 'Iki gice kigaruka ku murimo wo gusesengura ukorwa mbere y''uko hagira ugera: gusuzuma ahantu, kumenya ahantu hagoye, kubara umubare w''umutekano ushingiye ku bipimo, no gukora gahunda yo gucunga imbaga.', 2)
  returning id into m_KG_102_2;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_2, '2.1', 'Conducting a Crowd Safety Site Survey', 'Gukora Isuzuma ry''Ahantu ku Mutekano w''Imbaga', 'text', 'The survey must be conducted physically, in the conditions the event will run in, because a site walked in daylight tells you little about the same site at night in rain. Measure and record: the width of every entrance and exit including emergency exits; usable floor area per zone excluding structures, bars and equipment; every point where a route narrows; surfaces, gradients, steps and trip hazards; lighting coverage and shadow; vehicle access and turning space; and radio dead zones. Photograph each significant finding. The output is a measured site map, because a written description of a hazard that cannot be seen on a plan will not be used by anyone acting under pressure.', 'Isuzuma rigomba gukorwa mu buryo bw''umubiri, mu bihe ibirori bizaberamo, kuko ahantu hagenzuwe ku manywa hatakubwira ku hantu hamwe mu ijoro imvura igwa. Pima kandi wandike: ubugari bwa buri rwinjiriro n''urusohokerwa harimo n''iz''ibyihutirwa; ubutaka bushobora gukoreshwa kuri buri gace utabariyemo inyubako, bari n''ibikoresho; buri hantu inzira igabanuka; ubutaka, imisozi, intambwe n''ahantu bashobora gusitara; aho urumuri rugera n''ibicucu; inzira z''imodoka n''umwanya wo guhindukira; n''aho radio idakora. Fata amafoto ya buri kintu gikomeye wabonye. Icyavuyemo ni ikarita y''ahantu ifite ibipimo, kuko ibyanditse ku kaga bitagaragara ku ikarita bitazakoreshwa n''umuntu ukora mu gitutu.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_2, '2.2', 'Identifying and Classifying Choke Points', 'Kumenya no Gutondeka Ahantu Hagoye', 'text', 'A choke point is any location where a route narrows and flow is forced to compress, producing a sharp local rise in density regardless of how comfortable the overall venue is. Typical examples: a doorway narrower than the corridor feeding it; a staircase; a corner where two flows converge; a gap between a barrier and a wall; a bar or merchandise stand adjacent to a walkway; and a surface change causing people to slow. Classify each by severity, based on the flow rate expected through it against its width, and by whether it can be removed, widened, bypassed or must instead be staffed and monitored throughout.', 'Ahantu hagoye ni aho inzira igabanuka kandi imigendekere igahatirwa kwiyunga, bigatera ubwinshi bukabije aho hantu uko ahantu hose hose haba huruhutse kose. Ingero zisanzwe: umuryango mugufi kurusha inzira imugezaho; urwuriro; ikona aho imigendekere ibiri ihurira; icyuho hagati y''urugomero n''urukuta; bari cyangwa aho bacuruza byegereye inzira; n''ihinduka ry''ubutaka rituma abantu bagenda buhoro. Tondeka buri hantu ku buremere, ushingiye ku muvuduko w''abazanyuramo ugereranyije n''ubugari bwaho, n''uko hashobora gukurwaho, kugurwa, kwikwepwa cyangwa hakenera abakozi n''ukugenzurwa mu gihe cyose.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_2, '2.3', 'Calculating Safe Capacity from Measurement', 'Kubara Umubare w''Umutekano Ushingiye ku Bipimo', 'text', 'Safe capacity is calculated, not estimated. Take the usable floor area of a zone in square metres, excluding structures, equipment and any area people cannot stand in, and divide by the density figure appropriate to that zone and activity — a lower figure for a standing area near a stage than for a circulation area. Then check the result against exit capacity: a zone that can hold a number of people it cannot evacuate in the required time is over capacity regardless of floor area. The lower of the two figures is the operating limit. A calculated figure can be defended to a licensing authority or in an inquiry; an estimated one cannot.', 'Umubare w''umutekano urabarwa, ntupimwa mu maso. Fata ubutaka bushobora gukoreshwa bw''agace mu bipimo bya metero kare, utabariyemo inyubako, ibikoresho n''ahantu hose abantu badashobora guhagarara, hanyuma ubugabanye n''umubare w''ubwinshi ukwiye ako gace n''igikorwa — umubare muke ku hantu bahagarara hafi y''isahani kurusha ahantu banyura. Hanyuma ugenzure icyavuyemo ugereranyije n''ubushobozi bwo gusohoka: agace gashobora kwakira umubare w''abantu kadashobora kwimura mu gihe gisabwa karenze umubare uko ubutaka bwaba bungana kose. Umubare muke muri iyo mibare ibiri ni wo mupaka w''akazi. Umubare wabazwe ushobora kwiregurwa ku rwego rutanga impushya cyangwa mu iperereza; uwapimwe mu maso ntibishoboka.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_2, '2.4', 'Building the Crowd Management Plan', 'Gukora Gahunda yo Gucunga Imbaga', 'text', 'The plan must be usable by someone who did not write it, under pressure, at night. It should state: expected attendance and arrival profile; the measured site map with zones, entrances, exits and assembly points; safe capacity per zone and who monitors each; the queue and flow design; barrier positions including pressure release points and who operates them; the monitoring positions and reporting protocol; density trigger levels and the specific action at each; the evacuation plan; and the named person authorised to stop or pause the event. A plan without stated trigger levels leaves every decision to individual judgement at the moment judgement is hardest.', 'Gahunda igomba gushobora gukoreshwa n''umuntu utari uwayanditse, ari mu gitutu, mu ijoro. Igomba kuvuga: abitabiriye biteganyijwe n''uko bazagenda bagera; ikarita y''ahantu yapimwe ifite utugari, inzira zinjirirwa, izisohokerwa n''ahantu ho guhurira; umubare w''umutekano kuri buri gace n''uwukurikirana; imiterere y''umurongo n''imigendekere; aho inzitizi ziri harimo n''ahantu ho kurekura igitutu n''ababikoresha; ahantu ho gukurikirana n''uburyo bwo gutanga raporo; urwego rw''ubwinshi rutera igikorwa n''igikorwa cyihariye kuri buri rwego; gahunda yo kwimuka; n''umuntu wagenwe wemerewe guhagarika cyangwa gutinza ibirori. Gahunda idafite urwego rutera igikorwa isiga buri cyemezo ku bushishozi bw''umuntu ku giti cye mu gihe ubushishozi bugoye kurusha ibindi.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_2, '2.5', 'Contingency Planning for Foreseeable Crowd Disruptions', 'Gutegura Ibitunguranye Bishoboka ku Mbaga', 'text', 'Certain disruptions are predictable enough that they should never be improvised. A sudden weather change on an outdoor site will move thousands toward cover simultaneously. A power failure removes lighting and public address at once. A schedule overrun holds a crowd waiting past its patience. A headline act cancelling produces both disappointment and a mass early departure. A transport disruption redirects all arrivals to one entrance. Each requires a written contingency stating the trigger, the action, and who authorises it. A team that has rehearsed the question of what to do if power fails at peak attendance will act in seconds; a team meeting it for the first time will lose minutes deciding.', 'Ibibazo bimwe birateganywa ku buryo bidakwiye kwikorerwa mu kanya. Impinduka y''ikirere itunguranye ku hantu ho hanze izimura abantu ibihumbi bagana ahakingiye icyarimwe. Amashanyarazi ahagaze akuraho urumuri n''ijwi icyarimwe. Gahunda irenza igihe igumisha imbaga itegereje irenza ubwihangane. Umuhanzi mukuru uhagaritse atanga agahinda no kugenda kw''abantu benshi kare. Guhagarara kw''ubwikorezi byohereza abaza bose ku rwinjiriro rumwe. Buri kimwe gisaba gahunda yanditse ivuga igitera, igikorwa, n''uwemeza. Itsinda ryigeze kwitoza ikibazo cy''icyo gukora niba amashanyarazi ahagaze igihe abantu ari benshi rizakora mu masegonda; itsinda ribihuye bwa mbere rizatakaza iminota rifata icyemezo.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-102', m_KG_102_2, 'Quiz — Crowd Risk Assessment and Capacity Planning', 'Ikizamini — Isuzuma ry''Ibyago by''Imbaga no Kubara Ubushobozi', 'quiz', 70, 2)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why must a site survey be conducted in the event''s actual conditions?', 'Kuki isuzuma ry''ahantu rigomba gukorwa mu bihe ibirori bizaberamo?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A site walked in daylight tells you little about it at night in rain', 'Ahantu hagenzuwe ku manywa hatakubwira ku hantu mu ijoro imvura igwa', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Above roughly five persons per square metre', 'Hejuru y''abantu batanu ho hafi kuri metero kare', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd calibrates its alarm level against the most authoritative visible response', 'Imbaga ipima ubwoba bwayo ku gisubizo kigaragara gifite ubushobozi', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Otherwise every decision is left to individual judgement when judgement is hardest', 'Ubundi buri cyemezo gisigara ku bushishozi bwa buri wese igihe bugoye', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'How is safe capacity calculated?', 'Umubare w''umutekano ubarwa ute?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A controlled line distributes people along a length instead of concentrating them', 'Umurongo ugenzurwa ukwirakwiza abantu aho kubegeranyiriza', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It abandons the checkpoint''s purpose while barely affecting the queue', 'Bitererana intego y''aho hagenzurirwa hatabaye impinduka ku murongo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Early separation rather than late intervention', 'Gutandukanya kare aho kugira icyo ukora bitinze', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Usable area ÷ appropriate density figure, then checked against exit capacity', 'Ubutaka ÷ umubare w''ubwinshi ukwiye, hanyuma ugenzurwe n''ubushobozi bwo gusohoka', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Which figure becomes the operating limit?', 'Ni uwuhe mubare uba umupaka w''akazi?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd moved too fast into a narrowing produces the compression it was escaping', 'Imbaga yihuse mu hantu hagabanuka itanga gukandana yari yirinda', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'In crowd safety the near-miss is usually the only warning before the incident', 'Mu mutekano w''imbaga ni cyo burira rwonyine mbere y''ikibazo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The lower of floor-area capacity and exit capacity', 'Umuke muri uw''ubutaka n''uw''ubushobozi bwo gusohoka', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An announcement from the source the crowd is watching reduces pressure fastest', 'Itangazo rivuye ku isoko imbaga ireba rigabanya igitutu vuba', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why must a crowd plan state density trigger levels?', 'Kuki gahunda y''imbaga igomba kuvuga urwego rw''ubwinshi rutera igikorwa?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A site walked in daylight tells you little about it at night in rain', 'Ahantu hagenzuwe ku manywa hatakubwira ku hantu mu ijoro imvura igwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Otherwise every decision is left to individual judgement when judgement is hardest', 'Ubundi buri cyemezo gisigara ku bushishozi bwa buri wese igihe bugoye', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is a limit that no longer exists', 'Ni umupaka utakiriho', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A blocked crowd — momentum keeps arriving at a front that cannot move', 'Imbaga ibujijwe — umuvuduko ukomeza kugera imbere hadashobora kugenda', false, 4);
end $$;
do $$ declare m_KG_102_3 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-102') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-102', 3, 'Queue Design, Barriers and Flow Control', 'Igenamiterere ry''Umurongo, Inzitizi no Kugenzura Imigendekere', 'This module covers the operational systems that keep density safe: how queues are designed, how barriers are selected and placed, how flow is separated, and how density is monitored in real time.', 'Iki gice kigaruka kuri sisitemu z''akazi zigumisha ubwinshi mu mutekano: uko imirongo itegurwa, uko inzitizi zihitamo zikanashyirwa aho, uko imigendekere itandukanywa, n''uko ubwinshi bukurikiranwa muri iki gihe.', 3)
  returning id into m_KG_102_3;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_3, '3.1', 'Designing Queue Systems That Prevent Bunching', 'Gutegura Sisitemu z''Imirongo Zirinda Ihuriro ry''Abantu', 'text', 'A well-designed queue converts an open crowd into a controlled line, which is inherently safer because it distributes people along a length instead of concentrating them in an area. Barriers should form the line rather than relying on people to organise themselves. Staff must be positioned along the full length of the queue and not only at the head, so that problems are detected where they begin rather than where they end. A queue should never double back on itself without physical separation, because ambiguity about which line is which invites people to move sideways and create crossing flows. Communicate an honest estimated wait time, because uncertainty produces more frustration than delay does.', 'Umurongo uteguwe neza uhindura imbaga ifunguye umurongo ugenzurwa, ari wo mutekano kurusha kuko ukwirakwiza abantu mu burebure aho kubegeranyiriza mu gace. Inzitizi zigomba gukora umurongo aho kwiringira abantu ngo bitondere. Abakozi bagomba gushyirwa mu burebure bwose bw''umurongo atari ku mutwe gusa, kugira ngo ibibazo bimenyekane aho bitangirira aho kumenyekana aho birangirira. Umurongo ntugomba na rimwe gusubira inyuma udatandukanyijwe mu buryo bw''umubiri, kuko kutamenya uwo murongo ari uwuhe bitera abantu kwimuka ku ruhande bagakora imigendekere yambukiranya. Menyesha igihe cy''ukuri giteganyijwe cyo gutegereza, kuko kutamenya bitera uburakari kurusha gutinda.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_3, '3.2', 'One-Way Systems and Flow Separation', 'Sisitemu y''Icyerekezo Kimwe no Gutandukanya Imigendekere', 'text', 'Two crowd flows moving in opposing directions through the same space produce turbulence, and turbulence is the condition that precedes a crush. The remedy is separation: entry routes physically distinct from exit routes, circulation designed so that people moving toward a stage do not meet people leaving it, and clearly marked one-way sections where the space cannot accommodate two flows. Separation must be physical rather than signposted, because a crowd under pressure does not read signs. Where separation is impossible, that location becomes a monitored point requiring staff, and the plan must record it as an accepted residual risk with the control applied.', 'Imigendekere ibiri y''imbaga igenda mu byerekezo bihabanye mu mwanya umwe itanga imigendekere idatuje, kandi iyo migendekere idatuje ni yo miterere ibanziriza ihahamuka. Igisubizo ni ugutandukanya: inzira zo kwinjira zitandukanye mu buryo bw''umubiri n''izo gusohoka, imigendekere iteguwe ku buryo abagana ku isahani batahura n''abayivamo, n''ahantu hagaragazwa neza h''icyerekezo kimwe aho umwanya udashobora kwakira imigendekere ibiri. Gutandukanya bigomba kuba ibyo mu buryo bw''umubiri aho kuba ibyapa, kuko imbaga iri mu gitutu idasoma ibyapa. Aho gutandukanya bidashoboka, aho hantu haba ahantu hakurikiranwa hasaba abakozi, kandi gahunda igomba kwandika ko ari ikibazo cyemewe gisigaye hamwe n''igenzura ryashyizweho.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_3, '3.3', 'Barrier Selection, Placement and Pressure Release', 'Guhitamo Inzitizi, Kuzishyira Aho no Kurekura Igitutu', 'text', 'Barriers must be rated for the load they will actually bear. A rope or tape line marks a boundary but absorbs no pressure, and treating one as a crush barrier is a serious error. Critically, a barrier line must never fully enclose an area without a release point, because a crowd pressed against an immovable barrier with nowhere to relieve pressure is the precise mechanism by which most crush injuries occur. Every barrier line requires a planned, staffed opening through which compressed individuals can be extracted, and officers must be briefed in advance on where those openings are and who operates them. Barriers must also be inspected and secured before the event, since a barrier that moves under load is worse than none.', 'Inzitizi zigomba kuba zishoboye uburemere zizakira by''ukuri. Umugozi cyangwa uruti rwerekana imbibi ariko ntibwakira igitutu, kandi kubufata nk''urugomero rw''igitutu ni ikosa rikomeye. Icy''ingenzi cyane, umurongo w''inzitizi ntugomba na rimwe gukikiza agace burundu nta hantu ho kurekura igitutu, kuko imbaga ikandiwe ku rugomero rudatimuka nta ho igabanya igitutu ari yo nzira nyayo ibikomere byinshi byo gukandwa binyuramo. Buri murongo w''inzitizi usaba icyuho cyateganyijwe gifite abakozi aho abakandiwe bashobora gukurwamo, kandi abakozi bagomba kumenyeshwa mbere aho ibyo byuho biri n''ababikoresha. Inzitizi zigomba kandi kugenzurwa no gushyirwa neza mbere y''ibirori, kuko urugomero rutimuka ruri munsi y''uburemere ari rubi kurusha kutagira na rumwe.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_3, '3.4', 'Monitoring Density in Real Time', 'Gukurikirana Ubwinshi muri Iki Gihe', 'text', 'Density must be monitored continuously, not assessed once at the start, because it changes with the schedule. Officers should be stationed at elevated monitoring points where the overall shape of the crowd is visible, since density problems are frequently invisible from within the crowd itself. Reports must describe a specific location and observed condition rather than a general impression: a report that the crowd is large tells a commander nothing actionable, while a report that the area in front of the left barrier has reached standing-contact density with people raising arms allows an immediate targeted decision. Define trigger levels in advance so that a report leads automatically to a pre-agreed action rather than a discussion.', 'Ubwinshi bugomba gukurikiranwa buhoraho, atari gupimwa rimwe mu ntangiriro, kuko buhinduka bijyanye na gahunda. Abakozi bagomba gushyirwa ku hantu hazamutse ho gukurikirana aho imiterere yose y''imbaga igaragara, kuko ibibazo by''ubwinshi akenshi bitagaragara uri mu mbaga ubwayo. Raporo zigomba gusobanura ahantu nyaho n''imiterere yabonetse aho gutanga imyumvire rusange: raporo ivuga ko imbaga ari nini nta cyo ibwira umuyobozi gishobora gukorwa, mu gihe raporo ivuga ko agace kari imbere y''urugomero rwo ibumoso kageze ku bwinshi bwo guhagarara bakorana abantu bazamura amaboko ituma hafatwa icyemezo cyihuse cyibanze. Gena urwego rutera igikorwa mbere kugira ngo raporo itume habaho igikorwa cyumvikanyweho aho gutuma habaho ikiganiro.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_3, '3.5', 'Managing Entry: The Highest-Risk Period', 'Gucunga Kwinjira: Igihe Gifite Ibyago Byinshi', 'text', 'Entry is the highest-risk period at most events because arrival is concentrated and queue density outside the venue frequently exceeds safe levels where nobody is monitoring it. The number of entry lanes must be calculated against the expected arrival rate before the event, since the only remedies available on the day are rushing the checks or accepting a dangerous queue. Always plan a secondary entry that can be opened when the primary reaches capacity, and identify in the plan who is authorised to open it and at what trigger. Never resolve an entry queue problem by increasing processing speed alone, because that abandons the purpose of the checkpoint while barely affecting the queue.', 'Kwinjira ni cyo gihe gifite ibyago byinshi mu birori byinshi kuko abaza baba begeranye kandi ubwinshi bw''umurongo hanze y''ahantu akenshi burenga urwego rw''umutekano aho nta muntu ubukurikirana. Umubare w''imirongo yo kwinjira ugomba kubarwa ugereranyije n''umuvuduko w''abaza mbere y''ibirori, kuko ibisubizo byonyine bihari uwo munsi ari ukwihuta mu igenzura cyangwa kwemera umurongo w''akaga. Buri gihe teganya urwinjiriro rwa kabiri rushobora gufungurwa iyo urwa mbere rwuzuye, kandi ugene muri gahunda uwemerewe kurufungura n''urwego rutera. Ntukigere ukemura ikibazo cy''umurongo wo kwinjira wongera umuvuduko gusa, kuko ibyo bitererana intego y''aho hagenzurirwa hatabaye impinduka ku murongo.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-102', m_KG_102_3, 'Quiz — Queue Design, Barriers and Flow Control', 'Ikizamini — Igenamiterere ry''Umurongo, Inzitizi no Kugenzura Imigendekere', 'quiz', 70, 3)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why should barriers form a queue rather than relying on people to organise?', 'Kuki inzitizi zigomba gukora umurongo aho kwiringira abantu?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A controlled line distributes people along a length instead of concentrating them', 'Umurongo ugenzurwa ukwirakwiza abantu aho kubegeranyiriza', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Above roughly five persons per square metre', 'Hejuru y''abantu batanu ho hafi kuri metero kare', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd calibrates its alarm level against the most authoritative visible response', 'Imbaga ipima ubwoba bwayo ku gisubizo kigaragara gifite ubushobozi', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The lower of floor-area capacity and exit capacity', 'Umuke muri uw''ubutaka n''uw''ubushobozi bwo gusohoka', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why must flow separation be physical rather than signposted?', 'Kuki gutandukanya imigendekere bigomba kuba ibyo mu buryo bw''umubiri?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Otherwise every decision is left to individual judgement when judgement is hardest', 'Ubundi buri cyemezo gisigara ku bushishozi bwa buri wese igihe bugoye', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It abandons the checkpoint''s purpose while barely affecting the queue', 'Bitererana intego y''aho hagenzurirwa hatabaye impinduka ku murongo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Early separation rather than late intervention', 'Gutandukanya kare aho kugira icyo ukora bitinze', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd under pressure does not read signs', 'Imbaga iri mu gitutu ntisoma ibyapa', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What must every barrier line include and why?', 'Ni iki buri murongo w''inzitizi ugomba kubamo n''impamvu?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd moved too fast into a narrowing produces the compression it was escaping', 'Imbaga yihuse mu hantu hagabanuka itanga gukandana yari yirinda', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'In crowd safety the near-miss is usually the only warning before the incident', 'Mu mutekano w''imbaga ni cyo burira rwonyine mbere y''ikibazo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A staffed pressure release point — enclosure with no release causes crush injury', 'Ahantu ho kurekura igitutu hafite abakozi — gukikiza nta kurekura bitera ibikomere', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An announcement from the source the crowd is watching reduces pressure fastest', 'Itangazo rivuye ku isoko imbaga ireba rigabanya igitutu vuba', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why is increasing processing speed the wrong fix for an entry queue?', 'Kuki kwongera umuvuduko ari igisubizo kibi ku murongo wo kwinjira?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A site walked in daylight tells you little about it at night in rain', 'Ahantu hagenzuwe ku manywa hatakubwira ku hantu mu ijoro imvura igwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It abandons the checkpoint''s purpose while barely affecting the queue', 'Bitererana intego y''aho hagenzurirwa hatabaye impinduka ku murongo', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is a limit that no longer exists', 'Ni umupaka utakiriho', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A blocked crowd — momentum keeps arriving at a front that cannot move', 'Imbaga ibujijwe — umuvuduko ukomeza kugera imbere hadashobora kugenda', false, 4);
end $$;
do $$ declare m_KG_102_4 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-102') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-102', 4, 'Crowd Communication and Behavioural Control', 'Itumanaho n''Imbaga no Kugenzura Imyitwarire', 'This module covers influencing a crowd without force: how to speak to large numbers, how to interrupt panic, when physical intervention is and is not appropriate, and how to manage the specific behaviours that generate risk.', 'Iki gice kigaruka ku kugira icyo uhindura ku mbaga utakoresheje imbaraga: uko uvugana n''abantu benshi, uko uhagarika ubwoba, igihe kugira icyo ukora ku mubiri bikwiye n''igihe bidakwiye, n''uko wacunga imyitwarire yihariye itera ibyago.', 4)
  returning id into m_KG_102_4;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_4, '4.1', 'Communicating Effectively with a Large Crowd', 'Kuvugana Neza n''Imbaga Nini', 'text', 'Instructions to a crowd must be short, calm and directive. A specific instruction such as ''please move toward the exit on your left'' produces action; a long or anxious announcement produces confusion and often accelerates panic. Tone carries more weight than content at scale, because a crowd cannot process detail but registers emotional state immediately. Officers should combine clear hand signals with verbal instruction, since a substantial proportion of any large crowd cannot hear an announcement clearly. Instructions given at different points must be consistent, because a crowd receiving contradictory directions from two officers stops complying with either.', 'Amabwiriza ku mbaga agomba kuba magufi, atuje kandi asobanutse. Itegeko ryihariye nka ''nyamuneka nimwerekeze ku muryango uri ibumoso bwanyu'' ritanga igikorwa; itangazo rirekire cyangwa rifite ubwoba ritanga urujijo kandi akenshi ryihutisha ubwoba. Uburyo uvuga bufite uburemere kurusha ibivuzwe ku mbaga nini, kuko imbaga idashobora gutunganya ibisobanuro ariko ihita yumva imimerere y''imyumvire. Abakozi bagomba guhuza ibimenyetso by''amaboko bisobanutse n''amabwiriza y''amagambo, kuko igice kinini cy''imbaga nini iyo ari yo yose kidashobora kumva itangazo neza. Amabwiriza atangwa ahantu hatandukanye agomba guhuza, kuko imbaga yakiriye amabwiriza avuguruzanya avuye ku bakozi babiri ihagarika gukurikiza na rimwe.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_4, '4.2', 'Interrupting Panic Before It Spreads', 'Guhagarika Ubwoba Mbere y''uko Bukwira', 'text', 'Panic spreads faster than any actual threat and typically starts from one loud reaction others read as evidence of danger. The interruption is informational and behavioural. Informationally, an early, honest and calm announcement about what is happening prevents the vacuum that rumour fills, and rumour travels faster and far less accurately. Behaviourally, officers must not run, must not shout among themselves, and must not visibly cluster in alarm, because a crowd reads officer behaviour as the most authoritative available signal about how dangerous the situation is. Where a false alarm occurs, say so quickly and clearly rather than allowing a crowd to remain in an unresolved state of alert.', 'Ubwoba bukwira vuba kurusha akaga nyako kose kandi akenshi butangirira ku gisubizo kimwe cy''ijwi rikomeye abandi basoma nk''ikimenyetso cy''akaga. Guhagarika ni ukw''amakuru n''ukw''imyitwarire. Mu makuru, itangazo ryihuse, ry''ukuri kandi rituje ku kiri kuba ririnda icyuho ibihuha byuzuza, kandi ibihuha bigenda vuba kandi bidafite ukuri. Mu myitwarire, abakozi ntibagomba kwiruka, ntibagomba gutera hejuru bavugana, kandi ntibagomba guteranira hamwe bafite ubwoba bigaragara, kuko imbaga isoma imyitwarire y''abakozi nk''ikimenyetso gifite ubushobozi kurusha ibindi ku bijyanye n''uburemere bw''ikibazo. Aho induru y''ibinyoma ibaye, bivuge vuba kandi neza aho kwemerera imbaga kuguma mu bwoba butakemuwe.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_4, '4.3', 'When Physical Intervention Is and Is Not Appropriate', 'Igihe Kugira Icyo Ukora ku Mubiri Bikwiye n''Igihe Bidakwiye', 'text', 'Physical intervention in a dense crowd is inherently hazardous and should be limited to extracting individuals in immediate distress, ideally through a planned release point. Attempting to push a crowd backward transfers force into a mass that cannot comply, increases compression at the point of contact, and frequently triggers the panic response the officer is trying to prevent. The correct approach is to work with the direction of flow: relieve pressure by opening capacity ahead rather than resisting it from the front. Officers must never enter a dense crowd alone, must maintain their own escape route, and must recognise that an officer trapped in a crush becomes a casualty rather than a responder.', 'Kugira icyo ukora ku mubiri mu mbaga yegeranye ni akaga kandi bigomba kugarukira ku gukura abantu bari mu kaga kegereje, cyane cyane binyuze ku hantu hateganyijwe ho kurekura igitutu. Kugerageza gusunika imbaga inyuma bwohereza imbaraga mu mbaga idashobora gukurikiza, byongera gukandana aho bakoranye, kandi akenshi bitera igisubizo cy''ubwoba umukozi aba agerageza kwirinda. Uburyo bunoze ni ugukorana n''icyerekezo cy''imigendekere: gabanya igitutu ufungura ubushobozi imbere aho kubirwanya uvuye imbere. Abakozi ntibagomba na rimwe kwinjira mu mbaga yegeranye bonyine, bagomba kugumana inzira yabo yo gusohokamo, kandi bagomba kumva ko umukozi ufashwe mu ihahamuka aba uwakomeretse aho kuba utabara.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_4, '4.4', 'Managing Alcohol, Disorder and Group Conflict', 'Gucunga Inzoga, Akajagari n''Amakimbirane hagati y''Amatsinda', 'text', 'Alcohol raises risk in three ways: it reduces individual awareness of danger, it increases the likelihood of conflict, and it slows response to instruction. Where alcohol is available, density thresholds should be treated more conservatively and monitoring increased. Group conflict typically escalates from a small trigger and is best managed by early separation rather than late intervention: identify developing tension, move one group''s route or position, and remove the audience where possible. Intervene quietly, in numbers, and out of the crowd''s line of sight where practical, because a visible confrontation between officers and attendees becomes a focal point that draws people toward it and raises density exactly where it is least wanted.', 'Inzoga zongera ibyago mu buryo butatu: zigabanya ubwitonzi bw''umuntu ku kaga, zongera amahirwe y''amakimbirane, kandi zitinza igisubizo ku mabwiriza. Aho inzoga ziboneka, imipaka y''ubwinshi igomba gufatwa mu buryo bukomeye kandi gukurikirana bikiyongera. Amakimbirane hagati y''amatsinda akenshi akura ava ku kintu gito kandi acunzwe neza n''ugutandukanya kare aho kugira icyo ukora bitinze: menya ubushyuhe bugenda bukura, imura inzira cyangwa umwanya w''itsinda rimwe, kandi ukureho abareba aho bishoboka. Kora mu bwiherero, muri benshi, kandi hanze y''aho imbaga ireba aho bishoboka, kuko guhangana kugaragara hagati y''abakozi n''abitabiriye biba ikintu gikurura abantu kandi bikongera ubwinshi aho butifuzwa.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_4, '4.5', 'Working with Stewards, Staff and Organisers', 'Gukorana n''Abayobora Abantu, Abakozi n''Abategura', 'text', 'Crowd safety depends on information held outside the security team: stewards see conditions in areas security cannot cover, bar staff see intoxication developing, production staff know when a schedule change will move thousands at once, and the organiser knows when an announcement will be made from the stage. All of this reaches the security team only where the relationship is cooperative. Practical measures: include stewards and venue staff in the pre-event briefing on density triggers, the stop signal and the reporting route; establish a simple channel to the monitoring point; and give visible feedback when a report leads to action. The stage is also a crowd-management tool — an announcement from the source the crowd is already watching reduces forward pressure faster than officers at a barrier can.', 'Umutekano w''imbaga ushingira ku makuru ari hanze y''itsinda ry''umutekano: abayobora abantu babona uko bimeze mu bice umutekano udashobora kugenzura, abakozi ba bari babona gusinda bigenda byiyongera, abakozi b''igikorwa bazi igihe impinduka ya gahunda izimura abantu ibihumbi icyarimwe, kandi utegura azi igihe itangazo rizatangwa rivuye ku isahani. Ibi byose bigera ku itsinda ry''umutekano gusa aho umubano ari uw''ubufatanye. Ingamba zifatika: shyira abayobora abantu n''abakozi b''ahantu mu kumenyeshwa mbere y''ibirori ku rwego rw''ubwinshi rutera igikorwa, ikimenyetso cyo guhagarara n''inzira yo gutanga amakuru; shyiraho inzira yoroshye igana ku hantu hakurikiranirwa; kandi utange ibitekerezo bigaragara igihe amakuru yatumye habaho igikorwa. Isahani na yo ni igikoresho cyo gucunga imbaga — itangazo rivuye ku isoko imbaga imaze kwibandaho rigabanya igitutu cy''imbere vuba kurusha abakozi bari ku rugomero.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-102', m_KG_102_4, 'Quiz — Crowd Communication and Behavioural Control', 'Ikizamini — Itumanaho n''Imbaga no Kugenzura Imyitwarire', 'quiz', 70, 4)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why does tone matter more than content when addressing a large crowd?', 'Kuki uburyo uvuga bufite akamaro kurusha ibivuzwe ku mbaga nini?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd cannot process detail but registers emotional state immediately', 'Imbaga ntitunganya ibisobanuro ariko ihita yumva imimerere y''imyumvire', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Above roughly five persons per square metre', 'Hejuru y''abantu batanu ho hafi kuri metero kare', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd calibrates its alarm level against the most authoritative visible response', 'Imbaga ipima ubwoba bwayo ku gisubizo kigaragara gifite ubushobozi', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The lower of floor-area capacity and exit capacity', 'Umuke muri uw''ubutaka n''uw''ubushobozi bwo gusohoka', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why must officers never push a crowd backward to relieve pressure?', 'Kuki abakozi batagomba gusunika imbaga inyuma kugira ngo bagabanye igitutu?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Otherwise every decision is left to individual judgement when judgement is hardest', 'Ubundi buri cyemezo gisigara ku bushishozi bwa buri wese igihe bugoye', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A staffed pressure release point — enclosure with no release causes crush injury', 'Ahantu ho kurekura igitutu hafite abakozi — gukikiza nta kurekura bitera ibikomere', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Early separation rather than late intervention', 'Gutandukanya kare aho kugira icyo ukora bitinze', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It transfers force into a mass that cannot comply and increases compression', 'Bwohereza imbaraga mu mbaga idashobora gukurikiza kandi byongera gukandana', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'How is group conflict best managed?', 'Amakimbirane hagati y''amatsinda acungwa gute neza?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd moved too fast into a narrowing produces the compression it was escaping', 'Imbaga yihuse mu hantu hagabanuka itanga gukandana yari yirinda', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'In crowd safety the near-miss is usually the only warning before the incident', 'Mu mutekano w''imbaga ni cyo burira rwonyine mbere y''ikibazo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Early separation rather than late intervention', 'Gutandukanya kare aho kugira icyo ukora bitinze', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An announcement from the source the crowd is watching reduces pressure fastest', 'Itangazo rivuye ku isoko imbaga ireba rigabanya igitutu vuba', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why is the stage a crowd-management tool?', 'Kuki isahani ari igikoresho cyo gucunga imbaga?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A site walked in daylight tells you little about it at night in rain', 'Ahantu hagenzuwe ku manywa hatakubwira ku hantu mu ijoro imvura igwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An announcement from the source the crowd is watching reduces pressure fastest', 'Itangazo rivuye ku isoko imbaga ireba rigabanya igitutu vuba', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is a limit that no longer exists', 'Ni umupaka utakiriho', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A blocked crowd — momentum keeps arriving at a front that cannot move', 'Imbaga ibujijwe — umuvuduko ukomeza kugera imbere hadashobora kugenda', false, 4);
end $$;
do $$ declare m_KG_102_5 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-102') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-102', 5, 'Evacuation and Crowd Emergency Response', 'Kwimuka no Gutabara mu Byihutirwa by''Imbaga', 'This module covers what happens when the plan is activated: evacuation versus shelter-in-place, directing large numbers safely, assembly and accounting, and reaching a casualty inside a dense crowd.', 'Iki gice kigaruka ku bibaho igihe gahunda ishyizwe mu bikorwa: kwimuka ugereranyije no kuguma aho uri, kuyobora abantu benshi mu mutekano, guhurira no kubarura, no kugera ku wakomeretse mu mbaga yegeranye.', 5)
  returning id into m_KG_102_5;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_5, '5.1', 'Evacuation Versus Shelter-in-Place', 'Kwimuka Ugereranyije no Kuguma Aho Uri', 'text', 'These are opposite responses, and the plan must state in advance which threats call for which, since choosing wrongly is worse than acting slowly. Evacuation applies where remaining is more dangerous than moving — fire, smoke, structural failure, gas. Shelter-in-place applies where moving would expose people to the threat — severe weather, an external hazard, certain security incidents where the outside is less safe than the inside. The decision must sit with the named incident commander and must not be made independently by officers at different points, because a partial evacuation into an unsafe area is worse than either response applied consistently.', 'Ibi ni ibisubizo bihabanye, kandi gahunda igomba kuvuga mbere iterabwoba risaba iki, kuko guhitamo nabi ari bibi kurusha gukora buhoro. Kwimuka bikoreshwa aho kuguma aho biteje akaga kurusha kugenda — inkongi, umwotsi, kunanirwa kw''inyubako, gaze. Kuguma aho uri bikoreshwa aho kugenda byashyira abantu mu kaga — ikirere kibi cyane, akaga ko hanze, ibibazo bimwe by''umutekano aho hanze hadafite umutekano kurusha imbere. Icyemezo kigomba kuba ku muyobozi w''ikibazo wagenwe kandi ntikigomba gufatwa buri wese ukwe n''abakozi bari ahantu hatandukanye, kuko kwimura igice kimwe ujya ahantu hatarinzwe ari bibi kurusha igisubizo icyo ari cyo cyose gikurikizwa buri gihe.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_5, '5.2', 'Evacuation Capacity and Route Planning', 'Ubushobozi bwo Kwimuka no Gutegura Inzira', 'text', 'Evacuation requires far more exit capacity than entry capacity, because arrival occurs gradually over hours while evacuation must occur within minutes. Planning must assume that not every normal route will be usable, since the emergency itself may block the primary exit — a fire will make one side of a building unusable, which is precisely the side people would instinctively use. Officers must therefore know multiple pre-planned routes for every zone, and must know them well enough to direct people without hesitation, because visible uncertainty in an officer during an evacuation transmits directly into crowd anxiety and slows the whole movement.', 'Kwimuka bisaba ubushobozi bwinshi cyane bwo gusohoka kurusha ubwo kwinjira, kuko kugera bibera buhoro mu masaha mu gihe kwimuka bigomba kubera mu minota. Igenamigambi rigomba kwiyumvisha ko atari buri nzira isanzwe izashobora gukoreshwa, kuko ibyihutirwa ubwabyo bishobora kuziba inzira nkuru — inkongi izatuma uruhande rumwe rw''inyubako rutakoreshwa, ari na rwo ruhande abantu bakwiyumvisha gukoresha. Abakozi rero bagomba kumenya inzira nyinshi zateganyijwe mbere kuri buri gace, kandi bakazimenya neza bihagije kugira ngo bayobore abantu batazuyaza, kuko kutamenya kugaragara ku mukozi mu gihe cyo kwimuka bihita byoherezwa mu bwoba bw''imbaga kandi bikatinza imigendekere yose.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_5, '5.3', 'Directing a Controlled Evacuation', 'Kuyobora Kwimuka Kugenzurwa', 'text', 'Officers must actively direct rather than assume people will locate exits, because most people in an unfamiliar space attempt to leave by the route they entered even when nearer exits exist. Position officers to be seen and heard, use consistent instructions across positions so people moving between zones are not given contradictory directions, and maintain onward flow toward the assembly point rather than allowing people to stop immediately outside an exit, which blocks those still emerging behind them. Keep the pace steady rather than urgent: a crowd moved too fast through a narrowing produces exactly the compression the evacuation was intended to escape.', 'Abakozi bagomba kuyobora ku bushake aho kwiyumvisha ko abantu bazibonera inzira zisohoka, kuko abantu benshi mu hantu batazi bagerageza gusohoka banyuze mu nzira binjiriyemo n''igihe hari inzira za hafi. Shyira abakozi aho babonwa kandi bumvwa, koresha amabwiriza ahuje ahantu hose kugira ngo abantu bimuka bava mu kagari bajya mu kandi batahabwa amabwiriza avuguruzanya, kandi ugumishe imigendekere igana ahantu ho guhurira aho kwemerera abantu guhagarara bahita basohoka, bikaziba abakiri gusohoka inyuma yabo. Gumisha umuvuduko uhamye aho kuwuhutisha: imbaga yimuwe vuba cyane inyuze ahantu hagabanuka itanga gukandana nyako kwimuka kwari kugamije kwirinda.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_5, '5.4', 'Assembly Points and Accounting for People', 'Ahantu ho Guhurira no Kubarura Abantu', 'text', 'An assembly point must be far enough from the incident to be safe, close enough to be reached quickly, and large enough for the full number arriving so that it does not itself become a dangerous concentration — an assembly point sized for a fraction of the crowd recreates the problem it was meant to solve. It must also not sit on an emergency vehicle access route. Officers assist with accounting so that anyone unaccounted for is identified quickly, since that is the information emergency services need most urgently on arrival. People must be prevented from returning to the venue, which is a common and dangerous impulse driven by concern for belongings or companions.', 'Ahantu ho guhurira hagomba kuba kure y''ikibazo bihagije kugira ngo habe umutekano, hafi bihagije kugira ngo hagerweho vuba, kandi hanini bihagije ku mubare wose ugeze kugira ngo naho ubwaho hatabaho ihuriro ry''akaga — ahantu ho guhurira hagenewe igice cy''imbaga hongera gukora ikibazo hari hagamije gukemura. Hagomba kandi kutaba ku nzira imodoka z''ibyihutirwa zinyuraho. Abakozi bafasha kubarura kugira ngo utabonetse amenyekane vuba, kuko ari yo makuru abatabazi bakenera cyane bageze. Abantu bagomba kubuzwa gusubira ku hantu h''ibirori, ari byo bikunze kubaho kandi bikaba akaga, biterwa no kwitangira ibintu byabo cyangwa abo bari kumwe.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_5, '5.5', 'Medical Access Through a Dense Crowd', 'Kugera ku Buvuzi Unyuze mu Mbaga Yegeranye', 'text', 'A medical emergency inside a dense crowd presents a distinct problem: the casualty may be reachable only with difficulty and a stretcher or medical team may be physically unable to pass. Planning must establish a route that can be opened on instruction and identify who opens it. Officers should know how to create a corridor by working along the direction of flow rather than cutting across it. Where a casualty cannot be reached at all, the immediate priority is reducing density around them by opening capacity nearby, since compression is very frequently the cause of the medical emergency in the first place, and reducing it may resolve the emergency before the medical team arrives.', 'Ikibazo cy''ubuzima cyihutirwa mu mbaga yegeranye gitanga ikibazo cyihariye: uwakomeretse ashobora kugerwaho bigoye kandi ingobyi cyangwa itsinda rya muganga bishobora kunanirwa kunyuramo. Igenamigambi rigomba gushyiraho inzira ishobora gufungurwa hatanzwe itegeko rikanamenya uyifungura. Abakozi bagomba kumenya uko bakora umuhanda bakurikiza icyerekezo cy''imigendekere aho kucyambukiranya. Aho uwakomeretse atagerwaho na gato, icy''ibanze cyihutirwa ni ukugabanya ubwinshi bumukikije bafungura ubushobozi hafi aho, kuko gukandwa akenshi ari yo mpamvu y''icyo kibazo cy''ubuzima uhereye ku ntangiriro, kandi kukugabanya bishobora gukemura ikibazo mbere y''uko itsinda rya muganga rigera.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-102', m_KG_102_5, 'Quiz — Evacuation and Crowd Emergency Response', 'Ikizamini — Kwimuka no Gutabara mu Byihutirwa by''Imbaga', 'quiz', 70, 5)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Who makes the evacuation versus shelter decision?', 'Ni nde ufata icyemezo cyo kwimuka cyangwa kuguma aho uri?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The named incident commander only — never officers independently', 'Umuyobozi w''ikibazo wagenwe gusa — atari abakozi buri wese ukwe', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Above roughly five persons per square metre', 'Hejuru y''abantu batanu ho hafi kuri metero kare', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd calibrates its alarm level against the most authoritative visible response', 'Imbaga ipima ubwoba bwayo ku gisubizo kigaragara gifite ubushobozi', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The lower of floor-area capacity and exit capacity', 'Umuke muri uw''ubutaka n''uw''ubushobozi bwo gusohoka', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why must exit capacity far exceed entry capacity?', 'Kuki ubushobozi bwo gusohoka bugomba kurenga cyane ubwo kwinjira?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Otherwise every decision is left to individual judgement when judgement is hardest', 'Ubundi buri cyemezo gisigara ku bushishozi bwa buri wese igihe bugoye', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A staffed pressure release point — enclosure with no release causes crush injury', 'Ahantu ho kurekura igitutu hafite abakozi — gukikiza nta kurekura bitera ibikomere', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It transfers force into a mass that cannot comply and increases compression', 'Bwohereza imbaraga mu mbaga idashobora gukurikiza kandi byongera gukandana', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Arrival is gradual over hours; evacuation must occur within minutes', 'Kugera bibera buhoro mu masaha; kwimuka bikorwa mu minota', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Why should evacuation pace be steady rather than urgent?', 'Kuki umuvuduko wo kwimuka ugomba kuba uhamye aho kuba uwihuse?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Arrival is gradual over hours; evacuation must occur within minutes', 'Kugera bibera buhoro mu masaha; kwimuka bikorwa mu minota', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'In crowd safety the near-miss is usually the only warning before the incident', 'Mu mutekano w''imbaga ni cyo burira rwonyine mbere y''ikibazo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd moved too fast into a narrowing produces the compression it was escaping', 'Imbaga yihuse mu hantu hagabanuka itanga gukandana yari yirinda', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Early separation rather than late intervention', 'Gutandukanya kare aho kugira icyo ukora bitinze', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What is the first priority when a casualty cannot be reached in a dense crowd?', 'Ni iki cy''ibanze igihe uwakomeretse atagerwaho mu mbaga yegeranye?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A site walked in daylight tells you little about it at night in rain', 'Ahantu hagenzuwe ku manywa hatakubwira ku hantu mu ijoro imvura igwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Reduce density around them by opening capacity nearby', 'Kugabanya ubwinshi bumukikije ufungura ubushobozi hafi aho', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is a limit that no longer exists', 'Ni umupaka utakiriho', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A blocked crowd — momentum keeps arriving at a front that cannot move', 'Imbaga ibujijwe — umuvuduko ukomeza kugera imbere hadashobora kugenda', false, 4);
end $$;
do $$ declare m_KG_102_6 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-102') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-102', 6, 'Review, Documentation and Professional Standards', 'Isuzuma, Inyandiko n''Amabwiriza y''Umwuga', 'This final module covers what happens after: reporting accurately, reviewing to change controls, learning from near-misses, and the ethical and professional standards that govern crowd safety work.', 'Iki gice cya nyuma kigaruka ku bibaho nyuma: gutanga raporo mu kuri, gusuzuma kugira ngo hahinduke ibigenzura, kwiga ku byari hafi kubaho, n''amabwiriza y''ubunyangamugayo n''ay''umwuga agenga akazi k''umutekano w''imbaga.', 6)
  returning id into m_KG_102_6;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_6, '6.1', 'Incident Reporting in Crowd Environments', 'Gutanga Raporo y''Ikibazo mu Mbaga', 'text', 'Write the report as soon as practicable while recollection is accurate, and record observed fact only — exact times, precise locations, the density condition observed, the behaviour seen and the action taken — with no assumption, inference or opinion. Crowd incidents attract inquiry more than most, and these documents frequently become evidence in a licensing review, an insurance claim or a legal proceeding. Vague expressions such as ''it got quite busy'' weaken a report to the point of uselessness; ''at 21:40 the area between barrier sections 3 and 4 reached standing-contact density with attendees raising arms'' is a usable record.', 'Andika raporo vuba bishoboka mu gihe kwibuka gukiri kunoze, kandi wandike ibyabonetse gusa — amasaha nyayo, ahantu nyaho, imiterere y''ubwinshi yabonetse, imyitwarire yabonywe n''igikorwa cyakozwe — nta kwiyumvisha, gukeka cyangwa ibitekerezo. Ibibazo by''imbaga bikurura iperereza kurusha ibindi byinshi, kandi izi nyandiko akenshi ziba ibimenyetso mu isuzuma ry''uruhushya, ikirego cy''ubwishingizi cyangwa urubanza. Amagambo adasobanutse nka ''habaye abantu benshi'' atuma raporo idafite akamaro; ''saa 21:40 agace kari hagati y''ibice bya 3 na 4 by''urugomero kageze ku bwinshi bwo guhagarara bakorana abitabiriye bazamura amaboko'' ni inyandiko ikoreshwa.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_6, '6.2', 'Post-Event Review and Learning from Near-Misses', 'Isuzuma Nyuma y''Ibirori no Kwiga ku Byari Hafi Kubaho', 'text', 'The review exists to change a control, not to identify a person to blame, because a review perceived as blame-seeking produces defensive accounts and destroys the information it depends on. It asks four questions: what was supposed to happen, what actually happened, where did they diverge, and which control was absent, poorly designed, or present but not followed. Near-misses must be reviewed with the same rigour as actual incidents — a queue that almost exceeded safe capacity contains exactly the same lesson as one that did, at no human cost, and in crowd safety the near-miss is usually the only warning you will get before the incident.', 'Isuzuma ririho kugira ngo hahinduke igenzura, atari ukumenya umuntu wo guhana, kuko isuzuma rifatwa nk''irishaka guhana ritanga ibisobanuro byo kwirwanaho kandi rigasenya amakuru rishingiyeho. Ryibaza ibibazo bine: ni iki cyagombye kuba, ni iki cyabaye koko, ni hehe byatandukaniye, kandi ni irihe genzura ritari rihari, ryateguwe nabi, cyangwa ryari rihari ariko ntirikurikizwe. Ibyari hafi kubaho bigomba gusuzumwa umurava umwe n''ibyabaye koko — umurongo wari hafi kurenga umubare w''umutekano ukubiyemo isomo rimwe n''uwarengeje, nta gihombo cy''ubuzima, kandi mu mutekano w''imbaga ikintu cyari hafi kubaho akenshi ni cyo burira rwonyine uzabona mbere y''ikibazo.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_6, '6.3', 'Documentation, Capacity Records and Legal Exposure', 'Inyandiko, Inyandiko z''Umubare n''Ibyago by''Amategeko', 'text', 'Crowd safety generates specific legal exposure because capacity limits are usually licensed and breaching one transfers liability directly. The records that matter are: the calculated safe capacity per zone and the basis of the calculation; the monitoring log showing counts or density observations through the event; the decision log recording when a trigger was reached and what action followed; and the incident and near-miss reports. Retain these for the period the regulation requires. An organisation that operated safely but recorded nothing is in a far weaker position after an inquiry than one that had a problem and documented its response fully.', 'Umutekano w''imbaga utanga ibyago byihariye by''amategeko kuko imipaka y''umubare akenshi igengwa n''impushya kandi kuyirenga bwohereza inshingano mu buryo butaziguye. Inyandiko zifite akamaro ni izi: umubare w''umutekano wabazwe kuri buri gace n''ishingiro ry''ibarwa; igitabo cy''ukurikirana cyerekana imibare cyangwa ibyabonetse ku bwinshi mu gihe cy''ibirori; igitabo cy''ibyemezo cyandika igihe urwego rutera cyagerwaho n''igikorwa cyakurikiyeho; na raporo z''ibibazo n''iz''ibyari hafi kubaho. Bika izi mu gihe amabwiriza asaba. Ikigo cyakoze mu mutekano ariko ntikandike ikintu kiri mu mwanya mubi cyane nyuma y''iperereza kurusha icyagize ikibazo kikandika igisubizo cyacyo cyuzuye.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_6, '6.4', 'Ethics and Professional Conduct in Crowd Work', 'Ubunyangamugayo n''Imyitwarire y''Umwuga mu Kazi k''Imbaga', 'text', 'Crowd safety officers work with thousands of members of the public, almost all of whom have done nothing wrong. Treat every attendee equally regardless of appearance, nationality, gender or perceived status. Never use position for personal benefit or preferential access. Apply density and capacity limits to everyone, including where an organiser or a senior person requests an exception, because a capacity limit relaxed once is a limit that no longer exists. Report honestly even where the report is inconvenient — an officer who under-reports a density condition to avoid stopping an event has removed the only warning the system had. Silence about a colleague''s serious lapse in this field is participation.', 'Abakozi b''umutekano w''imbaga bakorana n''abantu ibihumbi, hafi bose nta cyo bakoze. Fata buri witabiriye kimwe utitaye ku ko agaragara, igihugu, igitsina cyangwa urwego rukekwa. Ntukigere ukoresha umwanya wawe ku nyungu zawe cyangwa ku kwinjira kw''umwihariko. Kurikiza imipaka y''ubwinshi n''umubare kuri buri wese, harimo n''aho utegura cyangwa umuntu ukomeye asaba ko harengwa, kuko umupaka w''umubare wagabanuwe rimwe uba umupaka utakiriho. Tanga raporo z''ukuri n''aho raporo idashimishije — umukozi ugabanya raporo ku bwinshi kugira ngo yirinde guhagarika ibirori aba yakuyeho iburira rwonyine sisitemu yari ifite. Guceceka ku kosa rikomeye rya mugenzi wawe muri uru rwego ni ukugira uruhare.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_102_6, '6.5', 'Continuous Improvement and Professional Development', 'Gukomeza Kunoza n''Iterambere ry''Umwuga', 'text', 'Crowd safety is a specialised and consistently in-demand competency, precisely because failure is severe, irreversible and highly public while success is invisible. Development directions include crowd safety supervision, event safety officer roles, venue safety management, and consultancy in capacity and flow design. Recognised crowd safety and event safety qualifications, first aid certification and experience across event types all improve mobility substantially. The strongest development habit is documentation: keep your site surveys, capacity calculations, crowd plans and post-event reviews, because a portfolio of real analysis is what distinguishes a candidate from someone who can only state how many events they have worked.', 'Umutekano w''imbaga ni ubumenyi bwihariye kandi buhora bukenewe, kubera ko gutsindwa ari bikomeye, bidasubirwaho kandi bigaragara cyane mu gihe gutsinda kutagaragara. Icyerekezo cy''iterambere kirimo ubuyobozi bw''umutekano w''imbaga, imirimo y''ushinzwe umutekano w''ibirori, imicungire y''umutekano w''ahantu, n''ubujyanama mu kubara umubare n''igenamiterere ry''imigendekere. Ibyemezo byemewe by''umutekano w''imbaga n''ubw''ibirori, icyemezo cy''ubufasha bwa mbere n''uburambe mu bwoko butandukanye bw''ibirori byose byongera cyane ubushobozi bwo kwimuka. Umuco ukomeye w''iterambere ni inyandiko: bika amasuzuma yawe y''ahantu, imibare y''ubushobozi, gahunda z''imbaga n''amasuzuma nyuma y''ibirori, kuko ububiko bw''isesengura nyaryo ari bwo butandukanya ukandida n''ushobora kuvuga gusa umubare w''ibirori yakoreye.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-102', m_KG_102_6, 'Quiz — Review, Documentation and Professional Standards', 'Ikizamini — Isuzuma, Inyandiko n''Amabwiriza y''Umwuga', 'quiz', 70, 6)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why do crowd incident reports frequently become evidence?', 'Kuki raporo z''ibibazo by''imbaga akenshi ziba ibimenyetso?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Crowd incidents attract licensing reviews, insurance claims and legal proceedings', 'Ibibazo by''imbaga bikurura isuzuma ry''impushya, ibirego by''ubwishingizi n''imanza', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Above roughly five persons per square metre', 'Hejuru y''abantu batanu ho hafi kuri metero kare', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A crowd calibrates its alarm level against the most authoritative visible response', 'Imbaga ipima ubwoba bwayo ku gisubizo kigaragara gifite ubushobozi', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The lower of floor-area capacity and exit capacity', 'Umuke muri uw''ubutaka n''uw''ubushobozi bwo gusohoka', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why must near-misses be reviewed as rigorously as incidents?', 'Kuki ibyari hafi kubaho bigomba gusuzumwa nk''ibyabaye?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Otherwise every decision is left to individual judgement when judgement is hardest', 'Ubundi buri cyemezo gisigara ku bushishozi bwa buri wese igihe bugoye', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A staffed pressure release point — enclosure with no release causes crush injury', 'Ahantu ho kurekura igitutu hafite abakozi — gukikiza nta kurekura bitera ibikomere', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It transfers force into a mass that cannot comply and increases compression', 'Bwohereza imbaraga mu mbaga idashobora gukurikiza kandi byongera gukandana', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'In crowd safety the near-miss is usually the only warning before the incident', 'Mu mutekano w''imbaga ni cyo burira rwonyine mbere y''ikibazo', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What happens to a capacity limit that is relaxed once?', 'Ni iki kiba ku mupaka w''umubare wagabanuwe rimwe?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Arrival is gradual over hours; evacuation must occur within minutes', 'Kugera bibera buhoro mu masaha; kwimuka bikorwa mu minota', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Crowd incidents attract licensing reviews, insurance claims and legal proceedings', 'Ibibazo by''imbaga bikurura isuzuma ry''impushya, ibirego by''ubwishingizi n''imanza', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is a limit that no longer exists', 'Ni umupaka utakiriho', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Early separation rather than late intervention', 'Gutandukanya kare aho kugira icyo ukora bitinze', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What does under-reporting a density condition remove?', 'Kugabanya raporo ku bwinshi bikuraho iki?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A site walked in daylight tells you little about it at night in rain', 'Ahantu hagenzuwe ku manywa hatakubwira ku hantu mu ijoro imvura igwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The only warning the system had', 'Iburira rwonyine sisitemu yari ifite', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'In crowd safety the near-miss is usually the only warning before the incident', 'Mu mutekano w''imbaga ni cyo burira rwonyine mbere y''ikibazo', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A blocked crowd — momentum keeps arriving at a front that cannot move', 'Imbaga ibujijwe — umuvuduko ukomeza kugera imbere hadashobora kugenda', false, 4);
