do $$ declare m_KG_103_2 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-103') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-103', 2, 'Risk Assessment and Vulnerability Analysis', 'Isuzuma ry''Ibyago n''Isesengura ry''Intege Nke', 'This module covers how to identify where loss risk actually sits, how to measure it with evidence, and how to prioritise limited resources against the largest exposures.', 'Iki gice kigaruka ku buryo bwo kumenya aho ibyago by''igihombo biri by''ukuri, uko bipimwa hakoreshejwe ibimenyetso, n''uko umutungo muke utondekwa hakurikijwe ibyago binini.', 2)
  returning id into m_KG_103_2;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_2, '2.1', 'Identifying and Measuring Loss Risks', 'Kumenya no Gupima Ibyago by''Igihombo', 'text', 'Risk identification must be driven by data rather than impression, because management intuition about where loss occurs is frequently wrong in a specific and predictable direction: it over-weights visible external theft and under-weights invisible internal and operational loss. Useful data sources include stock variance by category and location, void and refund patterns by operator, cash discrepancies by shift, waste and write-off records, and delivery discrepancy reports. Each identified risk should then be measured on two axes: likelihood of occurrence and financial impact if it occurs. A risk that is frequent but trivial and a risk that is rare but catastrophic require entirely different responses, and conflating them produces a programme that addresses neither properly.', 'Kumenya ibyago bigomba gushingira ku makuru aho gushingira ku myumvire, kuko icyo ubuyobozi bwiyumvisha ku byerekeye aho igihombo kibera akenshi kibeshya mu buryo bwihariye kandi buteganywa: bwibanda cyane ku bujura bwo hanze bugaragara bukirengagiza igihombo cyo mu kigo n''icy''imikorere kitagaragara. Amasoko y''amakuru afite akamaro arimo itandukaniro ry''ibicuruzwa ku bwoko n''ahantu, uburyo bwo gukuraho no gusubiza amafaranga kuri buri mukozi, itandukaniro ry''amafaranga kuri buri kazi, inyandiko z''ibyapfushijwe ubusa n''ibyavanywemo, na raporo z''itandukaniro ry''ibyakiriwe. Buri kibazo cyamenyekanye kigomba noneho gupimwa ku birindiro bibiri: amahirwe yo kuba n''ingaruka z''amafaranga niba kibaye. Ikibazo gikunze kubaho ariko kitagira agaciro kanini n''ikibazo gikunze kubaho gake ariko kibi cyane bisaba ibisubizo bitandukanye burundu, kandi kubivanga bitanga gahunda idakemura na kimwe neza.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_2, '2.2', 'Conducting Risk Assessments in Retail and Corporate Environments', 'Gukora Isuzuma ry''Ibyago mu Maduka no mu Bigo', 'text', 'A retail assessment follows the goods: receiving bay, back store, sales floor, point of sale, and returns. Each transition point is a control point, and loss concentrates where accountability transfers between people without a verifying record. A corporate assessment follows different assets — cash handling, procurement, expense claims, payroll, IT access and confidential data — and here the highest-value exposures usually sit in procurement and payment approval rather than in physical stock. In both environments the assessment should be conducted by walking the process rather than reading the policy, because the documented procedure and the actual practice diverge in almost every organisation, and it is the actual practice that determines exposure.', 'Isuzuma ry''iduka rikurikira ibicuruzwa: aho byakirirwa, ububiko bwo hanyuma, aho bigurishirizwa, aho byishyurirwa, n''aho bisubizwa. Buri hantu bihindukira ni ahantu hagenzurwa, kandi igihombo cyibanda aho inshingano zihererekanywa hagati y''abantu nta nyandiko igenzura. Isuzuma ry''ikigo rikurikira undi mutungo — gucunga amafaranga, kugura, ibisabwa by''amafaranga yakoreshejwe, imishahara, kwinjira muri sisitemu n''amakuru y''ibanga — kandi hano ibyago by''agaciro kanini akenshi biri mu kugura no kwemeza kwishyura aho kuba mu bicuruzwa by''umubiri. Mu bihe byombi isuzuma rigomba gukorwa ugenda ukurikira inzira y''akazi aho gusoma politiki, kuko inzira yanditse n''ibikorwa by''ukuri bitandukana hafi mu kigo cyose, kandi ni ibikorwa by''ukuri bigena ibyago.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_2, '2.3', 'Vulnerability Mapping and Prioritisation', 'Gukora Ikarita y''Intege Nke no Kuzitondeka', 'text', 'A vulnerability map records every identified weakness against its location, the asset exposed, the likelihood band, the estimated financial impact, the existing control if any, and the recommended action with an owner and a date. Prioritisation then follows from likelihood multiplied by impact, moderated by cost of mitigation: a moderate risk that can be eliminated by a free procedural change outranks a slightly larger risk requiring significant capital. The output must be a document management can act on, which means it names owners and deadlines. A vulnerability assessment that identifies twenty weaknesses and assigns none of them to anyone has produced awareness without producing change.', 'Ikarita y''intege nke yandika buri ntege nke yamenyekanye hamwe n''aho iri, umutungo ushobora kwibasirwa, urwego rw''amahirwe yo kuba, ingaruka z''amafaranga ziteganyijwe, igenzura risanzweho niba rihari, n''igikorwa gisabwa hamwe n''uwagishinzwe n''itariki. Gutondeka noneho bikurikira amahirwe yo kuba bikubwe n''ingaruka, hakurikijwe n''ikiguzi cyo kubikemura: ikibazo cyo hagati gishobora gukurwaho n''impinduka y''inzira y''akazi itagira ikiguzi kiruta ikibazo kinini gato gisaba amafaranga menshi. Icyavuyemo kigomba kuba inyandiko ubuyobozi bushobora gukoraho, bivuze ko igena abashinzwe n''ibihe ntarengwa. Isuzuma ry''intege nke rimenya intege nke makumyabiri ritagira n''imwe rihereza umuntu riba ryatanze ubumenyi ritatanze impinduka.', 12, 3);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-103', m_KG_103_2, 'Quiz — Risk Assessment and Vulnerability Analysis', 'Ikizamini — Isuzuma ry''Ibyago n''Isesengura ry''Intege Nke', 'quiz', 70, 2)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'In which direction is management intuition about loss typically wrong?', 'Icyo ubuyobozi bwiyumvisha ku gihombo akenshi kibeshya mu buhe buryo?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It over-weights visible external theft, under-weights internal and operational loss', 'Cyibanda ku bujura bwo hanze bugaragara, kikirengagiza igihombo cyo mu kigo n''icy''imikorere', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Security asks who comes in; loss prevention asks where value leaves', 'Umutekano wibaza uwinjira; kwirinda igihombo kwibaza aho agaciro kagenda', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Twenty units', 'Ibintu makumyabiri', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A named owner and a deadline', 'Uwagishinzwe wagenwe n''igihe ntarengwa', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'On which two axes should a risk be measured?', 'Ni ku birindiro bibiri ki ikibazo kigomba gupimirwa?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A policy with no matching procedure', 'Politiki idafite inzira y''akazi ihuye na yo', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Unusual void rates, concentrated refunds, transactions just below authorisation threshold', 'Gukuraho bidasanzwe, gusubiza byibanze, ibikorwa biri munsi gato y''urwego rusaba uruhushya', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity', 'Amahirwe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Likelihood of occurrence and financial impact', 'Amahirwe yo kuba n''ingaruka z''amafaranga', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Where does loss concentrate in a retail process?', 'Igihombo cyibanda he mu nzira y''akazi y''iduka?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The control is effectively cancelled for everyone who observed it', 'Iryo genzura riba ryavanyweho kuri buri wese wabibonye', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Improved detection and reporting, not increased loss', 'Kumenya no gutanga amakuru byanoze, atari igihombo cyiyongereye', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Where accountability transfers between people without a verifying record', 'Aho inshingano zihererekanywa nta nyandiko igenzura', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that only works on known audit dates is not a control', 'Igenzura rikora gusa ku matariki azwi si igenzura', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What must every vulnerability map recommendation include?', 'Ni iki buri cyifuzo cy''ikarita y''intege nke kigomba kubamo?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It over-weights visible external theft, under-weights internal and operational loss', 'Cyibanda ku bujura bwo hanze bugaragara, kikirengagiza igihombo cyo mu kigo n''icy''imikorere', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A named owner and a deadline', 'Uwagishinzwe wagenwe n''igihe ntarengwa', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Financial impact and trend, not incident narrative', 'Ingaruka z''amafaranga n''icyerekezo, atari inkuru y''ibibazo', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Internal loss', 'Igihombo cyo mu kigo', false, 4);
end $$;
do $$ declare m_KG_103_3 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-103') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-103', 3, 'Designing a Loss Prevention Program', 'Gutegura Gahunda yo Kwirinda Igihombo', 'This module covers turning assessment findings into a functioning programme: written policy, operational integration, and the technology that supports both.', 'Iki gice kigaruka ku guhindura ibyavuye mu isuzuma gahunda ikora: politiki yanditse, guhuza n''ibikorwa, n''ikoranabuhanga rishyigikira byombi.', 3)
  returning id into m_KG_103_3;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_3, '3.1', 'Establishing Policies and Procedures', 'Gushyiraho Politiki n''Inzira z''Akazi', 'text', 'A loss prevention policy states what the organisation requires; a procedure states exactly how a person performs it. Both are necessary, and the most common failure is a policy without a matching procedure, which produces a rule nobody knows how to follow. Effective procedures are specific, assign responsibility by role rather than by name, define what evidence is created at each step, and are short enough to be read. Critically, a procedure must be operationally realistic: a control requiring two managers to authorise every refund will be bypassed within a week in a store that has one manager on shift, and a bypassed control is worse than none because it creates false assurance.', 'Politiki yo kwirinda igihombo ivuga icyo ikigo gisaba; inzira y''akazi ivuga neza uko umuntu agikora. Byombi ni ngombwa, kandi ikosa rikunze kubaho ni politiki idafite inzira y''akazi ihuye na yo, bigatanga itegeko nta muntu uzi uko rikurikizwa. Inzira z''akazi zikora ni izisobanutse, zihereza inshingano ku murimo aho kuzihereza ku izina, zigena ikimenyetso gikorwa kuri buri ntambwe, kandi zikaba ngufi ku buryo zisomwa. Icy''ingenzi, inzira y''akazi igomba kuba ishoboka mu bikorwa: igenzura risaba abayobozi babiri kwemeza buri gusubiza amafaranga rizacikwa mu cyumweru mu iduka rifite umuyobozi umwe ku kazi, kandi igenzura ryacitswe ni ribi kurusha kutagira na rimwe kuko ritanga icyizere cy''ibinyoma.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_3, '3.2', 'Integration with Security and Operations Departments', 'Guhuza n''Amashami y''Umutekano n''Ibikorwa', 'text', 'Loss prevention cannot function as an isolated department, because it owns almost none of the processes that generate loss. Stock accuracy belongs to operations, hiring and discipline belong to HR, system access belongs to IT, and payment authorisation belongs to finance. The loss prevention function therefore succeeds through influence and evidence rather than authority: it presents data showing where loss occurs, proposes a control the owning department can realistically implement, and reports the measured result back. Where loss prevention is positioned as an enforcement body policing colleagues, cooperation collapses and information stops flowing — which removes the very early warning the function depends on.', 'Kwirinda igihombo ntibishobora gukora nk''ishami ryigunze, kuko hafi nta nzira z''akazi zitera igihombo bifite. Ukuri kw''ibicuruzwa ni ukw''ibikorwa, gushaka abakozi n''ibihano ni ibyo abakozi, kwinjira muri sisitemu ni ibya IT, kandi kwemeza kwishyura ni iby''imari. Umurimo wo kwirinda igihombo rero utsinda binyuze mu kwemeza no ku bimenyetso aho kunyura ku butware: utanga amakuru agaragaza aho igihombo kibera, ugatanga igenzura ishami ribifite rishobora gushyira mu bikorwa koko, hanyuma ukagaruka ugatanga raporo y''ibyavuyemo byapimwe. Aho kwirinda igihombo bishyizwe nk''urwego rukurikirana bagenzi babo, ubufatanye burasenyuka kandi amakuru ntakomeza kugera — bigakuraho iburira rya kare umurimo ushingiyeho.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_3, '3.3', 'Technology and Systems Supporting Loss Prevention', 'Ikoranabuhanga na Sisitemu Bishyigikira Kwirinda Igihombo', 'text', 'Technology supports a loss prevention programme but never substitutes for it. CCTV provides evidence and some deterrence but detects nothing on its own unless someone reviews it against a trigger. Electronic article surveillance reduces casual external theft but has no effect on internal or operational loss. Exception reporting from the point-of-sale system is frequently the highest-value tool available, because it flags statistical outliers — an operator with an unusual void rate, refunds concentrated in one shift, transactions repeatedly just below an authorisation threshold — that no amount of camera watching would reveal. Access control logs and inventory management systems complete the picture. The principle is that technology should generate a trigger for human attention, not replace it.', 'Ikoranabuhanga rishyigikira gahunda yo kwirinda igihombo ariko ntirisimbura na rimwe. Kamera zitanga ibimenyetso n''ubukumira buke ariko ubwazo ntizimenya ikintu keretse hari umuntu uzireba akurikije ikimenyetso. Ibikoresho by''ikoranabuhanga ku bicuruzwa bigabanya ubujura bworoheje bwo hanze ariko nta ngaruka bifite ku gihombo cyo mu kigo cyangwa icy''imikorere. Raporo z''ibidasanzwe zivuye muri sisitemu y''aho bishyurirwa akenshi ni igikoresho gifite agaciro kanini kuko zigaragaza ibidasanzwe mu mibare — umukozi ufite ijanisha ridasanzwe ryo gukuraho, gusubiza amafaranga byibanze ku kazi kamwe, ibikorwa bikunze kuba munsi gato y''urwego rusaba uruhushya — ibyo kureba kamera kose kutabasha kugaragaza. Inyandiko z''abinjira na sisitemu zicunga ibicuruzwa byuzuza ishusho. Ihame ni uko ikoranabuhanga rigomba gutanga ikimenyetso cyo gukurura ubwitonzi bw''umuntu, atari kubusimbura.', 12, 3);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-103', m_KG_103_3, 'Quiz — Designing a Loss Prevention Program', 'Ikizamini — Gutegura Gahunda yo Kwirinda Igihombo', 'quiz', 70, 3)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What is the most common policy failure in a loss prevention programme?', 'Ni ikihe kosa rikunze kubaho muri politiki ya gahunda yo kwirinda igihombo?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A policy with no matching procedure', 'Politiki idafite inzira y''akazi ihuye na yo', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Security asks who comes in; loss prevention asks where value leaves', 'Umutekano wibaza uwinjira; kwirinda igihombo kwibaza aho agaciro kagenda', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Twenty units', 'Ibintu makumyabiri', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Where accountability transfers between people without a verifying record', 'Aho inshingano zihererekanywa nta nyandiko igenzura', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why is a bypassed control worse than no control?', 'Kuki igenzura ryacitswe ari ribi kurusha kutagira igenzura?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A named owner and a deadline', 'Uwagishinzwe wagenwe n''igihe ntarengwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Unusual void rates, concentrated refunds, transactions just below authorisation threshold', 'Gukuraho bidasanzwe, gusubiza byibanze, ibikorwa biri munsi gato y''urwego rusaba uruhushya', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity', 'Amahirwe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It creates false assurance', 'Ritanga icyizere cy''ibinyoma', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'How does the loss prevention function succeed with other departments?', 'Umurimo wo kwirinda igihombo utsinda ute n''ayandi mashami?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The control is effectively cancelled for everyone who observed it', 'Iryo genzura riba ryavanyweho kuri buri wese wabibonye', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Improved detection and reporting, not increased loss', 'Kumenya no gutanga amakuru byanoze, atari igihombo cyiyongereye', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Through evidence and influence, not authority', 'Binyuze ku bimenyetso no kwemeza, atari ku butware', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that only works on known audit dates is not a control', 'Igenzura rikora gusa ku matariki azwi si igenzura', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Name three statistical outliers POS exception reporting can flag.', 'Vuga ibintu bitatu bidasanzwe raporo z''aho bishyurirwa zishobora kugaragaza.', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It over-weights visible external theft, under-weights internal and operational loss', 'Cyibanda ku bujura bwo hanze bugaragara, kikirengagiza igihombo cyo mu kigo n''icy''imikorere', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Unusual void rates, concentrated refunds, transactions just below authorisation threshold', 'Gukuraho bidasanzwe, gusubiza byibanze, ibikorwa biri munsi gato y''urwego rusaba uruhushya', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Financial impact and trend, not incident narrative', 'Ingaruka z''amafaranga n''icyerekezo, atari inkuru y''ibibazo', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Internal loss', 'Igihombo cyo mu kigo', false, 4);
end $$;
do $$ declare m_KG_103_4 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-103') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-103', 4, 'Investigations and Internal Controls', 'Iperereza n''Ibigenzura by''Imbere', 'This module covers how to investigate a suspected loss lawfully and professionally, how to detect fraud, and how internal controls and audits reduce opportunity before an investigation is ever needed.', 'Iki gice kigaruka ku buryo bwo gukora iperereza ku gihombo gikekwa mu mategeko no mu bunyamwuga, uko uburiganya bumenyekana, n''uko ibigenzura by''imbere n''amagenzura bigabanya amahirwe mbere y''uko iperereza rikenerwa.', 4)
  returning id into m_KG_103_4;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_4, '4.1', 'Methods of Investigation (Interviews, Surveillance, Data Analysis)', 'Uburyo bwo Gukora Iperereza (Kubaza, Gukurikirana, Gusesengura Amakuru)', 'text', 'Most investigations begin with data rather than suspicion, because data identifies where to look without prejudging who is responsible. Analysis of transaction records, stock variances and access logs establishes a pattern; surveillance is then used to test a specific hypothesis over a defined period rather than deployed indefinitely in the hope of seeing something. Interviews are conducted last, once the factual position is established, and must be conducted lawfully: the person is not detained, is not threatened or induced, is told the purpose, and their account is recorded accurately including anything that contradicts the investigator''s theory. An investigation that starts by confronting a suspect usually contaminates the evidence and often collapses.', 'Amaperereza menshi atangirira ku makuru aho gutangirira ku gukeka, kuko amakuru agaragaza aho kureba atabanje gucira urubanza uwo aricyo. Isesengura ry''inyandiko z''ibikorwa, itandukaniro ry''ibicuruzwa n''inyandiko z''abinjira rishyiraho uburyo bugaragara; gukurikirana noneho bikoreshwa mu gupima igitekerezo cyihariye mu gihe kigenwe aho gukoreshwa igihe kitagira urugero wiringiye kubona ikintu. Kubaza bikorwa nyuma, iyo uko ibintu bimeze bimaze kumenyekana, kandi bigomba gukorwa mu mategeko: umuntu ntafungwa, ntatotezwa cyangwa ngo ashukwe, abwirwa impamvu, kandi ibyo avuze byandikwa neza harimo n''ibivuguruza igitekerezo cy''umushakashatsi. Iperereza ritangira rihanganye n''ukekwa akenshi ryanduza ibimenyetso kandi kenshi rirasenyuka.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_4, '4.2', 'Fraud Detection and Prevention Techniques', 'Uburyo bwo Kumenya no Kwirinda Uburiganya', 'text', 'Fraud generally requires three conditions together: opportunity created by weak control, pressure on the individual, and a rationalisation that allows them to justify it. Loss prevention can rarely influence pressure or rationalisation, but it can systematically remove opportunity, which is why control design is the primary preventive tool. Common indicators include an employee who refuses to take leave or resists rotation because a scheme would be discovered in their absence, transactions structured just below an authorisation threshold, suppliers with no verifiable physical address, duplicate invoice numbers, and unexplained lifestyle change. Any single indicator proves nothing; a cluster of them justifies a discreet review.', 'Uburiganya muri rusange busaba ibintu bitatu bihuriye: amahirwe yatewe n''igenzura ridakomeye, igitutu ku muntu, n''impamvu yiyemeza atuma abyemera. Kwirinda igihombo gake bishobora guhindura igitutu cyangwa impamvu yiyemeza, ariko bishobora gukuraho amahirwe mu buryo buteguye, ni yo mpamvu igenamiterere ry''ibigenzura ari igikoresho cy''ibanze cyo kwirinda. Ibimenyetso bisanzwe birimo umukozi wanga gufata ikiruhuko cyangwa arwanya guhinduranywa kuko ubugambanyi bwe bwamenyekana adahari, ibikorwa byateguwe munsi gato y''urwego rusaba uruhushya, abatanga ibicuruzwa badafite aderesi ishobora kugenzurwa, nimero z''inyemezabwishyu zisubiwemo, n''ihinduka ry''imibereho ridasobanutse. Ikimenyetso kimwe nta cyo kigaragaza; ihuriro ry''ibimenyetso byinshi rituma haba isuzuma mu bwiherero.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_4, '4.3', 'Internal Audits and Compliance Programs', 'Amagenzura y''Imbere na Gahunda zo Kubahiriza Amategeko', 'text', 'Internal audit is the mechanism that verifies whether designed controls are actually operating, as distinct from whether they exist on paper. An audit programme should combine scheduled reviews with unannounced spot checks, since a control that only performs correctly on known audit dates is not a control. Core internal controls to verify include segregation of duties, dual authorisation above defined thresholds, mandatory leave and rotation in sensitive roles, physical stock counts independent of the person responsible for the stock, and reconciliation performed by someone who did not process the original transaction. Audit findings must be tracked to closure with an owner and date, because an unclosed finding is a documented vulnerability the organisation has knowingly accepted.', 'Igenzura ry''imbere ni uburyo bwemeza niba ibigenzura byateguwe bikora koko, bitandukanye no kuba biriho ku rupapuro. Gahunda y''igenzura igomba guhuza amagenzura ateganyijwe n''amagenzura y''ako kanya atamenyeshejwe, kuko igenzura rikora neza gusa ku matariki y''igenzura azwi atari igenzura. Ibigenzura by''imbere by''ibanze bigomba kugenzurwa birimo gutandukanya inshingano, uruhushya rw''abantu babiri hejuru y''urwego rugenwe, ikiruhuko gitegetswe no guhinduranya mu mirimo y''ibanga, kubara ibicuruzwa mu buryo bwigenga ku muntu ubishinzwe, no kwemeza imibare bikorwa n''umuntu utakoze igikorwa cya mbere. Ibyavuye mu igenzura bigomba gukurikiranwa kugeza bikemutse hamwe n''uwabishinzwe n''itariki, kuko ikibazo kitakemutse ari intege nke yanditse ikigo cyemeye kibizi.', 12, 3);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-103', m_KG_103_4, 'Quiz — Investigations and Internal Controls', 'Ikizamini — Iperereza n''Ibigenzura by''Imbere', 'quiz', 70, 4)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why should an investigation start with data rather than confronting a suspect?', 'Kuki iperereza rigomba gutangirira ku makuru aho guhangana n''ukekwa?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Data shows where to look without prejudging; early confrontation contaminates evidence', 'Amakuru agaragaza aho kureba utaciriye urubanza; guhangana kare byanduza ibimenyetso', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Security asks who comes in; loss prevention asks where value leaves', 'Umutekano wibaza uwinjira; kwirinda igihombo kwibaza aho agaciro kagenda', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Twenty units', 'Ibintu makumyabiri', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Where accountability transfers between people without a verifying record', 'Aho inshingano zihererekanywa nta nyandiko igenzura', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What three conditions does fraud generally require?', 'Ni ibihe bintu bitatu uburiganya busaba muri rusange?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A named owner and a deadline', 'Uwagishinzwe wagenwe n''igihe ntarengwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Through evidence and influence, not authority', 'Binyuze ku bimenyetso no kwemeza, atari ku butware', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity', 'Amahirwe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity, pressure and rationalisation', 'Amahirwe, igitutu n''impamvu yiyemeza', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Which of the three can loss prevention systematically remove?', 'Ni ikihe muri ibyo bitatu kwirinda igihombo bishobora gukuraho mu buryo buteguye?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The control is effectively cancelled for everyone who observed it', 'Iryo genzura riba ryavanyweho kuri buri wese wabibonye', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Improved detection and reporting, not increased loss', 'Kumenya no gutanga amakuru byanoze, atari igihombo cyiyongereye', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity', 'Amahirwe', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that only works on known audit dates is not a control', 'Igenzura rikora gusa ku matariki azwi si igenzura', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why must audits include unannounced spot checks?', 'Kuki amagenzura agomba kubamo amagenzura y''ako kanya atamenyeshejwe?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It over-weights visible external theft, under-weights internal and operational loss', 'Cyibanda ku bujura bwo hanze bugaragara, kikirengagiza igihombo cyo mu kigo n''icy''imikorere', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that only works on known audit dates is not a control', 'Igenzura rikora gusa ku matariki azwi si igenzura', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Financial impact and trend, not incident narrative', 'Ingaruka z''amafaranga n''icyerekezo, atari inkuru y''ibibazo', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Internal loss', 'Igihombo cyo mu kigo', false, 4);
end $$;
do $$ declare m_KG_103_5 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-103') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-103', 5, 'Employee Awareness and Ethical Culture', 'Ubumenyi bw''Abakozi n''Umuco w''Ubunyangamugayo', 'This module covers the human side of loss prevention: building a workforce that notices and reports, managing insider risk fairly, and creating reporting channels people actually use.', 'Iki gice kigaruka ku ruhande rw''abantu mu kwirinda igihombo: kubaka abakozi babona kandi batanga amakuru, gucunga akaga gaturuka imbere mu butabera, no gushyiraho inzira zo gutanga amakuru abantu bakoresha koko.', 5)
  returning id into m_KG_103_5;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_5, '5.1', 'Building a Security-Conscious Workforce', 'Kubaka Abakozi Bafite Ubumenyi bw''Umutekano', 'text', 'Employees are the largest detection network any organisation has, because they see the process daily and know immediately when something is irregular. Converting that into reporting requires three things. Staff must know what to report, which means training on specific indicators rather than a general instruction to be vigilant. They must know how to report, through a channel that is quick and does not require going through the person they may be reporting about. And they must believe reporting is safe and worthwhile, which depends entirely on what happened to the last person who reported. Where an organisation has a history of ignoring reports or exposing reporters, no amount of poster campaigning will restore the flow of information.', 'Abakozi ni yo mbuga nini yo kumenya ikigo cyose gifite, kuko babona inzira y''akazi buri munsi kandi bagahita bamenya igihe hari ikitagenda neza. Guhindura ibyo bikaba gutanga amakuru bisaba ibintu bitatu. Abakozi bagomba kumenya icyo batanga, bivuze amahugurwa ku bimenyetso byihariye aho gutanga itegeko rusange ryo kuba maso. Bagomba kumenya uko batanga amakuru, binyuze mu nzira yihuta itabasaba kunyura ku muntu bashobora kuba batanga amakuru kuri we. Kandi bagomba kwizera ko gutanga amakuru bifite umutekano kandi bifite akamaro, biterwa burundu n''ibyabaye ku muntu waheruka gutanga amakuru. Aho ikigo gifite amateka yo kwirengagiza amakuru cyangwa kugaragaza abayatanze, nta bikorwa byo kwamamaza byashobora kugarura amakuru.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_5, '5.2', 'Managing Insider Threats', 'Gucunga Akaga Gaturuka Imbere', 'text', 'An insider threat is a person with legitimate access acting against the organisation''s interests, either deliberately or through negligence. Management begins before employment with proportionate screening, continues through access rights that are granted by role and reviewed when a role changes, and ends with a leaver process that removes access on the day of departure rather than weeks later. The most common insider vulnerability in practice is accumulated access: an employee who has moved through three roles and retained the permissions of all three. Insider risk must be managed fairly and without creating a culture of suspicion, because treating an entire workforce as suspects destroys the reporting culture the programme depends on.', 'Akaga gaturuka imbere ni umuntu wemerewe kwinjira ukora mu buryo bubangamiye inyungu z''ikigo, abishaka cyangwa yirengagije. Kugacunga bitangira mbere y''akazi hakoreshejwe isuzuma rihuye, bigakomeza binyuze ku burenganzira bwo kwinjira butangwa hakurikijwe umurimo kandi bugasuzumwa igihe umurimo uhindutse, kandi bikarangira n''inzira y''usezera ikuraho uburenganzira ku munsi agiye aho kuba nyuma y''ibyumweru. Intege nke ikunze kubaho mu bikorwa ni uburenganzira bwiyongereye: umukozi wanyuze mu mirimo itatu akaguma n''uburenganzira bw''iyo mirimo yose uko ari itatu. Akaga gaturuka imbere kagomba gucungwa mu butabera kandi hatabaye umuco wo gukekana, kuko gufata abakozi bose nk''abakekwa bisenya umuco wo gutanga amakuru gahunda ishingiyeho.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_5, '5.3', 'Ethics, Integrity and Confidential Reporting Systems', 'Ubunyangamugayo, Ubudahemuka na Sisitemu zo Gutanga Amakuru mu Ibanga', 'text', 'A confidential reporting channel — a whistleblowing line, secure email or independent third-party service — consistently surfaces more internal loss than any technical control, but only if three conditions hold: reports are genuinely confidential, they are visibly acted upon, and reporters are protected from retaliation in fact rather than only in policy. Ethical culture is set from the top: where senior staff visibly follow the same controls as everyone else, compliance is normal; where a manager is exempted from a control, the control is effectively cancelled for everyone who observed it. Publishing anonymised outcomes — that reports were received, investigated and resolved — sustains confidence without breaching confidentiality.', 'Inzira y''ibanga yo gutanga amakuru — umurongo w''abatanga amakuru, imeyili ifite umutekano cyangwa serivisi yigenga y''undi muntu — buri gihe igaragaza igihombo cyo mu kigo kirenze icyo igenzura ry''ikoranabuhanga rigaragaza, ariko gusa iyo ibintu bitatu bihari: amakuru aba ari ibanga koko, hagaragara ko hakozweho, kandi abayatanze barinzwe guhorerwa mu bikorwa atari muri politiki gusa. Umuco w''ubunyangamugayo ushyirwaho uhereye hejuru: aho abakozi bakuru bagaragara bakurikiza ibigenzura bimwe n''abandi bose, kubahiriza biba bisanzwe; aho umuyobozi asonewe igenzura, iryo genzura riba ryavanyweho kuri buri wese wabibonye. Gutangaza ibyavuyemo bidasobanura abantu — ko amakuru yakiriwe, akorwaho iperereza kandi agakemuka — bigumisha icyizere hatarengwa ibanga.', 12, 3);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-103', m_KG_103_5, 'Quiz — Employee Awareness and Ethical Culture', 'Ikizamini — Ubumenyi bw''Abakozi n''Umuco w''Ubunyangamugayo', 'quiz', 70, 5)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What three things must staff have in order to report effectively?', 'Ni ibihe bintu bitatu abakozi bagomba kugira kugira ngo batange amakuru neza?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Know what to report, know how, and believe it is safe and worthwhile', 'Kumenya icyo batanga, uko batanga, no kwizera ko bifite umutekano n''akamaro', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Security asks who comes in; loss prevention asks where value leaves', 'Umutekano wibaza uwinjira; kwirinda igihombo kwibaza aho agaciro kagenda', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Twenty units', 'Ibintu makumyabiri', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Where accountability transfers between people without a verifying record', 'Aho inshingano zihererekanywa nta nyandiko igenzura', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What is the most common insider vulnerability in practice?', 'Ni iyihe ntege nke ikunze kubaho ku kaga gaturuka imbere?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A named owner and a deadline', 'Uwagishinzwe wagenwe n''igihe ntarengwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Through evidence and influence, not authority', 'Binyuze ku bimenyetso no kwemeza, atari ku butware', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity, pressure and rationalisation', 'Amahirwe, igitutu n''impamvu yiyemeza', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Accumulated access retained across role changes', 'Uburenganzira bwiyongereye buguma nyuma y''impinduka z''imirimo', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What happens when a manager is exempted from a control?', 'Ni iki kibaho iyo umuyobozi asonewe igenzura?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Accumulated access retained across role changes', 'Uburenganzira bwiyongereye buguma nyuma y''impinduka z''imirimo', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Improved detection and reporting, not increased loss', 'Kumenya no gutanga amakuru byanoze, atari igihombo cyiyongereye', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The control is effectively cancelled for everyone who observed it', 'Iryo genzura riba ryavanyweho kuri buri wese wabibonye', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity', 'Amahirwe', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Which three conditions make a confidential reporting channel work?', 'Ni ibihe bintu bitatu bituma inzira y''ibanga yo gutanga amakuru ikora?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It over-weights visible external theft, under-weights internal and operational loss', 'Cyibanda ku bujura bwo hanze bugaragara, kikirengagiza igihombo cyo mu kigo n''icy''imikorere', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Genuine confidentiality, visible action, and real protection from retaliation', 'Ibanga nyakuri, igikorwa kigaragara, no kurindwa guhorerwa mu bikorwa', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Financial impact and trend, not incident narrative', 'Ingaruka z''amafaranga n''icyerekezo, atari inkuru y''ibibazo', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Internal loss', 'Igihombo cyo mu kigo', false, 4);
end $$;
do $$ declare m_KG_103_6 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-103') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-103', 6, 'Measuring Effectiveness and Continuous Improvement', 'Gupima Imikorere no Gukomeza Kunoza', 'This module covers how to prove the programme is working, how to report it credibly to management, and how to convert findings into sustained improvement.', 'Iki gice kigaruka ku buryo bwo kwerekana ko gahunda ikora, uko bitangwa raporo ku buyobozi mu buryo bwizewe, n''uko ibyavuyemo bihindurwa impinduka irambye.', 6)
  returning id into m_KG_103_6;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_6, '6.1', 'Key Performance Indicators (KPIs) in Loss Prevention', 'Ibipimo by''Imikorere mu Kwirinda Igihombo', 'text', 'A loss prevention programme must be measurable or it cannot be defended in a budget discussion. The primary KPI is shrinkage as a percentage of sales or turnover, tracked by location and by category so that a rising figure can be traced to a source rather than merely observed. Supporting indicators include recovery value, number of cases opened and closed, average time to close, audit findings raised and closed, percentage of staff trained, and reports received through the confidential channel. Note that some KPIs move in counter-intuitive directions early on: a rise in reported incidents in the first months of a programme usually indicates improved detection and reporting rather than increased loss, and management should be briefed on this before the figures appear.', 'Gahunda yo kwirinda igihombo igomba gushobora gupimwa cyangwa ntizashobora kwiregura mu biganiro by''ingengo y''imari. Igipimo cy''ibanze ni igabanuka ry''ibicuruzwa ku ijanisha ry''ibyagurishijwe cyangwa ibyinjira, gikurikiranwa ku hantu no ku bwoko kugira ngo umubare wiyongera ushobore gukurikiranwa ku nkomoko aho kubonwa gusa. Ibipimo bishyigikira birimo agaciro k''ibyagaruwe, umubare w''ibibazo byafunguwe n''ibyafunzwe, igihe cyo gufunga, ibyavuye mu igenzura byatanzwe n''ibyakemutse, ijanisha ry''abakozi bahuguwe, n''amakuru yakiriwe binyuze mu nzira y''ibanga. Menya ko ibipimo bimwe bigenda mu buryo butunguranye mu ntangiriro: kwiyongera kw''ibibazo bitangwa mu mezi ya mbere ya gahunda akenshi bigaragaza kunoga kwo kumenya no gutanga amakuru aho kugaragaza kwiyongera kw''igihombo, kandi ubuyobozi bugomba kubimenyeshwa mbere y''uko iyo mibare igaragara.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_6, '6.2', 'Reporting and Data Analytics', 'Gutanga Raporo no Gusesengura Amakuru', 'text', 'Reporting to management should lead with financial impact and trend, not with incident narrative, because that is the language in which resourcing decisions are made. A strong report states the shrinkage figure against target, the direction of travel, the two or three largest contributing sources, the action taken, and what is required next with a cost and an expected return. Analytics should compare like with like — location against location, period against period, operator against peer group — since an absolute figure in isolation tells management nothing about whether performance is acceptable. Present exceptions rather than exhaustive data: a report nobody finishes reading has communicated nothing.', 'Gutanga raporo ku buyobozi bigomba gutangirira ku ngaruka z''amafaranga n''icyerekezo, atari ku nkuru y''ibibazo, kuko ari rwo rurimi ibyemezo by''umutungo bifatirwamo. Raporo ikomeye ivuga umubare w''igabanuka ugereranyije n''intego, icyerekezo bigenda, inkomoko ebyiri cyangwa eshatu nini zibitera, igikorwa cyakozwe, n''ibisabwa bikurikira hamwe n''ikiguzi n''inyungu iteganyijwe. Isesengura rigomba kugereranya ibisa — ahantu n''ahandi, igihe n''ikindi, umukozi n''itsinda asa na ryo — kuko umubare wonyine nta cyo ubwira ubuyobozi ku byerekeye niba imikorere yemewe. Garagaza ibidasanzwe aho gutanga amakuru yose: raporo nta muntu uyisoza nta cyo yatanze.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_103_6, '6.3', 'Lessons Learned and Program Enhancement', 'Amasomo Yavuyemo no Kunoza Gahunda', 'text', 'Every closed case and every audit finding contains information about a control that failed, and the value of that information is realised only if it changes the control rather than merely punishing the individual. A structured lessons-learned review asks: what control should have prevented this, why did it not, was it absent, poorly designed, or present but not followed, and what specific change is now required with an owner and a date. A programme reviewed annually against changing risk — new store formats, new payment methods, new suppliers, new systems — remains effective; a programme designed once and left unchanged degrades steadily as the business around it changes.', 'Buri kibazo cyafunzwe na buri cyavuye mu igenzura kirimo amakuru ku igenzura ryananiranye, kandi agaciro k''ayo makuru kagerwaho gusa iyo ahinduye igenzura aho guhana umuntu gusa. Isuzuma riteguye ry''amasomo yavuyemo ryibaza: ni irihe genzura ryagombye kuba ryarabikumiye, kuki ritabikoze, ese ryari ridahari, ryateguwe nabi, cyangwa ryarahari ariko ntirikurikizwe, kandi ni iyihe mpinduka yihariye isabwa ubu hamwe n''uwayishinzwe n''itariki. Gahunda isuzumwa buri mwaka hakurikijwe ibyago bihinduka — uburyo bushya bw''amaduka, uburyo bushya bwo kwishyura, abatanga ibicuruzwa bashya, sisitemu nshya — iguma ikora; gahunda yateguwe rimwe igasigara itahindutse igenda inanirwa uko ubucuruzi bukikije bugenda buhinduka.', 12, 3);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-103', m_KG_103_6, 'Quiz — Measuring Effectiveness and Continuous Improvement', 'Ikizamini — Gupima Imikorere no Gukomeza Kunoza', 'quiz', 70, 6)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What is the primary KPI in loss prevention?', 'Ni ikihe gipimo cy''ibanze mu kwirinda igihombo?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Shrinkage as a percentage of sales, tracked by location and category', 'Igabanuka ku ijanisha ry''ibyagurishijwe, gikurikiranwa ku hantu no ku bwoko', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Security asks who comes in; loss prevention asks where value leaves', 'Umutekano wibaza uwinjira; kwirinda igihombo kwibaza aho agaciro kagenda', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Twenty units', 'Ibintu makumyabiri', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Where accountability transfers between people without a verifying record', 'Aho inshingano zihererekanywa nta nyandiko igenzura', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why might reported incidents rise in the first months of a programme?', 'Kuki ibibazo bitangwa bishobora kwiyongera mu mezi ya mbere ya gahunda?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A named owner and a deadline', 'Uwagishinzwe wagenwe n''igihe ntarengwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Through evidence and influence, not authority', 'Binyuze ku bimenyetso no kwemeza, atari ku butware', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity, pressure and rationalisation', 'Amahirwe, igitutu n''impamvu yiyemeza', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Improved detection and reporting, not increased loss', 'Kumenya no gutanga amakuru byanoze, atari igihombo cyiyongereye', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What should a management report lead with?', 'Raporo y''ubuyobozi igomba gutangirira ku iki?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Accumulated access retained across role changes', 'Uburenganzira bwiyongereye buguma nyuma y''impinduka z''imirimo', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Shrinkage as a percentage of sales, tracked by location and category', 'Igabanuka ku ijanisha ry''ibyagurishijwe, gikurikiranwa ku hantu no ku bwoko', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Financial impact and trend, not incident narrative', 'Ingaruka z''amafaranga n''icyerekezo, atari inkuru y''ibibazo', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Opportunity', 'Amahirwe', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What three questions does a lessons-learned review ask about a failed control?', 'Ni ibihe bibazo bitatu isuzuma ry''amasomo ryibaza ku igenzura ryananiranye?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It over-weights visible external theft, under-weights internal and operational loss', 'Cyibanda ku bujura bwo hanze bugaragara, kikirengagiza igihombo cyo mu kigo n''icy''imikorere', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Was it absent, poorly designed, or present but not followed?', 'Ese ryari ridahari, ryateguwe nabi, cyangwa ryarahari ariko ntirikurikizwe?', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Improved detection and reporting, not increased loss', 'Kumenya no gutanga amakuru byanoze, atari igihombo cyiyongereye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Internal loss', 'Igihombo cyo mu kigo', false, 4);
end $$;
