do $$ declare m_KG_104_3 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-104') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-104', 3, 'Physical Security and Access Control', 'Umutekano w''Umubiri no Kugenzura Abinjira', 'This module covers the physical layer: how a property is designed, how keys and access are managed, how zones are protected, and how a security layout is planned.', 'Iki gice kigaruka ku rwego rw''umubiri: uko ikigo cyateguwe, uko urufunguzo n''ukwinjira bicungwa, uko utugari turindwa, n''uko imiterere y''umutekano itegurwa.', 3)
  returning id into m_KG_104_3;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_3, '3.1', 'Security Design and Infrastructure Planning', 'Igenamiterere ry''Umutekano no Gutegura Ibikorwa Remezo', 'text', 'The most effective and least intrusive security in a hotel is designed into the building. Reception should have a clear sightline to the main entrance and the lift lobby, so that anyone entering is passively observed without being challenged. Lighting must be even rather than bright in patches, since pools of shadow between bright areas reduce visibility more than uniform moderate lighting. Back-of-house corridors should be separated from guest areas by a controlled door rather than by signage alone. Where a property already exists and cannot be rebuilt, the same principles are applied through furniture placement, lighting adjustment and door hardware, which are inexpensive compared with the loss they prevent.', 'Umutekano ukora cyane kandi udahungabanya mu ihoteri ni uwateguwe mu nyubako. Aho abakiriwe hagomba kubona neza urwinjiriro rukuru n''aho itara riri, kugira ngo uwinjira wese yitegererezwe mu buryo butagaragara atabajijwe. Urumuri rugomba kuba ruringaniye aho kuba rwinshi ahantu hamwe, kuko ibicucu hagati y''ahantu hamurikiwe bigabanya kubona kurusha urumuri ruringaniye rwo hagati. Inzira z''imbere zigomba gutandukanywa n''ahantu h''abashyitsi n''umuryango ugenzurwa aho gutandukanywa n''ibyapa gusa. Aho ikigo kimaze kubaho kandi kidashobora kongera kubakwa, amahame amwe akoreshwa binyuze mu gushyira ibikoresho, guhindura urumuri n''ingufuli z''imiryango, ari bike ku giciro ugereranyije n''igihombo bikumira.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_3, '3.2', 'Key Control, Access Management, and Surveillance Systems', 'Kugenzura Urufunguzo, Ukwinjira na Sisitemu za Kamera', 'text', 'Key control is the single highest-value control in a hotel, because a master key defeats every other physical measure simultaneously. Master keys must be issued to a named individual, signed out and back in per shift block rather than held all day, recovered immediately when a staff member leaves employment, and audited against the electronic lock log. Electronic access systems should restrict lift access to booked floors, expire cards at checkout, and retain an audit trail of every door opening. Surveillance supports these controls but does not replace them: cameras record what happened but prevent nothing unless someone reviews footage against a trigger, and coverage must prioritise transitions — entrances, lift lobbies, service doors — over open public areas.', 'Kugenzura urufunguzo ni ryo genzura rifite agaciro kanini mu ihoteri, kuko urufunguzo rukuru rutsinda izindi ngamba zose z''umubiri icyarimwe. Urufunguzo rukuru rugomba gutangwa ku muntu wagenwe, rugasinywa rusohoka rukanasinywa rusubira ku gice cy''akazi aho kugumana umunsi wose, rukagarurwa ako kanya umukozi avuye ku kazi, kandi rukagenzurwa hakurikijwe inyandiko y''ingufuli z''ikoranabuhanga. Sisitemu z''ikoranabuhanga zo kwinjira zigomba kugarukira kuzamuka mu itara ku magorofa yatumijwe, karita zikarangira igihe cyo gusohoka, kandi zikabika inyandiko ya buri muryango wafunguwe. Kamera zishyigikira ibi bigenzura ariko ntizibisimbura: kamera zandika ibyabaye ariko ntizikumira ikintu keretse hari umuntu ureba amashusho akurikije ikimenyetso, kandi aho zigenzura hagomba kwibanda ku hantu bahindukira — inzira zinjirirwa, aho itara riri, imiryango y''ibikorwa — aho kwibanda ku hantu rusange hafunguye.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_3, '3.3', 'Securing Public Areas, Guest Floors, and Restricted Zones', 'Kurinda Ahantu Rusange, Amagorofa y''Abashyitsi n''Utugari Tubujijwe', 'text', 'A hotel divides naturally into three security zones with different rules. Public areas — lobby, restaurant, bar, conference foyer — are open by design and are protected by observation, lighting and staff awareness rather than by access control. Guest floors are semi-private and should require a key card for lift or stairwell access, with any person on a floor other than their own worth a courteous check. Restricted zones — back office, cash handling, server room, key cabinet, stores — require a controlled door, a named access list and, where practical, an audit trail. The most common breach in practice is not a forced door but an unrestricted transition between zones, typically a service door propped open.', 'Ihoteri igabanywamo utugari dutatu tw''umutekano dufite amategeko atandukanye. Ahantu rusange — aho bakirirwa, resitora, bari, aho bahurira mu nama — hafunguye ku bushake kandi harindwa n''ukwitegereza, urumuri n''ubwitonzi bw''abakozi aho kurindwa no kugenzura abinjira. Amagorofa y''abashyitsi ni ay''igice cy''ubwiherero kandi agomba gusaba karita kugira ngo uzamuke mu itara cyangwa mu rwuriro, kandi umuntu wese uri ku igorofa ritari irye akwiye kubazwa mu cyubahiro. Utugari tubujijwe — ibiro by''inyuma, aho amafaranga acungirwa, icyumba cya seriveri, ububiko bw''urufunguzo, amabubiko — dusaba umuryango ugenzurwa, urutonde rw''abemerewe rwagenwe kandi, aho bishoboka, inyandiko igenzura. Icyibazo gikunze kubaho mu bikorwa si umuryango wavunwe ahubwo ni ahantu bahindukira hatagenzurwa, akenshi umuryango w''ibikorwa wafunguwe.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_3, '3.4', 'Practical Exercise: Designing a Hotel Security Layout', 'Umwitozo: Gutegura Imiterere y''Umutekano w''Ihoteri', 'text', 'Working from a floor plan of a mid-size hotel, produce a security layout marking: all entry and exit points including service and fire exits; the zone boundary between public, guest and restricted areas; the position of every controlled door; proposed camera positions prioritising transitions; lighting deficiencies; the reception sightline; the key cabinet location and its access list; and the assembly point. For each proposed control, state what risk it addresses and what it costs the guest experience. Present the layout as a document a general manager could act on, with a prioritised action list showing owner and cost, since a layout without an action list is a drawing rather than a plan.', 'Ukoresheje ikarita y''ihoteri yo hagati, kora imiterere y''umutekano ugaragaza: inzira zose zinjirirwa n''izisohokerwa harimo iz''ibikorwa n''iz''inkongi; imbibi hagati y''utugari twa rusange, utw''abashyitsi n''utubujijwe; aho buri muryango ugenzurwa uri; aho kamera zateganyijwe zibanda ku hantu bahindukira; aho urumuri rudahagije; aho abakiriwe bareba; aho ububiko bw''urufunguzo buri n''urutonde rw''abemerewe; n''ahantu ho guhurira. Kuri buri genzura ryatanzwe, vuga ikibazo rikemura n''ikiguzi rifite ku buryo umushyitsi yakirwa. Tanga iyo miterere nk''inyandiko umuyobozi mukuru yakoraho, hamwe n''urutonde rw''ibikorwa rutondetse rwerekana uwabishinzwe n''ikiguzi, kuko imiterere idafite urutonde rw''ibikorwa ari igishushanyo aho kuba gahunda.', 12, 4);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-104', m_KG_104_3, 'Quiz — Physical Security and Access Control', 'Ikizamini — Umutekano w''Umubiri no Kugenzura Abinjira', 'quiz', 70, 3)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why is key control the highest-value control in a hotel?', 'Kuki kugenzura urufunguzo ari ryo genzura rifite agaciro kanini mu ihoteri?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A master key defeats every other physical measure simultaneously', 'Urufunguzo rukuru rutsinda izindi ngamba zose z''umubiri icyarimwe', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The business exists to admit strangers at all hours into a building where they sleep', 'Ubucuruzi bubaho kwakira abatazwi ku masaha yose mu nyubako bararamo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that existed on paper but was not applied consistently', 'Igenzura ryariho ku rupapuro ariko ritakurikizwaga buri gihe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Risk, control, owner, deadline and cost', 'Ikibazo, igenzura, uwabishinzwe, itariki ntarengwa n''ikiguzi', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Where should camera coverage be prioritised?', 'Kamera zigomba gushyirwa hehe by''ibanze?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Master key issue logs and electronic lock audit trails', 'Inyandiko zo gutanga urufunguzo rukuru n''iz''ingufuli z''ikoranabuhanga', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An unrestricted zone transition, usually a propped service door', 'Ahantu bahindukira hatagenzurwa, akenshi umuryango w''ibikorwa wafunguwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The nearest safe exit, not the one they entered by; never lifts', 'Uwa hafi w''umutekano, atari uwo binjiriyeho; ntimukoreshe itara', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'At transitions — entrances, lift lobbies, service doors', 'Ku hantu bahindukira — inzira zinjirirwa, aho itara riri, imiryango y''ibikorwa', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Name the three security zones in a hotel.', 'Vuga utugari dutatu tw''umutekano mu ihoteri.', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Information flow stops within weeks', 'Amakuru ahagarara mu byumweru bike', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A room number or a guest''s presence', 'Nimero y''icyumba cyangwa ko umushyitsi ahari', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Public, guest floors, restricted', 'Rusange, amagorofa y''abashyitsi, tubujijwe', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Whether the night shift has physically rehearsed it', 'Ukuba abakora nijoro barigeze kwitoza mu buryo bw''umubiri', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
