do $$ declare m_KG_104_4 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-104') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-104', 4, 'Guest Safety and Incident Response', 'Umutekano w''Abashyitsi no Gutabara Ibibazo', 'This module covers responding to what actually happens in a hotel: disturbances, theft, guest misconduct, emergencies, and fire.', 'Iki gice kigaruka ku gutabara ibibaho koko mu ihoteri: urusaku, ubujura, imyitwarire mibi y''abashyitsi, ibyihutirwa, n''inkongi.', 4)
  returning id into m_KG_104_4;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_4, '4.1', 'Handling Disturbances, Theft, and Guest Misconduct', 'Gucyuha Urusaku, Ubujura n''Imyitwarire Mibi y''Abashyitsi', 'text', 'Hotel incidents must be resolved with the minimum possible visibility to other guests, because the disturbance caused by the response is often greater than the original incident. Approach quietly, speak at conversational volume, and move the interaction out of a public area before addressing the substance. With an intoxicated guest, the objective is to get them to their room safely, not to win an argument; involve a colleague as a witness and never enter a room alone with a guest of any gender. For reported theft, secure the room, avoid touching surfaces, record exactly what the guest reports without endorsing or disputing it, and escalate per policy. Every incident is documented factually the same day, regardless of how minor it appeared.', 'Ibibazo by''ihoteri bigomba gukemurwa bitagaragaye cyane ku bandi bashyitsi bishoboka, kuko urusaku ruterwa n''igisubizo akenshi rurenga ikibazo cya mbere. Egera utuje, uvuge ku ijwi ry''ikiganiro, kandi ukure ikiganiro mu hantu rusange mbere yo kuvuga ikibazo. Ku mushyitsi wasinze, intego ni ukumugeza mu cyumba cye mu mutekano, atari ugutsinda impaka; jyana mugenzi wawe nk''umuhamya kandi ntukigere winjira mu cyumba wenyine n''umushyitsi w''igitsina icyo ari cyo cyose. Ku bujura bwatangajwe, rinda icyumba, wirinde gukora ku hantu, wandike neza ibyo umushyitsi avuga utabyemeje cyangwa ngo ubipfobye, kandi uzamure ikibazo hakurikijwe politiki. Buri kibazo cyandikwa mu buryo bw''ukuri uwo munsi, uko cyaba cyaragaragaraga nk''igito kose.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_4, '4.2', 'Emergency Response Planning and Coordination', 'Gutegura no Guhuza Igisubizo cy''Ibyihutirwa', 'text', 'An emergency plan is only useful if the person on duty at 03:00 knows it without reading it. The plan names a single incident commander role by position rather than by individual, states who calls the emergency services and from where, defines how guests are informed, identifies the assembly point and the route to it, and specifies who accounts for guests and staff. Coordination with external services must be prepared in advance: the fire service should have current floor plans and access arrangements, and the nearest hospital and journey time should be known. Plans must be rehearsed with the actual night shift, not only with the day management team who wrote them.', 'Gahunda y''ibyihutirwa ifite akamaro gusa iyo uri ku kazi saa cyenda z''ijoro ayizi atayisomye. Gahunda igena umurimo umwe w''umuyobozi w''ikibazo hakurikijwe umwanya aho gukurikiza umuntu, ivuga uhamagara abatabazi n''aho abahamagarira, igena uko abashyitsi bamenyeshwa, imenya ahantu ho guhurira n''inzira igerayo, kandi igena ubarura abashyitsi n''abakozi. Guhuza n''inzego zo hanze bigomba gutegurwa mbere: abazimya inkongi bagomba kugira amakarita y''amagorofa agezweho n''uburyo bwo kwinjira, kandi ivuriro rya hafi n''igihe urugendo rumara bikamenyekana. Gahunda zigomba kwitozwa n''abakora nijoro koko, atari n''itsinda ry''ubuyobozi bwo ku manywa bwazanditse gusa.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_4, '4.3', 'Fire Safety and Evacuation Protocols', 'Umutekano ku Nkongi n''Amabwiriza yo Kwimuka', 'text', 'Fire is the emergency most likely to cause mass casualties in a hotel, because guests are asleep, unfamiliar with the building, and may be in a state that delays response. Prevention controls include maintained detection and alarm systems, kitchen and plant room inspection, and fire doors that are never propped open. On activation, staff duties are: raise the alarm, alert guests by the defined method, direct guests to the nearest safe exit rather than the one they entered by, never use lifts, assist those requiring help, and account for everyone at the assembly point. Never re-enter the building, and never allow a guest to re-enter for belongings. Records of drills, inspections and system tests must be kept, as they are the first documents requested after any fire incident.', 'Inkongi ni yo byihutirwa bishobora gutera abantu benshi guhutazwa mu ihoteri, kuko abashyitsi baba basinziriye, batazi inyubako, kandi bashobora kuba mu mimerere itinza igisubizo. Ibigenzura byo kwirinda birimo sisitemu zo kumenya no gutera induru zibungabungwa, kugenzura igikoni n''icyumba cy''imashini, n''imiryango y''inkongi itigera ifungurwa ngo isigare. Induru ivuze, inshingano z''abakozi ni izi: gutera induru, kumenyesha abashyitsi mu buryo bwagenwe, kwerekeza abashyitsi ku muryango w''umutekano wa hafi aho kubereka uwo binjiriyeho, kutigera bakoresha itara, gufasha abakeneye ubufasha, no kubarura buri wese ku hantu ho guhurira. Ntukigere wongera kwinjira mu nyubako, kandi ntukemerere umushyitsi kongera kwinjira gushaka ibintu bye. Inyandiko z''imyitozo, izo kugenzura n''izo gupima sisitemu zigomba kubikwa, kuko ari zo nyandiko zibanza gusabwa nyuma y''ikibazo cy''inkongi.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_4, '4.4', 'Case Study: Crisis Management during a Fire in a Resort Hotel', 'Urugero rw''Ikibazo: Gucunga Ikibazo mu Gihe cy''Inkongi mu Ihoteri', 'text', 'A fire begins in a kitchen extraction duct at 02:15 in a resort with 180 occupied rooms and a night team of four. Reviewing such incidents produces consistent findings. Where evacuation succeeded, the property had rehearsed with the night shift, staff directed guests actively rather than relying on signage, and a named person held command from the first minute. Where it failed, common factors were: a fire door propped open allowing smoke into a guest corridor, an assembly point too close to the building, no accurate occupancy list so nobody could confirm who was missing, and multiple staff independently calling emergency services producing conflicting information. The strongest single predictor of outcome was whether the night team, not the day management, had ever physically practised the evacuation.', 'Inkongi itangirira mu muyoboro w''umwuka w''igikoni saa munani n''igice z''ijoro mu ihoteri rifite ibyumba 180 birimo abantu n''itsinda ry''ijoro ry''abantu bane. Gusuzuma ibibazo nk''ibi bitanga ibintu bihoraho. Aho kwimuka byagenze neza, ikigo cyari cyarizetoje n''abakora nijoro, abakozi bayoboraga abashyitsi ku bushake aho kwiringira ibyapa, kandi umuntu wagenwe yafashe ubuyobozi kuva ku munota wa mbere. Aho byananiranye, ibintu bisanzwe byari ibi: umuryango w''inkongi wari wafunguwe utuma umwotsi winjira mu nzira y''abashyitsi, ahantu ho guhurira hari hafi cyane y''inyubako, nta rutonde nyakuri rw''abari mu byumba bityo nta muntu washoboraga kwemeza uwabuze, n''abakozi benshi bahamagara abatabazi buri wese ukwe batanga amakuru avuguruzanya. Ikintu kimwe cyagaragazaga neza icyavamo ni ukuba itsinda ry''ijoro, atari ubuyobozi bwo ku manywa, ryari ryarigeze kwitoza kwimuka mu buryo bw''umubiri.', 12, 4);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-104', m_KG_104_4, 'Quiz — Guest Safety and Incident Response', 'Ikizamini — Umutekano w''Abashyitsi no Gutabara Ibibazo', 'quiz', 70, 4)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why should hotel incidents be resolved with minimum visibility?', 'Kuki ibibazo by''ihoteri bigomba gukemurwa bitagaragaye cyane?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The disturbance caused by the response often exceeds the incident', 'Urusaku ruterwa n''igisubizo akenshi rurenga ikibazo', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The business exists to admit strangers at all hours into a building where they sleep', 'Ubucuruzi bubaho kwakira abatazwi ku masaha yose mu nyubako bararamo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that existed on paper but was not applied consistently', 'Igenzura ryariho ku rupapuro ariko ritakurikizwaga buri gihe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Risk, control, owner, deadline and cost', 'Ikibazo, igenzura, uwabishinzwe, itariki ntarengwa n''ikiguzi', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What is the rule about entering a guest room?', 'Ni irihe tegeko ryo kwinjira mu cyumba cy''umushyitsi?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Master key issue logs and electronic lock audit trails', 'Inyandiko zo gutanga urufunguzo rukuru n''iz''ingufuli z''ikoranabuhanga', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Public, guest floors, restricted', 'Rusange, amagorofa y''abashyitsi, tubujijwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The nearest safe exit, not the one they entered by; never lifts', 'Uwa hafi w''umutekano, atari uwo binjiriyeho; ntimukoreshe itara', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Never alone — always take a witness', 'Ntukigere wenyine — buri gihe jyana umuhamya', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'During a fire, which exit should guests be directed to?', 'Mu gihe cy''inkongi, abashyitsi bagomba kwerekezwa ku muhe muryango?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Information flow stops within weeks', 'Amakuru ahagarara mu byumweru bike', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A room number or a guest''s presence', 'Nimero y''icyumba cyangwa ko umushyitsi ahari', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The nearest safe exit, not the one they entered by; never lifts', 'Uwa hafi w''umutekano, atari uwo binjiriyeho; ntimukoreshe itara', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Whether the night shift has physically rehearsed it', 'Ukuba abakora nijoro barigeze kwitoza mu buryo bw''umubiri', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What most strongly predicts a successful hotel evacuation?', 'Ni iki cyerekana neza ko kwimuka mu ihoteri bizagenda neza?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A junior employee''s comment becomes the organisation''s public position within minutes', 'Ijambo ry''umukozi mutoya rihinduka icyo ikigo kivuga mu minota mike', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Whether the night shift has physically rehearsed it', 'Ukuba abakora nijoro barigeze kwitoza mu buryo bw''umubiri', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The human layer: no shared logins, phishing awareness, blame-free reporting', 'Urwego rw''abantu: ntimusangire, kumenya uburiganya, gutanga raporo hatabaye guhanwa', false, 3);
