do $$ declare m_KG_104_8 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-104') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-104', 8, 'Crisis and Emergency Management', 'Gucunga Ibihe by''Ikibazo n''Ibyihutirwa', 'This module covers what happens after a serious incident: communicating publicly, keeping the business running, learning from what occurred, and rehearsing before it does.', 'Iki gice kigaruka ku bibaho nyuma y''ikibazo gikomeye: kuvugana n''abaturage, gukomeza ibikorwa, kwiga ku byabaye, no kwitoza mbere y''uko bibaho.', 8)
  returning id into m_KG_104_8;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_8, '8.1', 'Crisis Communication and Media Relations', 'Itumanaho mu Bihe by''Ikibazo n''Umubano n''Itangazamakuru', 'text', 'In a crisis a hotel is judged less by the incident than by how it communicates about it. The plan must name a single spokesperson by position and state clearly that no other staff member speaks to media, guests'' families or on social media — a well-intentioned comment by a junior employee becomes the organisation''s public position within minutes. Communication should be early, factual and limited to what is confirmed: state what happened, what is being done, and what people should do now. Never speculate on cause, never assign blame, and never state casualty information before authorities have notified families. Silence is not neutral; in its absence others will supply the narrative.', 'Mu bihe by''ikibazo ihoteri ipimwa gake ku kibazo ahubwo ipimwa ku buryo ivuga kuri cyo. Gahunda igomba kugena umuvugizi umwe hakurikijwe umwanya kandi ikavuga neza ko nta wundi mukozi uvugana n''itangazamakuru, imiryango y''abashyitsi cyangwa ngo abitangaze ku mbuga — ijambo ry''umukozi mutoya rifite intego nziza rihinduka icyo ikigo kivuga ku mugaragaro mu minota mike. Itumanaho rigomba kuba ryihuse, rishingiye ku byabaye kandi rikagarukira ku byemejwe: vuga ibyabaye, ibirimo gukorwa, n''icyo abantu bagomba gukora ubu. Ntugatekereze ku mpamvu, ntugatange urubanza, kandi ntukavuge amakuru y''abahutajwe mbere y''uko inzego zimenyesha imiryango. Guceceka ntibiba ubusa; iyo utavuze abandi bazatanga inkuru.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_8, '8.2', 'Business Continuity and Recovery Planning', 'Gukomeza Ibikorwa no Gutegura Kugaruka', 'text', 'A continuity plan answers a practical question: if part of this property becomes unusable tomorrow, how does the business keep operating? It identifies the functions that must continue — guest accommodation, food safety, payment processing, communications — and states the fallback for each: alternative rooms or partner properties, manual booking and payment procedures when systems are down, backup power and communications, and where critical records are held offsite. Recovery planning addresses the sequence for returning to normal, including which areas reopen first and what verification is required before they do. The plan must be accessible in a form that works when the systems are unavailable, which usually means printed and held in more than one location.', 'Gahunda yo gukomeza isubiza ikibazo gifatika: niba igice cy''iki kigo kitagishoboka kwifashishwa ejo, ubucuruzi bukomeza gute? Imenya imirimo igomba gukomeza — kwakira abashyitsi, umutekano w''ibiribwa, gutunganya ubwishyu, itumanaho — kandi ikavuga icyakoreshwa kuri buri wo: ibindi byumba cyangwa amahoteri bafatanya, inzira zo kwiyandikisha no kwishyura zikoreshwa n''intoki igihe sisitemu zidakora, amashanyarazi n''itumanaho by''inyongera, n''aho inyandiko z''ingenzi zibitswe hanze y''ikigo. Gutegura kugaruka bireba urutonde rwo gusubira mu buryo busanzwe, harimo n''ibice bizabanza gufungurwa n''ibigomba kugenzurwa mbere. Gahunda igomba kuboneka mu buryo bukora igihe sisitemu zidakora, akenshi bivuze icapwe kandi ibikwe ahantu harenze hamwe.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_8, '8.3', 'Post-Incident Analysis and Improvement Plans', 'Isesengura Nyuma y''Ikibazo na Gahunda zo Kunoza', 'text', 'Post-incident analysis is conducted to change a control, not to identify a person to blame, because a review perceived as blame-seeking produces defensive accounts and destroys the information it depends on. The structure asks: what was supposed to happen, what actually happened, where did they diverge, which control was absent, poorly designed, or present but not followed, and what specific change is required now with an owner and a date. Near-misses must be reviewed with the same rigour as actual incidents, since they contain the same lesson at no human cost. Improvements must be entered into the written procedures, or they disappear when the individuals involved move on.', 'Isesengura nyuma y''ikibazo rikorwa kugira ngo habe impinduka ku igenzura, atari ukumenya umuntu wo guhana, kuko isuzuma rifatwa nk''irishaka guhana ritanga ibisobanuro byo kwirwanaho kandi rigasenya amakuru rishingiyeho. Imiterere yibaza: ni iki cyagombye kuba, ni iki cyabaye koko, ni hehe byatandukaniye, ni irihe genzura ritari rihari, ryateguwe nabi, cyangwa ryari rihari ariko ntirikurikizwe, kandi ni iyihe mpinduka yihariye isabwa ubu hamwe n''uwayishinzwe n''itariki. Ibyari hafi kubaho bigomba gusuzumwa umurava umwe n''ibyabaye koko, kuko birimo isomo rimwe nta gihombo cy''ubuzima. Impinduka zigomba gushyirwa mu nzira z''akazi zanditse, cyangwa zirazimira igihe abo bireba bagiye.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_8, '8.4', 'Simulation Exercise: Multi-Scenario Emergency Response', 'Umwitozo wo Kwigana: Gutabara mu Byihutirwa Bitandukanye', 'text', 'Run a tabletop or live simulation covering three escalating scenarios in sequence: a medical emergency in a public area during peak occupancy; a fire alarm activation on a guest floor at night; and a systems outage affecting locks and booking during the response. Participants must include the actual night shift, not only management. Assess: who took command and how quickly; whether guests were directed actively or left to find exits; whether the assembly point functioned and headcount was possible; whether external services were called once by the designated person; and whether communication to guests was accurate. Conclude with a structured debrief asking participants what they perceived and decided before telling them what observers saw, and produce a written improvement list with owners and dates.', 'Kora umwitozo ku meza cyangwa wo ku murima ukubiyemo ingero eshatu zigenda zikaza ku rutonde: ikibazo cy''ubuzima cyihutirwa mu hantu rusange mu gihe abantu ari benshi; induru y''inkongi ku igorofa ry''abashyitsi nijoro; no guhagarara kwa sisitemu bigira ingaruka ku ngufuli no ku bwandikishe mu gihe cyo gutabara. Abitabira bagomba kubamo abakora nijoro koko, atari ubuyobozi gusa. Suzuma: ni nde wafashe ubuyobozi n''igihe byatwaye; ese abashyitsi bayobowe ku bushake cyangwa basigaye bishakira inzira; ese ahantu ho guhurira hakoze kandi kubara abantu byashobotse; ese abatabazi bahamagawe rimwe n''umuntu wagenwe; kandi ese itumanaho ku bashyitsi ryari iry''ukuri. Soza n''isesengura riteguye ubaza abitabiriye icyo babonye n''icyo bahisemo mbere yo kubabwira icyo abagenzuzi babonye, hanyuma ukore urutonde rwanditse rw''ibyo kunoza n''abazabishinzwe n''amatariki.', 12, 4);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-104', m_KG_104_8, 'Quiz — Crisis and Emergency Management', 'Ikizamini — Gucunga Ibihe by''Ikibazo n''Ibyihutirwa', 'quiz', 70, 8)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why must a single spokesperson be named in a crisis plan?', 'Kuki hagomba kugenwa umuvugizi umwe muri gahunda y''ikibazo?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A junior employee''s comment becomes the organisation''s public position within minutes', 'Ijambo ry''umukozi mutoya rihinduka icyo ikigo kivuga mu minota mike', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The business exists to admit strangers at all hours into a building where they sleep', 'Ubucuruzi bubaho kwakira abatazwi ku masaha yose mu nyubako bararamo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that existed on paper but was not applied consistently', 'Igenzura ryariho ku rupapuro ariko ritakurikizwaga buri gihe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Risk, control, owner, deadline and cost', 'Ikibazo, igenzura, uwabishinzwe, itariki ntarengwa n''ikiguzi', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What must never be stated early in crisis communication?', 'Ni iki kitagomba kuvugwa kare mu itumanaho ry''ikibazo?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Master key issue logs and electronic lock audit trails', 'Inyandiko zo gutanga urufunguzo rukuru n''iz''ingufuli z''ikoranabuhanga', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Public, guest floors, restricted', 'Rusange, amagorofa y''abashyitsi, tubujijwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Never alone — always take a witness', 'Ntukigere wenyine — buri gihe jyana umuhamya', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Speculation on cause, blame, or casualty information before families are notified', 'Gutekereza ku mpamvu, gutanga urubanza, cyangwa amakuru y''abahutajwe mbere y''imiryango', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Why must a continuity plan be printed and held in more than one location?', 'Kuki gahunda yo gukomeza igomba gucapwa ikabikwa ahantu harenze hamwe?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A team observed only during the day is not observed at all', 'Itsinda ryitegererezwa ku manywa gusa ntiryitegererezwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It combines identity, payment, location-by-hour and companion data', 'Ahuza irangamuntu, ubwishyu, aho uri ku isaha n''abo muri kumwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It must work when the systems are unavailable', 'Igomba gukora igihe sisitemu zidakora', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The nearest safe exit, not the one they entered by; never lifts', 'Uwa hafi w''umutekano, atari uwo binjiriyeho; ntimukoreshe itara', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What is the purpose of post-incident analysis?', 'Ni iyihe ntego y''isesengura nyuma y''ikibazo?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'No — that limit is not negotiable', 'Oya — uwo mupaka ntuvugwaho', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To change a control, not to identify a person to blame', 'Guhindura igenzura, atari kumenya umuntu wo guhana', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A room number or a guest''s presence', 'Nimero y''icyumba cyangwa ko umushyitsi ahari', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Discretion over display', 'Ubushishozi aho kwerekana', false, 4);
end $$;
do $$ declare m_KG_104_9 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-104') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-104', 9, 'Ethics, Professional Conduct, and Legal Aspects', 'Ubunyangamugayo, Imyitwarire y''Umwuga n''Ibijyanye n''Amategeko', 'This final module covers the ethical and legal framework within which hospitality security must operate, and the pathway for continuing professional development.', 'Iki gice cya nyuma kigaruka ku rwego rw''ubunyangamugayo n''amategeko umutekano mu bwakiranyi ugomba gukoreramo, n''inzira yo gukomeza kwiteza imbere mu mwuga.', 9)
  returning id into m_KG_104_9;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_9, '9.1', 'Code of Ethics in Hospitality Security', 'Amategeko y''Ubunyangamugayo mu Mutekano w''Ubwakiranyi', 'text', 'A hospitality security officer holds access and information that could easily be misused: master keys, guest records, movement patterns, and the private circumstances of people staying in the property. The ethical requirements follow directly from that access. Never use position or access for personal benefit or curiosity. Never disclose guest information, including confirming that a named person is staying. Never accept a gift, tip or favour that could create an expectation. Treat every guest equally regardless of nationality, appearance, apparent wealth or perceived status. And report a colleague''s serious misconduct, because silence in this environment is participation.', 'Umukozi w''umutekano mu bwakiranyi afite ukwinjira n''amakuru byashobora gukoreshwa nabi byoroshye: urufunguzo rukuru, inyandiko z''abashyitsi, uko abantu bagenda, n''ibihe bwite by''abari mu kigo. Ibisabwa mu bunyangamugayo bikurikira ako kwinjira. Ntukigere ukoresha umwanya wawe cyangwa ukwinjira ku nyungu zawe cyangwa ku bushake bwo kumenya. Ntukigere utangaza amakuru y''umushyitsi, harimo no kwemeza ko umuntu wavuzwe ari aho. Ntukigere wakira impano, amafaranga y''ikaze cyangwa serivisi bishobora gutera icyizere. Fata buri mushyitsi kimwe utitaye ku gihugu akomokamo, uko agaragara, ubutunzi cyangwa urwego bikekwa. Kandi tanga raporo ku myitwarire mibi ikomeye ya mugenzi wawe, kuko guceceka muri aya mahugurwa ari ukugira uruhare.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_9, '9.2', 'Use of Force and Legal Responsibilities', 'Gukoresha Imbaraga n''Inshingano z''Amategeko', 'text', 'A hotel security officer is not a police officer and holds no special authority beyond that of any citizen and the property rights delegated by the owner. Force may be used only where the law of the jurisdiction permits it, must be reasonable and proportionate to the threat, must cease the moment the threat ceases, and is always the last option after verbal de-escalation and withdrawal have been considered. Detention carries significant legal risk and must follow the specific rules of the jurisdiction rather than assumption. Officers must know their own limits precisely, because an officer who exceeds them exposes themselves to criminal liability and the property to civil claims regardless of the original wrongdoing.', 'Umukozi w''umutekano mu ihoteri si umupolisi kandi nta bubasha bwihariye afite burenze ubw''umuturage uwo ari we wese n''uburenganzira bw''ikigo nyiracyo yamuhaye. Imbaraga zishobora gukoreshwa gusa aho amategeko y''aho ukorera abyemera, zigomba kuba zishyize mu gaciro kandi zihuye n''akaga, zigomba guhagarara ako kanya akaga kavuyeho, kandi buri gihe ni bwo buryo bwa nyuma nyuma yo gutekereza kugabanya ubushyuhe mu magambo no gusubira inyuma. Gufunga umuntu bifite ibyago bikomeye by''amategeko kandi bigomba gukurikiza amategeko yihariye y''aho ukorera aho gushingira ku kwiyumvisha. Abakozi bagomba kumenya neza imipaka yabo, kuko umukozi uyirenga yiteza ibyago by''ubushinjacyaha kandi agateza ikigo ibirego by''amategeko uko ikosa rya mbere ryaba ryari rimeze kose.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_9, '9.3', 'Cultural Awareness and Discretion in Guest Interaction', 'Kumenya Umuco n''Ubushishozi mu Kuvugana n''Abashyitsi', 'text', 'An international hotel hosts guests whose expectations around personal space, eye contact, gender interaction, dress, religious observance and directness of speech differ substantially from one another and from the officer''s own. Misreading these is a frequent source of complaints that had nothing to do with security. Practical measures: keep a respectful physical distance and adjust to the guest''s response; be aware that direct eye contact or a raised voice carries different meaning across cultures; where possible, match the officer to the situation on gender where a guest''s comfort requires it; and never assume from appearance, dress or language which country a guest is from or what they believe. Discretion covers all of it: address concerns privately rather than in public areas.', 'Ihoteri mpuzamahanga yakira abashyitsi bafite ibyo bategereje ku mwanya bwite, kureba mu maso, kuvugana hagati y''ibitsina, imyambarire, kwubahiriza idini n''ubutaziguye mu kuvuga bitandukanye cyane hagati yabo no ku mukozi ubwe. Kubisoma nabi ni inkomoko ikunze gutera ibirego bitari bifite aho bihuriye n''umutekano. Ingamba zifatika: gumana intera y''icyubahiro y''umubiri kandi uyihindure ukurikije uko umushyitsi asubiza; menya ko kureba mu maso ku buryo butaziguye cyangwa kuzamura ijwi bifite ubusobanuro butandukanye mu mico; aho bishoboka, huza umukozi n''imimerere ku gitsina aho umushyitsi akeneye kumva ameze neza; kandi ntukigere wiyumvisha ushingiye ku ko agaragara, imyambarire cyangwa ururimi igihugu umushyitsi akomokamo cyangwa icyo yizera. Ubushishozi bukubiyemo byose: cyuha ibibazo mu bwiherero aho kubikorera mu hantu rusange.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_104_9, '9.4', 'Continuous Professional Development and Certification Pathways', 'Gukomeza Kwiteza Imbere mu Mwuga n''Inzira z''Ibyemezo', 'text', 'Hospitality security offers a genuine career path, but only for those who treat it as a profession rather than a post. Development directions include: specialising in loss prevention or investigations; moving into security management for a property or a group; specialising in fire and life safety; moving toward executive protection through the VIP hosting experience this role provides; or moving into risk and compliance. Recognised certifications from established professional bodies improve mobility and earning capacity substantially, as does first aid certification, fire safety qualification and any additional language. The strongest development habit is simple: document what you do, because a portfolio of incidents handled, procedures written and improvements implemented is what distinguishes a candidate at interview.', 'Umutekano mu bwakiranyi utanga inzira nyayo y''umwuga, ariko gusa ku bawufata nk''umwuga aho kuwufata nk''umurimo. Icyerekezo cy''iterambere kirimo: kwibanda ku kwirinda igihombo cyangwa ku maperereza; kwimukira mu micungire y''umutekano y''ikigo cyangwa umuryango w''ibigo; kwibanda ku mutekano ku nkongi n''ubuzima; kwerekeza ku kurinda abakomeye binyuze mu burambe bwo kwakira abashyitsi bakomeye uyu murimo utanga; cyangwa kwimukira mu bucungabyago no kubahiriza amategeko. Ibyemezo byemewe biva ku miryango y''umwuga izwi byongera cyane ubushobozi bwo kwimuka n''uwo kwinjiza, nk''uko bimeze ku cyemezo cy''ubufasha bwa mbere, icy''umutekano ku nkongi n''urundi rurimi rwose. Umuco ukomeye kurusha iyindi mu iterambere ni woroshye: andika ibyo ukora, kuko ububiko bw''ibibazo wacyuye, inzira wanditse n''impinduka washyize mu bikorwa ari byo bitandukanya ukandida mu kiganiro cy''akazi.', 12, 4);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-104', m_KG_104_9, 'Quiz — Ethics, Professional Conduct, and Legal Aspects', 'Ikizamini — Ubunyangamugayo, Imyitwarire y''Umwuga n''Ibijyanye n''Amategeko', 'quiz', 70, 9)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What authority does a hotel security officer hold?', 'Ni ubuhe bubasha umukozi w''umutekano mu ihoteri afite?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'That of any citizen plus property rights delegated by the owner', 'Ubw''umuturage uwo ari we wese n''uburenganzira bw''ikigo yahawe', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The business exists to admit strangers at all hours into a building where they sleep', 'Ubucuruzi bubaho kwakira abatazwi ku masaha yose mu nyubako bararamo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that existed on paper but was not applied consistently', 'Igenzura ryariho ku rupapuro ariko ritakurikizwaga buri gihe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Risk, control, owner, deadline and cost', 'Ikibazo, igenzura, uwabishinzwe, itariki ntarengwa n''ikiguzi', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'When must the use of force cease?', 'Ni ryari gukoresha imbaraga bigomba guhagarara?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Master key issue logs and electronic lock audit trails', 'Inyandiko zo gutanga urufunguzo rukuru n''iz''ingufuli z''ikoranabuhanga', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Public, guest floors, restricted', 'Rusange, amagorofa y''abashyitsi, tubujijwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Never alone — always take a witness', 'Ntukigere wenyine — buri gihe jyana umuhamya', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The moment the threat ceases', 'Ako kanya akaga kavuyeho', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Should you confirm to a caller that a named person is staying?', 'Ese wemeza ku uhamagaye ko umuntu wavuzwe ari mu kigo?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A team observed only during the day is not observed at all', 'Itsinda ryitegererezwa ku manywa gusa ntiryitegererezwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It combines identity, payment, location-by-hour and companion data', 'Ahuza irangamuntu, ubwishyu, aho uri ku isaha n''abo muri kumwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'No — never, under any circumstance', 'Oya — na rimwe, mu bihe ibyo ari byo byose', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The nearest safe exit, not the one they entered by; never lifts', 'Uwa hafi w''umutekano, atari uwo binjiriyeho; ntimukoreshe itara', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What is the strongest professional development habit in this field?', 'Ni uwuhe muco ukomeye w''iterambere ry''umwuga muri uru rwego?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'No — that limit is not negotiable', 'Oya — uwo mupaka ntuvugwaho', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Document what you do — build a portfolio', 'Andika ibyo ukora — wubake ububiko', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A room number or a guest''s presence', 'Nimero y''icyumba cyangwa ko umushyitsi ahari', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Discretion over display', 'Ubushishozi aho kwerekana', false, 4);
end $$;
