  values (q_id, 'Only after families have been formally notified', 'Nyuma gusa y''uko imiryango imenyeshejwe ku mugaragaro', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What distinguishes a candidate in international security at interview?', 'Ni iki gitandukanya ukandida mu mutekano mpuzamahanga?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It cannot be planned against; a specific operational consequence can', 'Ntibishobora guteganyirizwa; ingaruka yihariye y''ibikorwa irashobora', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A portfolio of real analytical work, not a list of countries worked in', 'Ububiko bw''umurimo nyawo wo gusesengura, atari urutonde rw''ibihugu', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Otherwise each officer decides alone under pressure', 'Ubundi buri mukozi afata icyemezo wenyine mu gitutu', false, 3);
