  values (a_id, 4, 'mcq', 'Why is the principal''s own digital exposure often the highest-value quick win?', 'Kuki uko uwo barinda agaragara ku ikoranabuhanga ari cyo cyihuse gifite agaciro?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
