do $$ declare m_KG_106_3 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-106') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-106', 3, 'Advance Work and Protective Planning', 'Umurimo Ubanziriza n''Igenamigambi ryo Kurinda', 'This module covers the work that determines whether a movement is safe: the advance, site and venue surveys, route selection and analysis, residential and workplace planning, and the operations order.', 'Iki gice kigaruka ku murimo ugena niba urugendo rufite umutekano: umurimo ubanziriza, isuzuma ry''ahantu, guhitamo no gusesengura inzira, igenamigambi ry''urugo n''aho akorera, n''amabwiriza y''igikorwa.', 3)
  returning id into m_KG_106_3;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_3, '3.1', 'The Advance: Why It Decides Everything', 'Umurimo Ubanziriza: Impamvu Ugena Byose', 'text', 'The advance is the work done at a location before the principal arrives, and it is where protection is actually achieved. An advance officer visits the venue, walks the route the principal will take from the vehicle to the destination and back, identifies entrances and exits including emergency exits, locates the nearest medical facility and confirms the journey time, identifies safe havens and choke points, meets venue staff and local security, confirms parking and vehicle positioning, checks communications coverage, and identifies where the principal will be exposed and for how long. Everything the detail does on the day is executing decisions the advance already made. A movement without an advance is not protected; it is merely accompanied.', 'Umurimo ubanziriza ni umurimo ukorwa ku hantu mbere y''uko uwo barinda ageza, kandi ni ho kurinda kugerwaho koko. Umukozi ubanziriza asura ahantu, akanyura mu nzira uwo barinda azanyuramo ava mu modoka ajya aho agiye no gusubira, akamenya inzira zinjirirwa n''izisohokerwa harimo n''iz''ibyihutirwa, akamenya ivuriro rya hafi akemeza igihe urugendo rumara, akamenya ahantu h''umutekano n''ahantu hagoye, agahura n''abakozi b''ahantu n''umutekano wo mu karere, akemeza aho imodoka zihagarara n''uko zishyirwa, akagenzura aho itumanaho rigera, kandi akamenya aho uwo barinda azaba agaragara n''igihe kingana iki. Ibyo itsinda rikora uwo munsi byose ni ugushyira mu bikorwa ibyemezo umurimo ubanziriza wamaze gufata. Urugendo rutabanjirijwe ntirurindwa; ni ugukurikizwa gusa.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_3, '3.2', 'Site and Venue Security Assessment', 'Isuzuma ry''Umutekano w''Ahantu', 'text', 'A venue assessment establishes: how the principal enters and by which route, whether a private or secondary entrance is available, where they will be seated or positioned and what the sightlines to that position are, who else will be present and how they are screened, where the nearest exit from each area is, where a safe haven can be established, where the vehicle will wait and how quickly it can be reached, what the venue''s own emergency procedures are, and who holds authority over the space. Meet the venue''s security manager in advance, because on the day their cooperation determines what is possible. Identify what you cannot control, since a venue where you cannot control access or positioning may need to be declined rather than accepted with mitigation.', 'Isuzuma ry''ahantu rishyiraho: uko uwo barinda yinjira n''inzira ki, niba hari urwinjiriro rwihariye cyangwa urwa kabiri, aho azicara cyangwa ashyirwa n''uko habonwa uvuye hehe, ni bande bandi bazaba bahari n''uko bagenzurwa, umuryango wa hafi uvuye kuri buri gace uri he, ahantu h''umutekano hashobora gushyirwaho, imodoka izategerereza he n''igihe cyo kuyigeraho, ni izihe nzira z''ibyihutirwa z''aho hantu, n''ufite ububasha ku mwanya. Hura n''umuyobozi w''umutekano w''aho hantu mbere, kuko uwo munsi ubufatanye bwe bugena ibishoboka. Menya ibyo udashobora kugenzura, kuko ahantu udashobora kugenzura abinjira cyangwa aho ashyirwa hashobora gukenera kwangwa aho kwemerwa hakemurwa.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_3, '3.3', 'Route Selection and Analysis', 'Guhitamo no Gusesengura Inzira', 'text', 'Route work covers a primary route and at least one viable alternate, both driven in advance and at the same time of day as the movement where possible. Record: choke points where the vehicle must slow or stop; areas where an exit from the route is impossible; predictable stopping points such as traffic lights and junctions; police stations, hospitals and other safe havens along the way with the deviation time to each; road works, closures and events; and communications coverage. The most important discipline is variation: a principal who travels the same route at the same time every day has removed the need for any surveillance at all, because the pattern is the intelligence.', 'Umurimo w''inzira ukubiyemo inzira nkuru n''iyindi imwe nibura ishoboka, zombi zikanyurwamo mbere kandi ku isaha imwe n''urugendo aho bishoboka. Andika: ahantu hagoye aho imodoka igomba kugabanya umuvuduko cyangwa guhagarara; utuce aho kuva mu nzira bidashoboka; ahantu bihagararwa biteganywa nk''amatara y''imihanda n''amasangano; ibiro bya polisi, ibitaro n''ahandi h''umutekano ku nzira hamwe n''igihe cyo kuhagera; imirimo yo mu muhanda, gufunga n''ibirori; n''aho itumanaho rigera. Umurava w''ingenzi kurusha indi ni ihinduka: uwo barinda unyura mu nzira imwe ku isaha imwe buri munsi aba yakuyeho ukwinjira kw''ugukurikiranwa kose, kuko uburyo ubwabwo ari yo makuru.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_3, '3.4', 'Residential and Workplace Protection Planning', 'Igenamigambi ryo Kurinda Urugo n''Aho Akorera', 'text', 'The residence and the workplace are the two locations a principal returns to predictably, which makes them the two locations an adversary can rely on finding them. Residential planning covers: perimeter and approach; access control including deliveries, contractors and household staff; alarm and camera coverage; a safe room or secure area; lighting; the family''s own security awareness, particularly children''s routines and social media; and the response plan including who is called and how long they take. Workplace planning covers reception and visitor control, the principal''s route from vehicle to office, lift access, meeting room selection, and the coordination with the organisation''s own security function, which is often more capable than the detail assumes.', 'Urugo n''aho akorera ni ho hantu habiri uwo barinda agaruka mu buryo buteganywa, bigatuma ari ho hantu habiri umwanzi ashobora kwiringira ko azamubona. Igenamigambi ry''urugo rikubiyemo: umurongo w''inyuma n''uko hegerwa; kugenzura abinjira harimo ibicuruzwa bigezwa, abakora ku masezerano n''abakozi bo mu rugo; induru na kamera; icyumba cy''umutekano cyangwa agace karinzwe; urumuri; ubwitonzi bw''umuryango ubwabwo ku mutekano, cyane cyane ibisanzwe by''abana n''imbuga nkoranyambaga; na gahunda y''igisubizo harimo uhamagarwa n''igihe amara. Igenamigambi ry''aho akorera rikubiyemo aho abakiriwe no kugenzura abashyitsi, inzira y''uwo barinda ava mu modoka ajya mu biro, kuzamuka mu itara, guhitamo icyumba cy''inama, no guhuza n''umurimo w''umutekano w''ikigo ubwacyo, akenshi ufite ubushobozi kurusha uko itsinda ryiyumvisha.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_3, '3.5', 'The Operations Order and Briefing', 'Amabwiriza y''Igikorwa no Kumenyesha', 'text', 'The operations order converts the advance into instructions the team can execute. It states: the principal''s schedule with timings; the route with primary and alternate; each officer''s position and responsibility at each phase; vehicle assignments and seating; radio channels and call signs; the emergency rendezvous point and the actions on contact; medical arrangements including the designated hospital and route; contact details for venue staff, local police and the client; and the abort criteria. Brief the whole team together before departure and confirm understanding by asking individuals to state their own position and first action rather than asking whether everyone understood. A team that has been given a document but not briefed has not been briefed.', 'Amabwiriza y''igikorwa ahindura umurimo ubanziriza amabwiriza itsinda rishobora gushyira mu bikorwa. Avuga: gahunda y''uwo barinda n''amasaha; inzira n''iya mbere n''iy''inyongera; aho buri mukozi ahagarara n''inshingano ze kuri buri cyiciro; imodoka zagenwe n''aho bicara; imirongo ya radio n''amazina; ahantu ho guhurira mu byihutirwa n''ibikorwa igihe hari ikibaye; uburyo bwa muganga harimo ibitaro byagenwe n''inzira; aho bavugishwa abakozi b''ahantu, polisi yo mu karere n''umukiriya; n''ibigena guhagarika. Menyesha itsinda ryose hamwe mbere yo guhaguruka kandi wemeze ko basobanukiwe usaba buri wese kuvuga aho ahagarara n''igikorwa cye cya mbere aho kubaza niba bose basobanukiwe. Itsinda ryahawe inyandiko ritamenyeshejwe ntiryamenyeshejwe.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-106', m_KG_106_3, 'Quiz — Advance Work and Protective Planning', 'Ikizamini — Umurimo Ubanziriza n''Igenamigambi ryo Kurinda', 'quiz', 70, 3)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What is a movement without an advance?', 'Urugendo rutabanjirijwe ni iki?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Not protected — merely accompanied', 'Ntirurindwa — ni ugukurikizwa gusa', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The whole point is that they continue living and working normally', 'Intego yose ni uko akomeza kubaho no gukora busanzwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They withhold information, change plans without notice and travel without the team', 'Bahisha amakuru, bahindura gahunda batabimenyesheje kandi bakagenda batabajyanye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Record, report and vary routines — never confront it', 'Andika, tanga raporo, hindura ibisanzwe — ntuhangane na ko', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What should you do about a venue where you cannot control access or positioning?', 'Ukora iki ku hantu udashobora kugenzura abinjira cyangwa aho ashyirwa?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A published schedule removes the need for hostile surveillance altogether', 'Gahunda yatangajwe ikuraho ukwinjira kw''ugukurikiranwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Ask individuals to state their own position and first action', 'Saba buri wese kuvuga aho ahagarara n''igikorwa cye cya mbere', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Hands and approach angles rather than faces', 'Amaboko n''aho begera aho kureba mu maso', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It may need to be declined rather than accepted with mitigation', 'Hashobora gukenera kwangwa aho kwemerwa hakemurwa', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Why is route variation the key discipline?', 'Kuki ihinduka ry''inzira ari wo murava w''ingenzi?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Inside information rather than surveillance alone', 'Amakuru y''imbere aho gushingira ku gukurikiranwa gusa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It removes the need for force', 'Bikuraho ukwinjira kw''imbaraga', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A fixed pattern removes the need for surveillance — the pattern is the intelligence', 'Uburyo buhoraho bukuraho ukwinjira kw''ugukurikiranwa — uburyo ni yo makuru', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Move the principal away immediately, without pausing to assess further', 'Kura uwo barinda ako kanya, utahagaze ngo usuzume', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'How should team understanding be confirmed at a briefing?', 'Gusobanukirwa kw''itsinda kwemezwa gute mu kumenyesha?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is anticipatory and person-based rather than reactive and location-based', 'Ni ay''iteganya ashingiye ku muntu aho kuba ay''igisubizo ashingiye ku hantu', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Ask individuals to state their own position and first action', 'Saba buri wese kuvuga aho ahagarara n''igikorwa cye cya mbere', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Preparation — decisions already in the operations order need not be made under stress', 'Gutegura — ibyemezo bimaze kuba mu mabwiriza ntibigomba gufatwa mu gitutu', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To remove the principal from the threat, not to defeat an attacker', 'Gukura uwo barinda ku kaga, atari gutsinda uwateye', false, 4);
end $$;
do $$ declare m_KG_106_4 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-106') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-106', 4, 'Protective Operations', 'Ibikorwa byo Kurinda', 'This module covers execution: protective formations, foot and vehicle movement, arrivals and departures, venue and public appearance operations, and immediate action on contact.', 'Iki gice kigaruka ku gushyira mu bikorwa: imiterere y''itsinda ririnda, kugenda ku maguru no mu modoka, kugera no kugenda, ibikorwa ku hantu no mu kugaragara ku mugaragaro, n''ibikorwa byihuse igihe hari ikibaye.', 4)
  returning id into m_KG_106_4;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_4, '4.1', 'Protective Formations and Positioning', 'Imiterere y''Itsinda Ririnda n''Aho Bahagarara', 'text', 'A formation exists to achieve two things: to maintain observation in every direction around the principal, and to keep an officer positioned to move the principal away from any threat that appears. The size and shape adjust to the environment — a wider formation in open space, a tighter one in a crowd, a single officer in a low-profile setting — but the functions remain constant. Each officer holds an assigned arc of responsibility and watches it rather than watching the principal, because a team all looking at the same person is a team observing nothing. Positioning must also account for what the principal is doing: a principal shaking hands is exposed differently from a principal seated at a table.', 'Imiterere y''itsinda ibaho kugira ngo igere ku bintu bibiri: kugumisha kwitegereza mu byerekezo byose bikikije uwo barinda, no kugumisha umukozi ashobora gukura uwo barinda ku kaga kose kagaragaye. Ubunini n''imiterere birahinduka bijyanye n''ahantu — imiterere yagutse mu mwanya ufunguye, iyegeranye mu mbaga, umukozi umwe aho batagaragara cyane — ariko imirimo iguma imwe. Buri mukozi afite igice cy''inshingano yahawe akakireba aho kureba uwo barinda, kuko itsinda ryose rireba umuntu umwe ari itsinda ritareba ikintu. Aho bahagarara bigomba kandi kwita ku byo uwo barinda ari gukora: uwo barinda ari gusuhuza abantu agaragara mu buryo butandukanye n''uwo barinda wicaye ku meza.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_4, '4.2', 'Foot Movement and Working a Venue', 'Kugenda ku Maguru no Gukorera ku Hantu', 'text', 'On foot the detail moves with the principal rather than around them, adjusting continuously to the space, the crowd density and the principal''s own pace and behaviour. Anticipate the next transition before it happens: a doorway, a staircase, a corner, a lift, a change from private to public space. These transitions are where exposure is highest and where a detail loses cohesion if it has not planned for them. Keep a route to an exit available at all times, and know where the vehicle is at every moment. Where the principal stops unexpectedly — to speak to someone, to sign something — the detail adjusts to hold the position rather than continuing to move, because a detail that walks on has left the principal alone.', 'Ku maguru itsinda rigenda n''uwo barinda aho kugenda rimuzengurutse, rihindura buri gihe bijyanye n''umwanya, ubwinshi bw''imbaga n''umuvuduko n''imyitwarire by''uwo barinda ubwe. Teganya ahantu hakurikira bahindukira mbere y''uko haba: umuryango, urwuriro, ikona, itara, guhinduka kuva mu mwanya bwite ujya mu wa rusange. Aho hantu bahindukira ni ho kugaragara kuri hejuru kandi ni ho itsinda ritakaza ubumwe niba ritarabiteganyije. Gumisha inzira igana ku muryango ihari igihe cyose, kandi umenye aho imodoka iri buri kanya. Aho uwo barinda ahagaze bitunguranye — kugira ngo avugane n''umuntu, gusinya ikintu — itsinda rihindura rigahagarara aho gukomeza kugenda, kuko itsinda rikomeza kugenda riba risize uwo barinda wenyine.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_4, '4.3', 'Vehicle Movement, Arrivals and Departures', 'Kugenda mu Modoka, Kugera no Kugenda', 'text', 'Statistically, the vehicle phase and the moments immediately around it carry the highest risk in most protective operations, because the principal is predictable in location, constrained in movement and exposed while entering or leaving. Arrivals and departures should therefore be planned in detail: the vehicle stops as close as possible to the entrance, doors open only when the detail is in position, the principal moves directly and without pause, and the vehicle does not depart until the principal is inside the building. Never allow the vehicle to be blocked in. Never announce arrival times publicly, and vary them. Ensure the driver remains with the vehicle, engine running where appropriate, and knows the alternate route without needing to be told.', 'Mu mibare, igice cy''imodoka n''utwanya twegereye ni byo bifite ibyago byinshi mu bikorwa byinshi byo kurinda, kuko uwo barinda ateganywa ku hantu, agarukiwe mu kugenda kandi agaragara mu gihe yinjira cyangwa asohoka. Kugera no kugenda bigomba rero guteganywa birambuye: imodoka ihagarara hafi bishoboka y''urwinjiriro, imiryango ifungurwa gusa iyo itsinda riri aho, uwo barinda agenda atagaruka kandi atahagaze, kandi imodoka ntigenda kugeza uwo barinda ari mu nyubako. Ntukemerere ko imodoka ifungirwa. Ntukigere utangaza amasaha yo kugera ku mugaragaro, kandi uyahindure. Emeza ko umushoferi aguma n''imodoka, moteri ikora aho bikwiye, kandi akamenya inzira y''inyongera atabwiwe.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_4, '4.4', 'Public Appearances and Crowd Interaction', 'Kugaragara ku Mugaragaro n''Ihuriro n''Imbaga', 'text', 'A public appearance is the deliberate creation of exposure, and the detail''s task is to allow it to happen while controlling the conditions. Establish where the principal will be and for how long, how the audience is separated and screened, and where the extraction route runs. Where the principal engages with a crowd — shaking hands, taking photographs — position officers to observe hands and approach angles rather than faces, and keep an officer positioned between the principal and the direction of least control. Watch for the person who is not behaving like the crowd: not looking at the principal when everyone else is, moving against the flow, or repeatedly repositioning to stay close. Agree the duration in advance with the principal, because these engagements always overrun.', 'Kugaragara ku mugaragaro ni ugukora kugaragara ku bushake, kandi umurimo w''itsinda ni ukwemerera bibaho bagenzura imimerere. Shyiraho aho uwo barinda azaba n''igihe kingana iki, uko abateze amatwi batandukanywa bakagenzurwa, n''aho inzira yo kumukuramo inyura. Aho uwo barinda ahurira n''imbaga — gusuhuza, gufata amafoto — shyira abakozi aho bareba amaboko n''aho begera aho kureba mu maso, kandi ugumishe umukozi hagati y''uwo barinda n''icyerekezo kidakomeye. Reba umuntu utitwara nk''imbaga: utareba uwo barinda mu gihe abandi bose bamureba, ugenda anyuranye n''imigendekere, cyangwa uhora yimuka kugira ngo agume hafi. Mwumvikane ku gihe mbere n''uwo barinda, kuko ibi bihuriro buri gihe birenza igihe.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_4, '4.5', 'Immediate Action on Contact', 'Igikorwa Cyihuse Igihe Hari Ikibaye', 'text', 'When something happens, the response is one thing: move the principal away from the threat, immediately, without pausing to assess further. The direction is away from the source and toward the nearest cover or the vehicle. Cover the principal, control their movement — a principal who runs in an unplanned direction is a principal you have lost — and evacuate to the pre-designated point. Only officers not required for the evacuation deal with anything else. Do not stop to gather information, do not return for belongings, and do not stop until you reach a location that has been established as safe. Everything else — reporting, investigating, understanding what happened — occurs after the principal is secure, never before.', 'Iyo hari ikibaye, igisubizo ni kimwe: kura uwo barinda ku kaga, ako kanya, utahagaze ngo usuzume kurushaho. Icyerekezo ni ugukura ku isoko werekeza ku gihishe cya hafi cyangwa ku modoka. Twikira uwo barinda, ugenzure imigendere ye — uwo barinda wiruka mu cyerekezo kitateganyijwe ni uwo barinda watakaje — kandi umujyane ku hantu hateganyijwe. Abakozi batakenewe mu kwimura ni bo bacyuha ikindi cyose. Ntuhagarare ngo ukusanye amakuru, ntugaruke ngo ushake ibintu, kandi ntuhagarare kugeza ugeze ku hantu hemejwe ko hafite umutekano. Ibindi byose — gutanga raporo, gukora iperereza, gusobanukirwa ibyabaye — bibaho nyuma y''uko uwo barinda arinzwe, ntibigera bibaho mbere.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-106', m_KG_106_4, 'Quiz — Protective Operations', 'Ikizamini — Ibikorwa byo Kurinda', 'quiz', 70, 4)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What should each officer in a formation be watching?', 'Ni iki buri mukozi mu miterere agomba kureba?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Their assigned arc, not the principal', 'Igice cye yahawe, atari uwo barinda', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The whole point is that they continue living and working normally', 'Intego yose ni uko akomeza kubaho no gukora busanzwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They withhold information, change plans without notice and travel without the team', 'Bahisha amakuru, bahindura gahunda batabimenyesheje kandi bakagenda batabajyanye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Record, report and vary routines — never confront it', 'Andika, tanga raporo, hindura ibisanzwe — ntuhangane na ko', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Which phase statistically carries the highest risk?', 'Ni ikihe cyiciro mu mibare gifite ibyago byinshi?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A published schedule removes the need for hostile surveillance altogether', 'Gahunda yatangajwe ikuraho ukwinjira kw''ugukurikiranwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A fixed pattern removes the need for surveillance — the pattern is the intelligence', 'Uburyo buhoraho bukuraho ukwinjira kw''ugukurikiranwa — uburyo ni yo makuru', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Hands and approach angles rather than faces', 'Amaboko n''aho begera aho kureba mu maso', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The vehicle phase and the moments immediately around it', 'Igice cy''imodoka n''utwanya twegereye', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'When engaging a crowd, what should officers watch?', 'Mu guhurira n''imbaga, abakozi bagomba kureba iki?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Inside information rather than surveillance alone', 'Amakuru y''imbere aho gushingira ku gukurikiranwa gusa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It removes the need for force', 'Bikuraho ukwinjira kw''imbaraga', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Hands and approach angles rather than faces', 'Amaboko n''aho begera aho kureba mu maso', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Move the principal away immediately, without pausing to assess further', 'Kura uwo barinda ako kanya, utahagaze ngo usuzume', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What is the single response on contact?', 'Ni ikihe gisubizo kimwe igihe hari ikibaye?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is anticipatory and person-based rather than reactive and location-based', 'Ni ay''iteganya ashingiye ku muntu aho kuba ay''igisubizo ashingiye ku hantu', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Move the principal away immediately, without pausing to assess further', 'Kura uwo barinda ako kanya, utahagaze ngo usuzume', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Preparation — decisions already in the operations order need not be made under stress', 'Gutegura — ibyemezo bimaze kuba mu mabwiriza ntibigomba gufatwa mu gitutu', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To remove the principal from the threat, not to defeat an attacker', 'Gukura uwo barinda ku kaga, atari gutsinda uwateye', false, 4);
end $$;
do $$ declare m_KG_106_5 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-106') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-106', 5, 'Emergency Response, Medical and Crisis Situations', 'Gutabara mu Byihutirwa, Ubuvuzi n''Ibihe by''Ikibazo', 'This module covers what the detail does when the emergency is medical, environmental or criminal: medical response, evacuation, fire, kidnap awareness and crisis coordination.', 'Iki gice kigaruka ku byo itsinda rikora igihe ibyihutirwa ari ibya muganga, iby''ibidukikije cyangwa iby''ubugizi bwa nabi: gutabara kwa muganga, kwimuka, inkongi, kumenya iby''ubwambuzi no guhuza mu bihe by''ikibazo.', 5)
  returning id into m_KG_106_5;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_5, '5.1', 'Medical Emergency Involving the Principal', 'Ikibazo cya Muganga Kireba Uwo Barinda', 'text', 'A medical emergency affecting the principal is statistically far more likely than an attack, and a detail that has planned only for hostile action is unprepared for the more probable event. The detail should know the principal''s relevant medical history, any medication carried and any allergy, and should hold this information securely and confidentially. Every advance identifies the nearest appropriate medical facility and the journey time to it, and the team should carry a trauma kit and hold current first aid certification. On the day, the response is: provide first aid within your training, evacuate to the identified facility or summon emergency services, protect the principal''s privacy and dignity throughout, and inform only those who need to know.', 'Ikibazo cya muganga kireba uwo barinda mu mibare gishoboka cyane kurusha igitero, kandi itsinda ryateganyije gusa igikorwa cy''urwango ntiryiteguye ikintu gishoboka kurushaho. Itsinda rigomba kumenya amateka ya muganga afite akamaro y''uwo barinda, umuti uwo ari wo wose atwaye n''ubuvunanye ubwo ari bwo bwose, kandi rigomba kubika ayo makuru neza kandi mu ibanga. Buri murimo ubanziriza umenya ivuriro rya hafi rikwiye n''igihe urugendo rumara rugerayo, kandi itsinda rigomba gutwara agasanduku k''ibikomere no kugira icyemezo kigezweho cy''ubufasha bwa mbere. Uwo munsi, igisubizo ni: gutanga ubufasha bwa mbere mu mipaka y''amahugurwa yawe, kumujyana ku ivuriro ryamenyekanye cyangwa guhamagara abatabazi, kurinda ubwiherero n''icyubahiro by''uwo barinda muri byose, no kumenyesha gusa abakwiye kumenya.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_5, '5.2', 'Fire, Evacuation and Environmental Emergencies', 'Inkongi, Kwimuka n''Ibyihutirwa by''Ibidukikije', 'text', 'In a fire or building emergency the principal evacuates like everyone else, but the detail''s task is to do it faster and by a route that avoids the crowd, which is why every advance identifies emergency exits and not merely the entrance. Do not use lifts. Move directly to the pre-identified assembly point or, where the plan allows, directly to the vehicle and away from the site entirely, because a principal standing in a car park with a crowd is exposed in a way the building never was. In an environmental emergency — severe weather, flooding, earthquake — the decision is between evacuation and remaining in place, and it should follow the plan and local guidance rather than being improvised.', 'Mu nkongi cyangwa ikibazo cy''inyubako uwo barinda yimuka nk''abandi bose, ariko umurimo w''itsinda ni ukubikora vuba kandi banyuze mu nzira yirinda imbaga, ni yo mpamvu buri murimo ubanziriza umenya inzira zisohoka z''ibyihutirwa atari urwinjiriro gusa. Ntimukoreshe itara. Genda utaziguye ugana ahantu ho guhurira hamenyekanye cyangwa, aho gahunda ibyemera, ugana ku modoka mu buryo butaziguye ukava ku hantu burundu, kuko uwo barinda uhagaze aho imodoka zihagarara n''imbaga agaragara mu buryo inyubako itigeze imugaragaza. Mu kibazo cy''ibidukikije — ikirere kibi cyane, umwuzure, umutingito — icyemezo ni hagati yo kwimuka no kuguma aho, kandi kigomba gukurikiza gahunda n''amabwiriza yo mu karere aho kwikorerwa.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_5, '5.3', 'Kidnap and Abduction Awareness', 'Kumenya iby''Ubwambuzi n''Ugushimuta', 'text', 'Where kidnap risk exists, prevention is almost entirely about predictability and information. Vary routes and timings so that a pattern cannot be established. Restrict who knows travel plans, including within the household and office, since most successful abductions rely on inside information rather than on surveillance alone. Maintain a check-in regime that raises an alarm quickly when a check-in is missed, and define how long a missed check-in is allowed to run before escalation. Reduce visible signals of value. Response is not a field decision: an organisation facing an abduction requires specialist support, and the detail''s role at that point is to secure the scene, preserve information and hand over to those equipped to manage it.', 'Aho ibyago by''ubwambuzi bihari, kwirinda hafi byose bireba kumenyekana n''amakuru. Hindura inzira n''amasaha kugira ngo uburyo butamenyekana. Garukira abazi gahunda z''ingendo, harimo no mu rugo no mu biro, kuko ugushimuta gwinshi gutsinda gushingira ku makuru y''imbere aho gushingira ku gukurikiranwa gusa. Gumisha uburyo bwo kwitangaza butera induru vuba iyo kwitangaza kubuze, kandi ugene igihe kwitangaza kubuze kwemererwa mbere yo kuzamura ikibazo. Gabanya ibimenyetso bigaragara by''agaciro. Igisubizo si icyemezo cyo ku murima: ikigo gihuye n''ugushimuta gisaba ubufasha bw''inzobere, kandi uruhare rw''itsinda muri icyo gihe ni ukurinda ahabaye ikibazo, kubika amakuru no guhererekanya ku bafite ibikoresho byo kubicunga.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_5, '5.4', 'Working with Police and Emergency Services', 'Gukorana na Polisi n''Abatabazi', 'text', 'A protective detail holds no authority beyond that of any citizen plus rights delegated by the principal or venue owner, and must know that boundary precisely. Engage local police in advance where the operation warrants it, providing the schedule, routes and a named contact, because a police service that knows you are operating responds differently from one that discovers it during an incident. Where an incident occurs, cooperate fully and identify yourselves clearly. Where command transfers to an emergency service, the detail supports rather than continuing to direct — with the exception that the detail retains responsibility for the principal''s immediate protection throughout. Always verify the identity of anyone presenting as an official before granting access.', 'Itsinda ririnda nta bubasha rifite burenze ubw''umuturage uwo ari we wese n''uburenganzira rwahawe n''uwo barinda cyangwa nyir''ahantu, kandi rigomba kumenya uwo mupaka neza. Injiza polisi yo mu karere mbere aho ibikorwa bibisaba, uyiha gahunda, inzira n''umuntu wagenwe wo kuvugisha, kuko urwego rwa polisi ruzi ko ukora rusubiza mu buryo butandukanye n''urubimenye mu gihe cy''ikibazo. Aho ikibazo kibaye, fatanya byuzuye kandi wivuge neza uwo uri we. Aho ubuyobozi bujya ku rwego rw''abatabazi, itsinda rishyigikira aho gukomeza kuyobora — usibye ko itsinda riguma rifite inshingano yo kurinda uwo barinda ako kanya muri byose. Buri gihe emeza indangamuntu y''uwivuga ko ari uw''inzego mbere yo kumwemerera kwinjira.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_5, '5.5', 'Post-Incident Actions and Review', 'Ibikorwa n''Isuzuma Nyuma y''Ikibazo', 'text', 'Once the principal is secure, the detail''s remaining tasks are: account for every team member; establish and communicate the principal''s status to those who need to know and to nobody else; preserve the scene where an offence may have occurred; record what each officer personally observed, separately, before accounts merge through discussion; and notify the client and any external service required. The review afterwards examines the control that failed rather than seeking an individual to blame, because the purpose is to change what happens next time. Near-misses are reviewed with the same rigour — in protective work the near-miss is usually the only warning you will receive before the incident.', 'Uwo barinda amaze kurindwa, imirimo isigaye y''itsinda ni: kubarura buri mukozi w''itsinda; kumenya no kumenyesha uko uwo barinda ameze ku bakwiye kumenya kandi nta wundi; kurinda ahabaye ikibazo aho icyaha gishobora kuba cyabaye; kwandika icyo buri mukozi yiboneye ubwe, ukwe, mbere y''uko ibyavuzwe bivangwa n''ikiganiro; no kumenyesha umukiriya n''urwego rwo hanze rwose rukenewe. Isuzuma nyuma risuzuma igenzura ryananiranye aho gushaka umuntu wo guhana, kuko intego ari uguhindura ibizabaho ubutaha. Ibyari hafi kubaho bisuzumwa umurava umwe — mu murimo wo kurinda ikintu cyari hafi kubaho akenshi ni cyo burira rwonyine uzabona mbere y''ikibazo.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-106', m_KG_106_5, 'Quiz — Emergency Response, Medical and Crisis Situations', 'Ikizamini — Gutabara mu Byihutirwa, Ubuvuzi n''Ibihe by''Ikibazo', 'quiz', 70, 5)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Which is statistically more likely: an attack or a medical emergency?', 'Ni ikihe gishoboka mu mibare: igitero cyangwa ikibazo cya muganga?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A medical emergency, by a wide margin', 'Ikibazo cya muganga, ku rugero runini', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The whole point is that they continue living and working normally', 'Intego yose ni uko akomeza kubaho no gukora busanzwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They withhold information, change plans without notice and travel without the team', 'Bahisha amakuru, bahindura gahunda batabimenyesheje kandi bakagenda batabajyanye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Record, report and vary routines — never confront it', 'Andika, tanga raporo, hindura ibisanzwe — ntuhangane na ko', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why is a principal in a car park with a crowd a concern after evacuation?', 'Kuki uwo barinda aho imodoka zihagarara n''imbaga ari ikibazo nyuma yo kwimuka?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A published schedule removes the need for hostile surveillance altogether', 'Gahunda yatangajwe ikuraho ukwinjira kw''ugukurikiranwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A fixed pattern removes the need for surveillance — the pattern is the intelligence', 'Uburyo buhoraho bukuraho ukwinjira kw''ugukurikiranwa — uburyo ni yo makuru', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The vehicle phase and the moments immediately around it', 'Igice cy''imodoka n''utwanya twegereye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They are exposed in a way the building never was', 'Agaragara mu buryo inyubako itigeze imugaragaza', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What do most successful abductions rely on?', 'Ugushimuta gwinshi gutsinda gushingira ku iki?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They are exposed in a way the building never was', 'Agaragara mu buryo inyubako itigeze imugaragaza', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It removes the need for force', 'Bikuraho ukwinjira kw''imbaraga', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Inside information rather than surveillance alone', 'Amakuru y''imbere aho gushingira ku gukurikiranwa gusa', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Hands and approach angles rather than faces', 'Amaboko n''aho begera aho kureba mu maso', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why record each officer''s observations separately after an incident?', 'Kuki wandika ibyo buri mukozi yabonye ukwe nyuma y''ikibazo?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is anticipatory and person-based rather than reactive and location-based', 'Ni ay''iteganya ashingiye ku muntu aho kuba ay''igisubizo ashingiye ku hantu', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Before accounts merge through discussion', 'Mbere y''uko ibivuzwe bivangwa n''ikiganiro', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Preparation — decisions already in the operations order need not be made under stress', 'Gutegura — ibyemezo bimaze kuba mu mabwiriza ntibigomba gufatwa mu gitutu', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To remove the principal from the threat, not to defeat an attacker', 'Gukura uwo barinda ku kaga, atari gutsinda uwateye', false, 4);
end $$;
do $$ declare m_KG_106_6 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-106') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-106', 6, 'Legal, Leadership and Professional Development', 'Amategeko, Ubuyobozi n''Iterambere ry''Umwuga', 'This final module covers the legal position of an EP officer, detail leadership and decision-making under stress, working internationally, business practice, and building a career in this field.', 'Iki gice cya nyuma kigaruka ku mwanya mu mategeko w''umukozi wa EP, ubuyobozi bw''itsinda no gufata ibyemezo mu gitutu, gukorera mu mahanga, imikorere y''ubucuruzi, no kubaka umwuga muri uru rwego.', 6)
  returning id into m_KG_106_6;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_6, '6.1', 'Legal Responsibilities and the Use of Force', 'Inshingano z''Amategeko no Gukoresha Imbaraga', 'text', 'An EP officer holds no special legal authority: their powers are those of any citizen, plus whatever rights the principal or a venue owner has lawfully delegated. Force may be used only where the law permits, must be reasonable and proportionate to the threat, must be the last option after evacuation and de-escalation have been considered, and must cease the moment the threat ceases. Evacuation is almost always the lawful and correct response precisely because it removes the need for force. Know the law of the jurisdiction you are operating in — rules on detention, weapons and self-defence vary substantially, and a practice that is lawful in one country is a criminal offence in another.', 'Umukozi wa EP nta bubasha bwihariye bw''amategeko afite: ububasha bwe ni ubw''umuturage uwo ari we wese, hiyongereyeho uburenganzira uwo barinda cyangwa nyir''ahantu yahaye mu buryo bwemewe. Imbaraga zishobora gukoreshwa gusa aho amategeko abyemera, zigomba kuba zishyize mu gaciro kandi zihuye n''akaga, zigomba kuba ari bwo buryo bwa nyuma nyuma yo gutekereza kwimuka no kugabanya ubushyuhe, kandi zigomba guhagarara ako kanya akaga kavuyeho. Kwimuka hafi buri gihe ni cyo gisubizo cyemewe kandi gikwiye kuko kikuraho ukwinjira kw''imbaraga. Menya amategeko y''aho ukorera — amategeko ku gufunga, intwaro no kwirwanaho aratandukana cyane, kandi igikorwa cyemewe mu gihugu kimwe ni icyaha mu kindi.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_6, '6.2', 'Detail Leadership and Decision-Making Under Stress', 'Ubuyobozi bw''Itsinda no Gufata Ibyemezo mu Gitutu', 'text', 'The detail leader is accountable for the plan, the briefing, the decisions taken during a movement and the review afterwards. During a movement the leadership style is directive — instructions are given and followed without debate, because there is no time to build consensus — while during planning and review a participative style produces better results, since officers on the ground see what the leader does not. Decision-making under stress degrades predictably: options narrow, tunnel vision develops and time perception distorts. The remedy is preparation rather than composure alone — decisions already made in the operations order do not have to be made under stress, which is the entire operational purpose of planning in advance.', 'Umuyobozi w''itsinda abazwa gahunda, kumenyesha, ibyemezo byafashwe mu gihe cy''urugendo n''isuzuma nyuma. Mu gihe cy''urugendo uburyo bw''ubuyobozi ni ubutegeka — amabwiriza atangwa akubahirizwa nta mpaka, kuko nta gihe cyo kubaka ubwumvikane — mu gihe cyo gutegura no gusuzuma uburyo bw''ubufatanye butanga ibyavuyemo byiza, kuko abakozi bari ku murima babona ibyo umuyobozi atabona. Gufata ibyemezo mu gitutu birangirika mu buryo buteganywa: uburyo bugabanuka, kureba ahantu hamwe biravuka kandi kumva igihe birahinduka. Igisubizo ni ugutegura aho kuba gutuza kwonyine — ibyemezo bimaze gufatwa mu mabwiriza y''igikorwa ntibigomba gufatwa mu gitutu, ari na yo ntego yose y''akazi yo gutegura mbere.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_6, '6.3', 'International Assignments and Cross-Border Work', 'Akazi Mpuzamahanga n''Umurimo Hakurya y''Imipaka', 'text', 'Working internationally changes the operating context substantially: the law changes, the reliability of police changes, medical capacity changes, and equipment lawful at home may be prohibited on arrival. Before travel, establish the legal position on protective work in that country, licensing requirements, weapons law and whether the operation requires local partnership; identify the medical facilities of appropriate standard and the evacuation arrangement; verify communications will function; and build the country and route picture as you would any other assessment. Engage a reputable local provider where required and conduct due diligence on them, because you retain responsibility for what they do in your name.', 'Gukorera mu mahanga bihindura cyane aho ukorera: amategeko arahinduka, kwizerwa kwa polisi kurahinduka, ubushobozi bwa muganga burahinduka, kandi ibikoresho byemewe iwanyu bishobora kuba bibujijwe ugeze. Mbere y''urugendo, menya umwanya mu mategeko w''umurimo wo kurinda muri icyo gihugu, ibisabwa by''impushya, amategeko y''intwaro n''ukuba ibikorwa bisaba ubufatanye bwo mu karere; menya amavuriro y''urwego rukwiye n''uburyo bwo kwimurwa; emeza ko itumanaho rizakora; kandi ubake ishusho y''igihugu n''inzira nk''uko wakora isuzuma iryo ari ryo ryose. Injiza utanga serivisi wo mu karere wizewe aho bikenewe kandi umugenzure amateka, kuko uguma ufite inshingano ku byo akora mu izina ryawe.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_6, '6.4', 'Business Practice: Clients, Contracts and Insurance', 'Imikorere y''Ubucuruzi: Abakiriya, Amasezerano n''Ubwishingizi', 'text', 'Many EP professionals work independently or through small companies, which makes commercial competence part of professional competence. A contract should state the scope of the service, the number of officers and hours, what is and is not included, the rate and payment terms, liability and insurance arrangements, confidentiality obligations, and the notice period. Carry appropriate professional indemnity and public liability insurance, and confirm that it covers the countries you will work in. Be honest about capability: accepting an assignment beyond your competence — a task requiring skills or team size you do not have — exposes the principal to risk and will end your reputation in a field where reputation is the only marketing that matters.', 'Abanyamwuga benshi ba EP bakora bigenga cyangwa binyuze mu bigo bito, bigatuma ubushobozi bw''ubucuruzi ari igice cy''ubushobozi bw''umwuga. Amasezerano agomba kuvuga ibyo serivisi ikubiyemo, umubare w''abakozi n''amasaha, ibirimo n''ibitarimo, igiciro n''ibisabwa mu kwishyura, inshingano n''uburyo bw''ubwishingizi, inshingano z''ibanga, n''igihe cyo kumenyesha. Gira ubwishingizi bukwiye bw''umwuga n''ubw''inshingano ku baturage, kandi wemeze ko bukubiyemo ibihugu uzakoreramo. Ba umunyakuri ku bushobozi: kwemera akazi karenze ubushobozi bwawe — umurimo usaba ubumenyi cyangwa ubunini bw''itsinda udafite — bishyira uwo barinda mu byago kandi bizarangiza ishusho yawe mu rwego aho ishusho ari yo kwamamaza kwonyine gufite akamaro.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_106_6, '6.5', 'Building a Career in Executive Protection', 'Kubaka Umwuga mu Kurinda Abakomeye', 'text', 'Executive protection rewards a combination of capabilities that is rarer than any of them alone: analytical judgement, planning discipline, interpersonal skill, medical capability and absolute discretion. Development directions include detail leadership, protective operations management, residential security management, corporate security roles, protective intelligence and independent consultancy. Recognised training, a current first aid or trauma qualification, an advanced driving qualification and an additional language all improve mobility substantially. The strongest habits are documentation and discretion: keep your advances, route analyses and after-action reviews as a portfolio, and never discuss a principal — because in this field the professionals who last are the ones nobody has heard anything about.', 'Kurinda abakomeye guhemba ihuriro ry''ubushobozi ridasanzwe kurusha buri bumwe bwonyine: ubushishozi bwo gusesengura, umurava wo gutegura, ubuhanga mu mibanire, ubushobozi bwa muganga n''ubushishozi bwuzuye. Icyerekezo cy''iterambere kirimo kuyobora itsinda, gucunga ibikorwa byo kurinda, gucunga umutekano w''urugo, imirimo y''umutekano w''ibigo, amakuru yo kurinda n''ubujyanama bwigenga. Amahugurwa yemewe, icyemezo kigezweho cy''ubufasha bwa mbere cyangwa cy''ibikomere, icyemezo cyo gutwara neza n''urundi rurimi byose byongera cyane ubushobozi bwo kwimuka. Imico ikomeye kurusha indi ni inyandiko n''ubushishozi: bika imirimo yawe ibanziriza, isesengura ry''inzira n''amasuzuma nyuma y''igikorwa nk''ububiko, kandi ntukigere uvuga ku wo urinda — kuko muri uru rwego abanyamwuga bamara igihe ari abo nta muntu wigeze yumva ikintu na kimwe kuri bo.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-106', m_KG_106_6, 'Quiz — Legal, Leadership and Professional Development', 'Ikizamini — Amategeko, Ubuyobozi n''Iterambere ry''Umwuga', 'quiz', 70, 6)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What legal authority does an EP officer hold?', 'Ni ubuhe bubasha bw''amategeko umukozi wa EP afite?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A citizen''s powers plus rights lawfully delegated by the principal or venue owner', 'Ubw''umuturage n''uburenganzira yahawe n''uwo barinda cyangwa nyir''ahantu', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The whole point is that they continue living and working normally', 'Intego yose ni uko akomeza kubaho no gukora busanzwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They withhold information, change plans without notice and travel without the team', 'Bahisha amakuru, bahindura gahunda batabimenyesheje kandi bakagenda batabajyanye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Record, report and vary routines — never confront it', 'Andika, tanga raporo, hindura ibisanzwe — ntuhangane na ko', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why is evacuation almost always the correct response?', 'Kuki kwimuka hafi buri gihe ari cyo gisubizo gikwiye?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A published schedule removes the need for hostile surveillance altogether', 'Gahunda yatangajwe ikuraho ukwinjira kw''ugukurikiranwa', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A fixed pattern removes the need for surveillance — the pattern is the intelligence', 'Uburyo buhoraho bukuraho ukwinjira kw''ugukurikiranwa — uburyo ni yo makuru', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The vehicle phase and the moments immediately around it', 'Igice cy''imodoka n''utwanya twegereye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It removes the need for force', 'Bikuraho ukwinjira kw''imbaraga', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What is the remedy for degraded decision-making under stress?', 'Ni ikihe gisubizo ku gufata ibyemezo kwangiritse mu gitutu?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They are exposed in a way the building never was', 'Agaragara mu buryo inyubako itigeze imugaragaza', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A citizen''s powers plus rights lawfully delegated by the principal or venue owner', 'Ubw''umuturage n''uburenganzira yahawe n''uwo barinda cyangwa nyir''ahantu', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Preparation — decisions already in the operations order need not be made under stress', 'Gutegura — ibyemezo bimaze kuba mu mabwiriza ntibigomba gufatwa mu gitutu', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Hands and approach angles rather than faces', 'Amaboko n''aho begera aho kureba mu maso', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What does accepting an assignment beyond your competence do?', 'Kwemera akazi karenze ubushobozi bwawe bikora iki?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is anticipatory and person-based rather than reactive and location-based', 'Ni ay''iteganya ashingiye ku muntu aho kuba ay''igisubizo ashingiye ku hantu', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Exposes the principal to risk and ends your reputation', 'Bishyira uwo barinda mu byago kandi birangiza ishusho yawe', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It removes the need for force', 'Bikuraho ukwinjira kw''imbaraga', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To remove the principal from the threat, not to defeat an attacker', 'Gukura uwo barinda ku kaga, atari gutsinda uwateye', false, 4);
