  values (q_id, 'They shape clinical decisions — found, CPR start, shocks delivered', 'Agena ibyemezo by''ubuvuzi — yaboneweho, CPR yatangiriye, amashanyarazi', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'When the casualty is unresponsive', 'Igihe uwakomeretse adasubiza', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Cooling with cool running water for a sustained period', 'Kukonjesha n''amazi akonje atemba igihe kirekire', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Can this written course replace certified practical first aid training?', 'Ese iri somo ryanditse ryasimbura amahugurwa afatika yemewe?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A general call produces nobody acting — everyone assumes somebody else will', 'Induru rusange itanga nta ukora — buri wese yiyumvisha ko undi azabikora', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'No — physical skills must be learned and assessed hands-on', 'Oya — ubumenyi bw''umubiri bugomba kwigwa bukanasuzumwa ku bikoresho', true, 2);
