do $$ declare m_KG_110_5 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-110') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-110', 5, 'Writing the Security Plan', 'Kwandika Gahunda y''Umutekano', 'This module covers producing the documents the assessment exists to generate: the risk register, the security plan itself, standard operating procedures, and the report that persuades management to act.', 'Iki gice kigaruka ku gukora inyandiko isuzuma ririho gutanga: urutonde rw''ibyago, gahunda y''umutekano ubwayo, inzira z''akazi zisanzwe, na raporo yemeza ubuyobozi gukora.', 5)
  returning id into m_KG_110_5;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_5, '5.1', 'Building and Maintaining a Risk Register', 'Gukora no Kubungabunga Urutonde rw''Ibyago', 'text', 'The risk register is the living record of every identified risk and what is being done about it. Each entry states: a unique reference; the risk described specifically enough to be understood by someone who was not present; the asset affected; likelihood and impact scores with the scale used; the existing controls; the residual risk; the chosen treatment; the recommended action; the named owner; the target date; and the current status. It must be reviewed at a defined interval and after any incident or significant change. A register that is written once and filed is a snapshot, not a register, and it becomes misleading within months as the organisation changes around it.', 'Urutonde rw''ibyago ni inyandiko ihoraho ya buri kibazo cyamenyekanye n''ibirimo gukorwa kuri cyo. Buri kintu kivuga: nimero yihariye; ikibazo gisobanuwe neza ku buryo umuntu utari ahari yakisobanukirwa; umutungo cyibasira; amanota y''amahirwe n''ingaruka n''urwego rwakoreshejwe; ibigenzura bihari; ikibazo gisigaye; igisubizo cyahisemo; igikorwa cyatanzwe; uwabishinzwe wagenwe; itariki ntarengwa; n''aho bigeze. Rugomba gusuzumwa ku gihe kigenwe kandi nyuma y''ikibazo cyangwa impinduka ikomeye. Urutonde rwanditse rimwe rugashyingurwa ni ifoto, atari urutonde, kandi ruhinduka rubeshya mu mezi make uko ikigo gihinduka rukikije.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_5, '5.2', 'Structure and Content of a Security Plan', 'Imiterere n''Ibirimo bya Gahunda y''Umutekano', 'text', 'The plan must be usable by someone who did not write it, under pressure, at night. A workable structure: scope and objectives; a summary of the assessment and the accepted risks; the site description with a map showing zones, entrances, exits and assembly points; the physical, procedural, technological and personnel controls in place; the staffing plan naming every post, its duties and its relief; the command structure with named roles; the communication plan and escalation route; emergency procedures for the foreseeable scenarios; the review cycle; and appendices with contact details, forms and the risk register. Keep it as short as accuracy allows, because a plan nobody finishes reading is a plan nobody follows.', 'Gahunda igomba gushobora gukoreshwa n''umuntu utari uwayanditse, ari mu gitutu, mu ijoro. Imiterere ikora: ibyo ireba n''intego; incamake y''isuzuma n''ibibazo byemewe; ibisobanuro by''ahantu n''ikarita yerekana utugari, inzira zinjirirwa, izisohokerwa n''ahantu ho guhurira; ibigenzura by''umubiri, iby''inzira z''akazi, iby''ikoranabuhanga n''iby''abakozi bihari; gahunda y''abakozi igena buri murimo, inshingano zawo n''uzasimbura; imiterere y''ubuyobozi hamwe n''imirimo yagenwe; gahunda y''itumanaho n''inzira yo kuzamura ikibazo; inzira zo gutabara ku bibazo bishobora guteganywa; uruziga rw''isuzuma; n''inyongera zirimo aho bavugishwa, imyandikire n''urutonde rw''ibyago. Igumishe ngufi uko ukuri kubyemera, kuko gahunda nta muntu uyisoza ari gahunda nta muntu uyikurikiza.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_5, '5.3', 'Writing Standard Operating Procedures', 'Kwandika Inzira z''Akazi Zisanzwe', 'text', 'A plan states what is required; an SOP states exactly how a person performs it. Each SOP should state: its purpose; who it applies to; the trigger that starts it; each step in sequence in plain language a new employee could follow; what record is created at each step; what to do when the procedure cannot be completed; and who to escalate to. Assign responsibility by role rather than by individual name, so the procedure survives staff changes. Keep it to one page. Then test it by having someone who did not write it follow it exactly, and revise every point where they had to interpret, because a procedure requiring interpretation is applied differently by every person who reads it.', 'Gahunda ivuga icyo bisaba; SOP ivuga neza uko umuntu agikora. Buri SOP igomba kuvuga: intego yayo; abo ireba; ikimenyetso kiyitangiza; buri ntambwe ku rutonde mu magambo yoroshye umukozi mushya yakurikiza; inyandiko ikorwa kuri buri ntambwe; icyo ukora igihe inzira idashobora kurangira; n''uwo uzamurira ikibazo. Hereza inshingano ku murimo aho kuzihereza ku izina ry''umuntu, kugira ngo inzira ibeho nyuma y''impinduka z''abakozi. Igumishe ku rupapuro rumwe. Hanyuma uyipime usaba umuntu utari uwayanditse kuyikurikiza uko iri, kandi ukosore buri hantu hose bahatiwe gusobanura, kuko inzira isaba gusobanura ikurikizwa mu buryo butandukanye na buri muntu uyisoma.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_5, '5.4', 'Reporting Findings to Management', 'Gutanga Ibyabonetse ku Buyobozi', 'text', 'An assessment that management does not act on has failed regardless of its technical quality. Lead with the conclusion, not the methodology: state the two or three most significant exposures, what they could cost, and what you recommend. Quantify wherever possible, because a figure competes for budget and an adjective does not. Present recommendations in cost order with owner and timescale, so that the no-cost items can be approved immediately. Avoid technical language the reader does not use, avoid presenting every finding with equal weight, and never rely on ''best practice'' as a justification. Include what you did not examine and why, since a report that states its own limits is more credible, not less.', 'Isuzuma ubuyobozi butakoraho ryaranganiwe uko ubuziranenge bwaryo bw''ikoranabuhanga bwaba bumeze kose. Tangirira ku mwanzuro, atari ku buryo bwakoreshejwe: vuga ibyago bibiri cyangwa bitatu bikomeye kurusha ibindi, ibyo byatwara, n''icyo utanga nk''icyifuzo. Tanga imibare aho bishoboka, kuko umubare uhatanira ingengo y''imari naho ijambo risobanura ntibishoboka. Tanga ibyifuzo ku rutonde rw''ikiguzi hamwe n''uwabishinzwe n''igihe, kugira ngo ibitagira ikiguzi byemezwe ako kanya. Irinde amagambo y''ikoranabuhanga umusomyi adakoresha, irinde gutanga buri kintu cyabonetse n''uburemere bumwe, kandi ntukigere wishingikiriza kuri ''inzira nziza'' nk''ibisobanuro. Shyiramo ibyo utasuzumye n''impamvu, kuko raporo ivuga imipaka yayo yizerwa kurusha, atari kugabanuka.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_5, '5.5', 'Implementation Planning and Change Management', 'Gutegura Gushyira mu Bikorwa no Gucunga Impinduka', 'text', 'A recommendation approved is not a control implemented. Implementation requires a sequence, an owner for each item, a date, a budget line, and a mechanism for verifying that the control was actually put in place and works. New controls also change how people work, and change fails where it is imposed without explanation: brief affected staff on what is changing and why, involve those who will operate the control in its final design, and expect a period of degradation as habits adjust. Verify after implementation rather than assuming — a control installed but never tested is not yet a control, and the gap between installation and verification is where most implementation failures hide.', 'Icyifuzo cyemejwe si igenzura ryashyizwe mu bikorwa. Gushyira mu bikorwa bisaba urutonde, uwabishinzwe kuri buri kintu, itariki, umurongo w''ingengo y''imari, n''uburyo bwo kwemeza ko igenzura ryashyizweho koko kandi rikora. Ibigenzura bishya kandi bihindura uko abantu bakora, kandi impinduka iranirwa aho ishyizweho nta bisobanuro: menyesha abakozi bireba icyo gihinduka n''impamvu, shyiramo abazakoresha igenzura mu igenamiterere ryaryo rya nyuma, kandi witegure igihe cyo kugabanuka uko imico ihinduka. Emeza nyuma yo gushyira mu bikorwa aho kwiyumvisha — igenzura ryashyizweho ariko ritigeze ripimwa ntabwo ririba igenzura, kandi icyuho hagati yo gushyiraho no kwemeza ni ho amakosa menshi yihisha.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-110', m_KG_110_5, 'Quiz — Writing the Security Plan', 'Ikizamini — Kwandika Gahunda y''Umutekano', 'quiz', 70, 5)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What makes a risk register a register rather than a snapshot?', 'Ni iki gituma urutonde rw''ibyago ruba urutonde aho kuba ifoto?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is reviewed at a defined interval and after any incident or change', 'Rusuzumwa ku gihe kigenwe na nyuma y''ikibazo cyangwa impinduka', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Vulnerability — a threat exists independently of you', 'Intege nke — iterabwoba ribaho ridashingiye kuri wowe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Could you answer an investigator with evidence rather than impression', 'Ese washobora gusubiza umushakashatsi ukoresheje ibimenyetso', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Delay time must exceed response time', 'Igihe cyo gutinza kigomba kurenza igihe cyo gutabara', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why assign SOP responsibility by role rather than by name?', 'Kuki uhereza inshingano za SOP ku murimo aho kuzihereza ku izina?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Record it as an information gap rather than assuming', 'Byandike nk''icyuho cy''amakuru aho kwiyumvisha', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Which controls are actually working and where single points of failure sit', 'Ibigenzura bikora koko n''aho hamwe hakwananirwa hari', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A hard perimeter with nothing behind it', 'Umurongo w''inyuma ukomeye nta kindi kiwuri inyuma', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'So the procedure survives staff changes', 'Kugira ngo inzira ibeho nyuma y''impinduka z''abakozi', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What should a management report lead with?', 'Raporo y''ubuyobozi igomba gutangirira ku iki?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'So the procedure survives staff changes', 'Kugira ngo inzira ibeho nyuma y''impinduka z''abakozi', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Whether the assessment and plan are still correct', 'Niba isuzuma na gahunda bikiri byo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The conclusion — the two or three most significant exposures, quantified', 'Umwanzuro — ibyago bibiri cyangwa bitatu bikomeye, bifite imibare', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It creates false assurance while the organisation believes it is protected', 'Ritanga icyizere cy''ibinyoma mu gihe ikigo cyizera ko kirinzwe', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Where do most implementation failures hide?', 'Amakosa menshi yo gushyira mu bikorwa yihisha he?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Controls are weakest at those times', 'Ibigenzura biba bidakomeye muri ibyo bihe', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'In the gap between installation and verification', 'Mu cyuho hagati yo gushyiraho no kwemeza', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Absent, poorly designed, or present but not followed', 'Ridahari, ryateguwe nabi, cyangwa ryarahari ntirikurikizwe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It protects what the writer assumed mattered and defaults to visible measures', 'Irinda ibyo uwayanditse yiyumvishije kandi ikajya ku ngamba zigaragara', false, 4);
end $$;
do $$ declare m_KG_110_6 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-110') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-110', 6, 'Review, Assurance and Continuous Improvement', 'Isuzuma, Kwemeza no Gukomeza Kunoza', 'This final module covers keeping an assessment and plan alive: testing whether controls still work, auditing, learning from incidents, and the professional standards governing this work.', 'Iki gice cya nyuma kigaruka ku kugumisha isuzuma na gahunda bikora: gupima niba ibigenzura bigikora, kugenzura, kwiga ku bibazo, n''amabwiriza y''umwuga agenga uyu murimo.', 6)
  returning id into m_KG_110_6;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_6, '6.1', 'Testing and Verifying Controls', 'Gupima no Kwemeza Ibigenzura', 'text', 'Controls degrade quietly. Staff change, workarounds develop, equipment fails without anyone noticing, and a procedure that was followed rigorously in month one is applied loosely by month twelve. Verification must therefore be active and periodic rather than assumed: physically test whether a door said to be locked is locked, whether an alarm actually reports to where it is supposed to, whether the response time is what the plan claims, and whether staff perform a procedure the way the SOP describes. Unannounced testing is essential, because a control that performs correctly only on known test dates is not a control at all.', 'Ibigenzura binangirika mu bwiherero. Abakozi barahinduka, uburyo bwo kubizenguruka buravuka, ibikoresho birapfa nta muntu ubibonye, kandi inzira y''akazi yakurikizwaga neza mu kwezi kwa mbere ikurikizwa mu buryo bworoheje mu kwezi kwa cumi n''abiri. Kwemeza rero bigomba kuba ibikorwa kandi bibaho ku gihe aho kwiyumvishwa: pima mu buryo bw''umubiri niba umuryango bavuga ko ufunze ufunze, niba induru itanga amakuru aho igomba, niba igihe cyo gutabara ari cyo gahunda ivuga, kandi niba abakozi bakora inzira y''akazi nk''uko SOP ibisobanura. Gupima utamenyesheje ni ngombwa, kuko igenzura rikora neza gusa ku matariki y''ipimwa azwi atari igenzura na gato.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_6, '6.2', 'Auditing the Assessment and Plan', 'Kugenzura Isuzuma na Gahunda', 'text', 'Audit asks a different question from verification: not whether a control works, but whether the assessment and plan are still correct. The organisation changes — new premises, new systems, new staff, new activities, new regulation — and an assessment describes a moment that recedes. Audit therefore checks: are the assets still the right assets; have new threats emerged; do the scores still reflect current likelihood; are accepted risks still acceptable; and has anything been implemented that changed the residual risk. Findings are graded by severity, assigned an owner and a closure date, and tracked. An audit programme that produces reports but never closes findings has documented weaknesses without correcting them.', 'Igenzura ryibaza ikibazo gitandukanye n''ukwemeza: atari niba igenzura rikora, ahubwo niba isuzuma na gahunda bikiri byo. Ikigo kirahinduka — ahantu hashya, sisitemu nshya, abakozi bashya, ibikorwa bishya, amategeko mashya — kandi isuzuma risobanura akanya kagenda gasubira inyuma. Igenzura rero rigenzura: ese umutungo ukiri wo; ese hari iterabwoba rishya ryavutse; ese amanota akigaragaza amahirwe y''ubu; ese ibibazo byemewe bikiri byemerwa; kandi ese hari icyashyizwe mu bikorwa cyahinduye ikibazo gisigaye. Ibyavuyemo bitondekwa ku buremere, bigahabwa uwabishinzwe n''itariki yo gukemuka, kandi bigakurikiranwa. Gahunda y''igenzura itanga raporo itigera ikemura ibyavuyemo iba yanditse intege nke itabikosoye.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_6, '6.3', 'Learning from Incidents and Near-Misses', 'Kwiga ku Bibazo n''Ibyari Hafi Kubaho', 'text', 'Every incident contains information about a control that failed, and the value of that information is realised only if it changes the control rather than merely punishing an individual. A structured review asks: what was supposed to happen, what actually happened, where did they diverge, and was the control absent, poorly designed, or present but not followed — because each of those three requires a completely different remedy. Near-misses must be reviewed with the same rigour, since they contain identical lessons at no cost. Feed every finding back into the risk register, because an incident that does not change the register has taught the organisation nothing durable.', 'Buri kibazo kirimo amakuru ku igenzura ryananiranye, kandi agaciro k''ayo makuru kagerwaho gusa iyo ahinduye igenzura aho guhana umuntu gusa. Isuzuma riteguye ryibaza: ni iki cyagombye kuba, ni iki cyabaye koko, ni hehe byatandukaniye, kandi ese igenzura ryari ridahari, ryateguwe nabi, cyangwa ryari rihari ariko ntirikurikizwe — kuko buri kimwe muri ibyo bitatu gisaba igisubizo gitandukanye burundu. Ibyari hafi kubaho bigomba gusuzumwa umurava umwe, kuko birimo amasomo amwe nta kiguzi. Subiza buri kintu cyabonetse mu rutonde rw''ibyago, kuko ikibazo kitahinduye urutonde nta cyo cyigishije ikigo kirambye.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_6, '6.4', 'Professional Ethics in Assessment Work', 'Ubunyangamugayo bw''Umwuga mu Murimo w''Isuzuma', 'text', 'An assessor holds significant influence over what an organisation spends and what it believes about its own exposure, and that carries obligations. Report what you found, including findings a client would prefer not to hear, because an assessment that omits an inconvenient exposure is worse than no assessment: it creates documented false assurance. Never recommend a product or supplier in which you hold an interest without declaring it. Do not inflate risk to justify expenditure, and do not deflate it to secure a contract renewal. Respect the confidentiality of everything you see, since an assessment necessarily documents exactly where an organisation is weakest — which makes the report itself a security risk requiring controlled handling.', 'Umusuzumyi afite ububasha bukomeye ku byo ikigo gikoresha n''ibyo cyizera ku byago cyacyo, kandi ibyo bifite inshingano. Tanga raporo ku byo wabonye, harimo n''ibyo umukiriya yakwifuza kutumva, kuko isuzuma risiga ikibazo kidashimishije ari bibi kurusha kutagira isuzuma: ritanga icyizere cy''ibinyoma cyanditse. Ntukigere utanga icyifuzo cy''igicuruzwa cyangwa uwagitanga ufitemo inyungu utabitangaje. Ntukongere ikibazo kugira ngo wemeze gukoresha amafaranga, kandi ntugikuremo kugira ngo wemeze kongera amasezerano. Ubahiriza ibanga ry''ibyo wabonye byose, kuko isuzuma ryandika neza aho ikigo gifite intege nke — bigatuma raporo ubwayo iba ikibazo cy''umutekano gisaba gucungwa neza.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_110_6, '6.5', 'Continuous Improvement and Professional Development', 'Gukomeza Kunoza n''Iterambere ry''Umwuga', 'text', 'Security risk assessment is among the most portable competencies in this profession, because the method transfers across sectors: the same logic applies to a bank, a hotel, a hospital, a factory or a public event. Development directions include specialising in a sector, moving into corporate security management, internal audit or business continuity, or working as an independent consultant. Recognised risk management qualifications improve mobility substantially. The strongest development habit is documentation: keep your assessments, matrices, plans and post-implementation verifications, because a portfolio of real analytical work is what distinguishes a candidate from someone who can only describe the theory.', 'Isuzuma ry''ibyago by''umutekano ni bumwe mu bumenyi bwimuka cyane muri uyu mwuga, kuko uburyo bugenda mu nzego zose: ubwenge bumwe bukoreshwa kuri banki, ihoteri, ibitaro, uruganda cyangwa ibirori rusange. Icyerekezo cy''iterambere kirimo kwibanda ku rwego rumwe, kwimukira mu micungire y''umutekano w''ikigo, igenzura ry''imbere cyangwa gukomeza kw''ubucuruzi, cyangwa gukora nk''umujyanama wigenga. Ibyemezo byemewe by''imicungire y''ibyago byongera cyane ubushobozi bwo kwimuka. Umuco ukomeye w''iterambere ni inyandiko: bika amasuzuma yawe, imbonerahamwe, gahunda n''ibyo wemeje nyuma yo gushyira mu bikorwa, kuko ububiko bw''umurimo nyawo wo gusesengura ari bwo butandukanya ukandida n''ushobora gusobanura inyigisho gusa.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-110', m_KG_110_6, 'Quiz — Review, Assurance and Continuous Improvement', 'Ikizamini — Isuzuma, Kwemeza no Gukomeza Kunoza', 'quiz', 70, 6)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'Why is unannounced testing essential?', 'Kuki gupima utamenyesheje ari ngombwa?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that works only on known test dates is not a control', 'Igenzura rikora gusa ku matariki azwi si igenzura', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Vulnerability — a threat exists independently of you', 'Intege nke — iterabwoba ribaho ridashingiye kuri wowe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Could you answer an investigator with evidence rather than impression', 'Ese washobora gusubiza umushakashatsi ukoresheje ibimenyetso', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Delay time must exceed response time', 'Igihe cyo gutinza kigomba kurenza igihe cyo gutabara', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What question does audit ask that verification does not?', 'Ni ikihe kibazo igenzura ryibaza kwemeza kutabaza?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Record it as an information gap rather than assuming', 'Byandike nk''icyuho cy''amakuru aho kwiyumvisha', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Which controls are actually working and where single points of failure sit', 'Ibigenzura bikora koko n''aho hamwe hakwananirwa hari', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A hard perimeter with nothing behind it', 'Umurongo w''inyuma ukomeye nta kindi kiwuri inyuma', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Whether the assessment and plan are still correct', 'Niba isuzuma na gahunda bikiri byo', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Name the three possible states of a failed control.', 'Vuga imimerere itatu ishoboka y''igenzura ryananiranye.', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'So the procedure survives staff changes', 'Kugira ngo inzira ibeho nyuma y''impinduka z''abakozi', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A control that works only on known test dates is not a control', 'Igenzura rikora gusa ku matariki azwi si igenzura', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Absent, poorly designed, or present but not followed', 'Ridahari, ryateguwe nabi, cyangwa ryarahari ntirikurikizwe', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It creates false assurance while the organisation believes it is protected', 'Ritanga icyizere cy''ibinyoma mu gihe ikigo cyizera ko kirinzwe', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why is a security assessment report itself a security risk?', 'Kuki raporo y''isuzuma ry''umutekano ubwayo ari ikibazo cy''umutekano?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Controls are weakest at those times', 'Ibigenzura biba bidakomeye muri ibyo bihe', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It documents exactly where the organisation is weakest', 'Yandika neza aho ikigo gifite intege nke', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Whether the assessment and plan are still correct', 'Niba isuzuma na gahunda bikiri byo', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It protects what the writer assumed mattered and defaults to visible measures', 'Irinda ibyo uwayanditse yiyumvishije kandi ikajya ku ngamba zigaragara', false, 4);
end $$;
