-- ---------- KG-111 · Security Operations & Incident Management ----------
do $$ declare m_KG_111_1 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-111') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-111', 1, 'Foundations of Security Operations', 'Ishingiro ry''Ibikorwa by''Umutekano', 'This module establishes how a security operation actually runs day to day: post orders, shift structure, handover, the control room, and the discipline that keeps standards constant when nobody is watching.', 'Iki gice gishyiraho uko ibikorwa by''umutekano bikora buri munsi: amabwiriza y''aho ukorera, imiterere y''akazi, guhererekanya, icyumba cy''igenzura, n''umurava ugumisha urwego igihe nta muntu ureba.', 1)
  returning id into m_KG_111_1;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_1, '1.1', 'What Security Operations Actually Means', 'Icyo Ibikorwa by''Umutekano Bisobanura by''Ukuri', 'text', 'Security operations is the continuous, repeatable delivery of protection — as distinct from planning it or assessing it. It is measured not by what happens on an exceptional day but by whether the standard holds on ordinary ones, because an operation that performs well only when observed provides no protection during the hours it is not. The core components are: defined post orders for every position; a shift structure with reliable relief; a documented handover at every change; a control room or coordination point; a communication system with defined channels and escalation; a documentation regime; and a supervisory cycle that verifies rather than assumes. Weakness in any one of these degrades all the others.', 'Ibikorwa by''umutekano ni ugutanga kurinda buhoraho kandi bishobora gusubirwamo — bitandukanye no kubitegura cyangwa kubisuzuma. Bipimwa atari ku byabaye ku munsi udasanzwe ahubwo ku kuba urwego rugumaho ku minsi isanzwe, kuko ibikorwa bikora neza gusa iyo bigenzurwa nta kurinda bitanga mu masaha bitagenzurwa. Ibigize ni ibi: amabwiriza yagenwe y''aho ukorera ku buri murimo; imiterere y''akazi ifite gusimburana kwizewe; guhererekanya kwanditse kuri buri mpinduka; icyumba cy''igenzura cyangwa ahantu ho guhuza; sisitemu y''itumanaho ifite imirongo yagenwe n''inzira yo kuzamura ikibazo; uburyo bwo kwandika; n''uruziga rw''ubugenzuzi rwemeza aho kwiyumvisha. Intege nke ku kimwe muri ibi zangiza ibindi byose.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_1, '1.2', 'Post Orders and Assignment Instructions', 'Amabwiriza y''Aho Ukorera n''Ay''Umurimo', 'text', 'Post orders are the written instructions defining exactly how duties are performed at one specific position: which doors are checked and how often, who is authorised to enter which area, what to do when a particular alarm activates, what records are kept, and who to call in each category of situation. They must be site-specific and position-specific rather than generic, because the details that differ between posts are precisely the details that cause failures. Officers must read the post orders for every new assignment rather than assuming a site works like the last one. Where post orders are unclear, contradictory or impossible to follow, raise it with a supervisor rather than quietly improvising a substitute that nobody else knows about.', 'Amabwiriza y''aho ukorera ni inyandiko igena neza uko inshingano zikorwa ku murimo umwe wihariye: ni izihe nzugi zigenzurwa n''inshuro zingahe, ni nde wemerewe kwinjira mu kihe gice, icyo ukora iyo induru runaka ivuze, ni izihe nyandiko zibikwa, n''uwo uhamagara kuri buri bwoko bw''ikibazo. Agomba kuba ayihariye ku hantu no ku murimo aho kuba rusange, kuko ibitandukanye hagati y''imirimo ari byo bitera ibibazo. Abakozi bagomba gusoma amabwiriza y''aho bakorera kuri buri kazi gashya aho kwiyumvisha ko ahantu hakora kimwe n''aho bavuye. Aho amabwiriza atasobanutse, avuguruzanya cyangwa adashobora gukurikizwa, bibwire umuyobozi aho kwikorera icyo wiyumvisha nta wundi uzi.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_1, '1.3', 'Shift Structure, Relief and Fatigue', 'Imiterere y''Akazi, Gusimburana n''Umunaniro', 'text', 'Fatigue degrades observation, judgement and reaction measurably, which makes shift design a safety control rather than a welfare matter. Officers must be relieved for breaks, must be able to eat and hydrate, and should not be holding a critical post at the end of an unbroken long shift when attention is lowest. Relief must be planned rather than improvised: a post left because relief did not arrive is an unprotected post, and an officer who stays beyond their shift because nobody came is being set up to fail. Night shifts carry particular risk because both alertness and supervision are at their lowest simultaneously, which is why unannounced night supervision matters more than daytime supervision.', 'Umunaniro ugabanya kwitegereza, ubushishozi n''igisubizo mu buryo bugaragara, bigatuma igenamiterere ry''akazi ari igenzura ry''umutekano aho kuba ikibazo cy''ubugwaneza. Abakozi bagomba gusimburwa mu biruhuko, bagomba gushobora kurya no kunywa, kandi ntibagomba kuba ku murimo w''ingenzi ku iherezo ry''akazi karekare kadacitse ubwitonzi buri hasi. Gusimburana kugomba guteganywa aho kwikorwa: umurimo wasizwe kuko uzasimbura atageze ni umurimo utarinzwe, kandi umukozi usigara nyuma y''akazi ke kuko nta muntu waje aba ashyizwe mu mwanya wo kunanirwa. Akazi ko mu ijoro gafite ibyago byihariye kuko kuba maso n''ubugenzuzi biba biri hasi icyarimwe, ni yo mpamvu ubugenzuzi bwo mu ijoro butamenyeshejwe bufite akamaro kurusha ubwo ku manywa.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_1, '1.4', 'Handover: Transferring Situational Knowledge', 'Guhererekanya: Guhererekanya Ubumenyi bw''Ibimeze', 'text', 'A shift change is one of the most vulnerable moments in any operation, because knowledge held by one officer can be lost entirely if it is not transferred. A proper handover covers: anything unusual observed during the shift; any equipment fault; any area currently unsecured; any person of interest still on site; any instruction received from a supervisor that the incoming officer must act on; and the status of any ongoing incident. The outgoing officer does not leave until the incoming officer has physically arrived, received the briefing and confirmed understanding. Record the handover, because an undocumented handover is indistinguishable from no handover when an incident is reviewed afterwards.', 'Guhinduranya akazi ni kimwe mu bihe by''intege nke cyane mu bikorwa byose, kuko ubumenyi umukozi umwe afite bushobora gutakara burundu nibudahererekanywa. Guhererekanya neza bikubiyemo: ikintu cyose kidasanzwe cyabonetse mu gihe cy''akazi; ikibazo cyose cy''ibikoresho; agace kose katarinzwe muri iki gihe; umuntu wese ushishikaje ukiri ku hantu; itegeko iryo ari ryo ryose ryavuye ku muyobozi umukozi uje agomba gukurikiza; n''aho ikibazo kiri gukomeza kigeze. Umukozi usoza ntagenda kugeza umukozi uje ageze by''ukuri, ahawe amakuru kandi yemeje ko yumvise. Andika guhererekanya, kuko guhererekanya kutanditse kudatandukanywa no kutabaho igihe ikibazo gisuzumwa nyuma.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_1, '1.5', 'The Control Room and Coordination Point', 'Icyumba cy''Igenzura n''Ahantu ho Guhuza', 'text', 'The control room is where information from every post converges and where coordination happens during an incident. Its functions are: monitoring surveillance and alarm systems; maintaining the occurrence log; receiving and directing radio traffic; holding the current status of every post; initiating escalation; and coordinating the response. Monitoring must be active rather than passive: an operator should scan screens in a deliberate rotating pattern rather than fixating on one, and should know exactly which camera covers which blind spot on the physical patrol route. During an incident, the control room does not become a crowd — only those with a defined role should be present, because a control room full of people watching is a control room where nobody can hear the radio.', 'Icyumba cy''igenzura ni aho amakuru ava ku murimo wose ahurira n''aho guhuza bibera mu gihe cy''ikibazo. Imirimo yacyo ni iyi: gukurikirana kamera na sisitemu z''induru; kubungabunga igitabo cy''ibibaye; kwakira no kuyobora ubutumwa bwa radio; kugumana aho buri murimo ugeze; gutangiza kuzamura ikibazo; no guhuza igisubizo. Gukurikirana bigomba kuba ibikorwa aho kuba ukwiringira: ukoresha agomba kureba ecran mu buryo buzenguruka ku bushake aho kwibanda ku imwe, kandi akamenya neza ni iyihe kamera igenzura iki cyuho ku nzira ya patrouille. Mu gihe cy''ikibazo, icyumba cy''igenzura ntikigomba guhinduka imbaga — abafite umurimo wagenwe gusa ni bo bagomba kuhaba, kuko icyumba cy''igenzura cyuzuye abantu bareba ari icyumba nta muntu ushobora kumva radio.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-111', m_KG_111_1, 'Quiz — Foundations of Security Operations', 'Ikizamini — Ishingiro ry''Ibikorwa by''Umutekano', 'quiz', 70, 1)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'How is a security operation properly measured?', 'Ibikorwa by''umutekano bipimwa bite neza?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'By whether the standard holds on ordinary days, not exceptional ones', 'N''uko urwego rugumaho ku minsi isanzwe, atari idasanzwe', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The details that differ between posts are exactly what causes failures', 'Ibitandukanye hagati y''imirimo ni byo bitera ibibazo', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Location, observation and requirement stated specifically', 'Ahantu, icyabonetse n''icyo usaba bivuzwe neza', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To support — clearing routes, access, information — not to keep directing', 'Gushyigikira — gufungura inzira, abinjira, amakuru — atari gukomeza kuyobora', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why must post orders be site- and position-specific?', 'Kuki amabwiriza y''aho ukorera agomba kuba ayihariye ku hantu no ku murimo?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Protect life, contain the situation, notify', 'Kurinda ubuzima, kugarura ikibazo, gutangaza', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'No backup, no witness and no clear exit plan', 'Nta bufasha, nta muhamya kandi nta nzira isobanutse', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Those who talk adopt each other''s version unconsciously', 'Abavugana bemera verisiyo za bagenzi babo batabishaka', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The details that differ between posts are exactly what causes failures', 'Ibitandukanye hagati y''imirimo ni byo bitera ibibazo', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Why does night shift carry particular risk?', 'Kuki akazi ko mu ijoro gafite ibyago byihariye?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The officer', 'Umukozi', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It contains the same lesson at no human cost', 'Kirimo isomo rimwe nta gihombo cy''ubuzima', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Alertness and supervision are at their lowest simultaneously', 'Kuba maso n''ubugenzuzi biri hasi icyarimwe', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The item may become unusable as evidence entirely', 'Ikintu gishobora kutakoreshwa nk''ikimenyetso', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'When may an outgoing officer leave?', 'Ni ryari umukozi usoza yagenda?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'So escalation is triggered by the situation, not by how sure an officer feels', 'Kugira ngo kuzamura biterwe n''uko bimeze, atari uko umukozi yiyumva', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Only after the incoming officer has arrived, been briefed and confirmed understanding', 'Nyuma gusa y''uko uje ageze, amenyeshejwe kandi yemeje ko yumvise', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Officers learn to conceal distress, which is worse for them and the operation', 'Abakozi biga guhisha imibabaro, ari bibi kuri bo n''ibikorwa', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The details that differ between posts are exactly what causes failures', 'Ibitandukanye hagati y''imirimo ni byo bitera ibibazo', false, 4);
end $$;
do $$ declare m_KG_111_2 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-111') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-111', 2, 'Communication and Command Structure', 'Itumanaho n''Imiterere y''Ubuyobozi', 'This module covers how information moves during normal operations and during an incident: radio discipline, the escalation route, who holds command, and how briefings are delivered.', 'Iki gice kigaruka ku buryo amakuru agenda mu bikorwa bisanzwe no mu gihe cy''ikibazo: umurava kuri radio, inzira yo kuzamura ikibazo, ufite ubuyobozi, n''uko amakuru atangwa.', 2)
  returning id into m_KG_111_2;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_2, '2.1', 'Radio Discipline and Transmission Protocol', 'Umurava kuri Radio n''Uburyo bwo Kohereza Ubutumwa', 'text', 'A radio channel is a shared operational resource that must remain immediately available, which means it is never used for conversation, jokes or complaints about colleagues. Transmissions follow a fixed structure: state your call sign, wait for acknowledgement, then deliver the message in short phrases stating location, observation and requirement. Reports must be specific: a transmission saying ''there''s a problem at the back'' tells the control room nothing actionable, while ''Post 4, service door at the north loading bay found open, no persons visible, requesting supervisor'' allows an immediate decision. Test every radio at the start of every shift, and know where coverage fails, because discovering a dead zone during an incident is a discovery made too late.', 'Umurongo wa radio ni umutungo w''akazi usangiwe ugomba kuguma ushobora gukoreshwa ako kanya, bivuze ko utigera ukoreshwa mu biganiro, urwenya cyangwa ibirego ku bo mukorana. Ubutumwa bukurikiza imiterere idahinduka: vuga izina ryawe rya radio, tegereza kwemererwa, hanyuma utange ubutumwa mu magambo magufi uvuga ahantu, icyabonetse n''icyo usaba. Raporo zigomba kuba zihariye: ubutumwa buvuga ''hari ikibazo inyuma'' nta cyo bubwira icyumba cy''igenzura gishobora gukorwa, mu gihe ''Umurimo wa 4, umuryango w''ibikorwa ku ruhande rw''amajyaruguru wabonetse ufunguye, nta bantu bagaragara, ndasaba umuyobozi'' butuma hafatwa icyemezo ako kanya. Suzuma buri radio mu ntangiriro ya buri kazi, kandi umenye aho itagera, kuko kumenya aho idakora mu gihe cy''ikibazo ari ukumenya bitinze.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_2, '2.2', 'The Escalation Route', 'Inzira yo Kuzamura Ikibazo', 'text', 'An escalation route defines in advance who an officer reports to, who that person escalates to, at what threshold each step occurs, and who is authorised to contact external emergency services. Thresholds must be stated so that escalation is triggered by a condition rather than by an officer''s confidence: ''any injury requiring more than basic first aid'' is a threshold, ''if it seems serious'' is not. Only one designated person should contact each external service, because multiple officers independently calling the same service wastes response capacity and produces conflicting information. Officers must know the route without looking it up, since an officer unsure who to call will wait, and waiting is the most common form of escalation failure.', 'Inzira yo kuzamura ikibazo igena mbere umukozi atangira raporo kuri nde, uwo muntu azamurira kuri nde, ni ku ruhe rwego buri ntambwe ibera, n''uwemerewe kuvugana n''abatabazi bo hanze. Inzego zigomba kuvugwa kugira ngo kuzamura ikibazo biterwe n''imimerere aho biterwa n''icyizere cy''umukozi: ''ikomere iryo ari ryo ryose risaba birenze ubufasha bw''ibanze'' ni urwego, ''niba bisa n''ibikomeye'' si urwego. Umuntu umwe wagenwe gusa ni we ugomba kuvugana na buri rwego rwo hanze, kuko abakozi benshi bahamagara buri wese ukwe batakaza ubushobozi bwo gutabara kandi bagatanga amakuru avuguruzanya. Abakozi bagomba kumenya inzira batayirebye, kuko umukozi utazi uwo ahamagara azategereza, kandi gutegereza ni bwo buryo bukunze kubaho bwo kunanirwa kuzamura ikibazo.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_2, '2.3', 'Command Structure During an Incident', 'Imiterere y''Ubuyobozi mu Gihe cy''Ikibazo', 'text', 'Every operation must have one named incident commander and a named deputy, identified by position rather than by individual so the structure survives staff changes and absences. Ambiguity about who decides is the most common cause of delayed response, because officers who are unsure of the chain wait for permission nobody is issuing. The commander holds decision authority, allocates tasks, controls the flow of information, and decides when to escalate or hand over to an external service. Everyone else executes and reports. A common failure is a commander who becomes absorbed in performing a task personally and therefore stops commanding, which leaves the whole operation without direction at the moment it most needs it.', 'Buri bikorwa bigomba kugira umuyobozi umwe wagenwe w''ikibazo n''umusimbura wagenwe, bamenyekana ku mwanya aho kumenyekana ku muntu kugira ngo imiterere ibeho nyuma y''impinduka z''abakozi n''ubudahari. Kutamenya uwo ufata icyemezo ni yo mpamvu ikunze gutera gutinda kw''igisubizo, kuko abakozi batazi urutonde bategereza uruhushya nta muntu urutanga. Umuyobozi afite ububasha bwo gufata ibyemezo, agahereza imirimo, akagenzura uko amakuru agenda, kandi agafata icyemezo cy''igihe cyo kuzamura ikibazo cyangwa kugihererekanya ku rwego rwo hanze. Abandi bose barakora bagatanga raporo. Ikosa risanzwe ni umuyobozi wibanda ku gukora umurimo ku giti cye bityo agahagarika kuyobora, bigasiga ibikorwa byose nta cyerekezo mu gihe bibikeneye cyane.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_2, '2.4', 'Briefing and Task Assignment', 'Kumenyesha no Guhereza Imirimo', 'text', 'Every officer must be briefed before deployment, and the briefing should cover the same points every time so nothing is omitted under time pressure: the situation; each officer''s specific post and duties; zone boundaries and access rules; the command structure and who to call; radio channels and call signs; emergency procedures and the assembly point; relief arrangements; and any specific risk identified for this shift or site. Confirm understanding by asking an officer to state their post and their first action in an emergency, rather than asking whether everyone understood — the second question produces agreement, not comprehension, and agreement is worthless at three in the morning.', 'Buri mukozi agomba kumenyeshwa mbere yo gushyirwa ku murimo, kandi kumenyesha kugomba gukubiyemo ingingo zimwe buri gihe kugira ngo nta kirengagizwa mu gitutu cy''igihe: uko ibintu bimeze; umurimo wihariye wa buri mukozi n''inshingano ze; imbibi z''utugari n''amategeko yo kwinjira; imiterere y''ubuyobozi n''uwo bahamagara; imirongo ya radio n''amazina; inzira z''ibyihutirwa n''ahantu ho guhurira; uburyo bwo gusimburana; n''ikibazo cyihariye cyamenyekanye kuri aka kazi cyangwa aha hantu. Emeza ko basobanukiwe usaba umukozi kuvuga umurimo we n''igikorwa cye cya mbere mu byihutirwa, aho kubaza niba bose basobanukiwe — ikibazo cya kabiri gitanga kwemera, atari gusobanukirwa, kandi kwemera nta gaciro gifite saa cyenda z''ijoro.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_2, '2.5', 'Coordinating with External Services', 'Guhuza n''Inzego zo Hanze', 'text', 'External services should be engaged before they are needed, not summoned for the first time during an incident. Where the site warrants it, provide police, ambulance and fire services in advance with the site map, access routes, gate codes or contact arrangements, and the name and number of the person who will meet them. Agree in advance the point at which command transfers: for most incidents the security operation retains command, but for a declared major incident command passes to the emergency service. After handover the security team supports — clearing routes, controlling access, providing information — rather than continuing to direct. Always verify the identity of anyone presenting as an official before granting access.', 'Inzego zo hanze zigomba kwinjizwa mbere y''uko zikenerwa, atari guhamagarwa bwa mbere mu gihe cy''ikibazo. Aho ahantu habisaba, ha polisi, ambulance n''abazimya inkongi mbere ikarita y''ahantu, inzira zinjirirwa, kode z''amarembo cyangwa uburyo bwo kubavugisha, n''izina na nimero by''uzabakira. Mwumvikane mbere ku gihe ubuyobozi bwimurwa: ku bibazo byinshi ibikorwa by''umutekano biguma bifite ubuyobozi, ariko ku kibazo gikomeye cyatangajwe ubuyobozi bujya ku rwego rw''abatabazi. Nyuma yo guhererekanya itsinda ry''umutekano rishyigikira — gufungura inzira, kugenzura abinjira, gutanga amakuru — aho gukomeza kuyobora. Buri gihe emeza indangamuntu y''uwivuga ko ari uw''inzego mbere yo kumwemerera kwinjira.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-111', m_KG_111_2, 'Quiz — Communication and Command Structure', 'Ikizamini — Itumanaho n''Imiterere y''Ubuyobozi', 'quiz', 70, 2)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What makes a radio report actionable?', 'Ni iki gituma raporo ya radio ikorwaho?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Location, observation and requirement stated specifically', 'Ahantu, icyabonetse n''icyo usaba bivuzwe neza', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'By whether the standard holds on ordinary days, not exceptional ones', 'N''uko urwego rugumaho ku minsi isanzwe, atari idasanzwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Only after the incoming officer has arrived, been briefed and confirmed understanding', 'Nyuma gusa y''uko uje ageze, amenyeshejwe kandi yemeje ko yumvise', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To support — clearing routes, access, information — not to keep directing', 'Gushyigikira — gufungura inzira, abinjira, amakuru — atari gukomeza kuyobora', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why must escalation thresholds be conditions rather than confidence levels?', 'Kuki inzego zo kuzamura ikibazo zigomba kuba imimerere aho kuba urwego rw''icyizere?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Protect life, contain the situation, notify', 'Kurinda ubuzima, kugarura ikibazo, gutangaza', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'No backup, no witness and no clear exit plan', 'Nta bufasha, nta muhamya kandi nta nzira isobanutse', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Those who talk adopt each other''s version unconsciously', 'Abavugana bemera verisiyo za bagenzi babo batabishaka', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'So escalation is triggered by the situation, not by how sure an officer feels', 'Kugira ngo kuzamura biterwe n''uko bimeze, atari uko umukozi yiyumva', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What is the most common cause of delayed incident response?', 'Ni iyihe mpamvu ikunze gutera gutinda kw''igisubizo?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The officer', 'Umukozi', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
