  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Ambiguity about who holds decision authority', 'Kutamenya ufite ububasha bwo gufata icyemezo', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
