do $$ declare m_KG_111_3 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-111') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-111', 3, 'Incident Response', 'Gutabara Ikibazo', 'This module covers what an officer actually does when something happens: the fixed priority sequence, the first sixty seconds, and the standard responses for the incident types most likely to occur.', 'Iki gice kigaruka ku byo umukozi akora koko igihe hari ikibaye: urutonde rw''ibanze rudahinduka, amasegonda mirongo itandatu ya mbere, n''ibisubizo bisanzwe ku bwoko bw''ibibazo bikunze kubaho.', 3)
  returning id into m_KG_111_3;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_3, '3.1', 'The Fixed Priority Sequence', 'Urutonde rw''Ibanze Rudahinduka', 'text', 'Whatever the incident — fire, injury, intrusion, theft, disorder, accident — the order of priority is fixed and does not change with circumstance. First, protect human life, including your own. Second, contain the situation so it does not worsen or spread. Third, notify the appropriate supervisor or authority. An officer who telephones a supervisor before assisting an injured person, or who pursues an intruder while others remain in danger, has inverted the sequence however well-intentioned the action. Commit this order to memory rather than to a document, because the value of a fixed sequence is that it allows correct action under pressure when there is no time to deliberate and no opportunity to look anything up.', 'Uko ikibazo cyaba kimeze kose — inkongi, gukomereka, kwinjira mu buryo butemewe, ubujura, akajagari, impanuka — urutonde rw''ibanze ni rumwe kandi ntiruhinduka bitewe n''ibihe. Icya mbere, kurinda ubuzima bw''abantu, harimo n''ubwawe. Icya kabiri, kugarura ikibazo kugira ngo kitiyongera cyangwa ngo gikwire. Icya gatatu, kumenyesha umuyobozi cyangwa ubuyobozi bubishinzwe. Umukozi uhamagara umuyobozi mbere yo gufasha uwakomeretse, cyangwa ukurikirana uwinjiye mu gihe abandi bakiri mu kaga, aba yacuritse urutonde n''ubwo igikorwa cye cyaba gifite intego nziza. Iga uru rutonde ku mutwe aho kurwandika mu nyandiko, kuko agaciro k''urutonde rudahinduka ari uko rutuma ukora neza mu gitutu igihe nta kanya ko gutekereza kandi nta bushobozi bwo kureba ikintu.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_3, '3.2', 'The First Sixty Seconds', 'Amasegonda Mirongo Itandatu ya Mbere', 'text', 'What an officer does in the first minute usually determines how the whole incident goes. The sequence is: assess your own safety before approaching, because an officer who becomes a second casualty helps nobody; establish what is actually happening rather than what it appears to be; act on the priority sequence; transmit a specific report giving location, nature and requirement; and prevent the situation from expanding — keep people back, keep routes clear, do not allow a crowd to form. Avoid two common errors: rushing in without assessing, and freezing while waiting for instruction. Where you are genuinely unsure, secure the area and report; that is always a defensible action.', 'Icyo umukozi akora mu munota wa mbere akenshi kigena uko ikibazo cyose kizagenda. Urutonde ni: suzuma umutekano wawe mbere yo kwegera, kuko umukozi uhinduka uwakomeretse wa kabiri nta muntu afasha; menya ibiri kubaho koko aho kumenya ibigaragara; kora ukurikije urutonde rw''ibanze; ohereza raporo yihariye ivuga ahantu, ubwoko n''icyo usaba; kandi wirinde ko ikibazo cyagura — gumisha abantu inyuma, gumisha inzira zifunguye, ntukemerere imbaga guteranira aho. Wirinde amakosa abiri asanzwe: kwiruka winjira utabanje gusuzuma, no guhagarara ubura icyo ukora utegereje itegeko. Aho utazi neza, rinda agace utange raporo; iryo ni igikorwa gishobora kwiregurwa buri gihe.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_3, '3.3', 'Medical Emergencies and Injury', 'Ibibazo bya Muganga no Gukomereka', 'text', 'In a medical emergency the officer''s role is to stabilise the situation until qualified help arrives, not to attempt treatment beyond their training. Do not move an injured person unless an immediate greater danger requires it, since movement can worsen a spinal or internal injury. Send another person to summon medical assistance rather than leaving the casualty, and stay with them. Clear the area of onlookers, both for the casualty''s dignity and to keep the access route open. Note the exact time, what you observed, and what you did, because that information is what the arriving medical team needs first. Assign one officer to meet the ambulance and guide it directly rather than leaving it to find the location.', 'Mu kibazo cya muganga cyihutirwa uruhare rw''umukozi ni ugutuza ikibazo kugeza ubufasha bufite ubumenyi bugeze, atari kugerageza kuvura birenze amahugurwa ye. Ntukimure uwakomeretse keretse akaga gakomeye kegereje kabisabye, kuko kwimuka bishobora kwongera ikomere ry''urutirigongo cyangwa iry''imbere. Ohereza undi muntu gushaka ubufasha bwa muganga aho gusiga uwakomeretse, kandi ugume na we. Kura abareba mu gace, ku bw''icyubahiro cy''uwakomeretse no kugira ngo inzira igume ifunguye. Andika isaha nyayo, icyo wabonye, n''icyo wakoze, kuko ayo makuru ari yo itsinda rya muganga rigeze rikeneye mbere. Gena umukozi umwe wo kwakira ambulance ayiyobore aho kuyireka ngo ishakishe ahantu.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_3, '3.4', 'Fire, Evacuation and Environmental Incidents', 'Inkongi, Kwimuka n''Ibibazo by''Ibidukikije', 'text', 'For fire, the first actions are to raise the alarm and initiate evacuation. Attempting to fight a fire is appropriate only for a small, contained fire using the correct extinguisher class, and never at the cost of delaying evacuation. During evacuation, officers actively direct people toward the nearest safe exit rather than assuming they will find it, since most people leave by the route they entered even when a nearer exit exists. Never use lifts. Direct people onward to the assembly point rather than allowing them to stop outside the door, which blocks those still emerging. Assist with the headcount so that anyone unaccounted for is identified quickly, because that is what emergency services need most urgently on arrival.', 'Ku nkongi, ibikorwa bya mbere ni ugutera induru no gutangiza kwimura abantu. Kugerageza kurwanya inkongi bikwiye gusa ku nkongi ntoya, ikikijwe, hakoreshejwe ubwoko bunoze bw''igikoresho, kandi ntibigomba na rimwe gutinza kwimura abantu. Mu gihe cyo kwimuka, abakozi bayobora abantu ku bushake bagana ku muryango w''umutekano wa hafi aho kwiyumvisha ko bazawubona, kuko abantu benshi basohoka banyuze mu nzira binjiriyemo n''igihe hari umuryango wa hafi. Ntimukoreshe itara. Yobora abantu bagana ahantu ho guhurira aho kubemerera guhagarara hanze y''umuryango, bikaziba abakiri gusohoka. Fasha kubara abantu kugira ngo utabonetse amenyekane vuba, kuko ari yo abatabazi bakenera cyane bageze.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_3, '3.5', 'Intrusion, Theft and Confrontation', 'Kwinjira mu Buryo Butemewe, Ubujura no Guhangana', 'text', 'Never search a potentially occupied space alone: a lone officer has no backup, no witness and no clear exit plan. Withdraw to a position that keeps the area under observation while providing a route away, report specifically, and wait for support before entering in pairs. In a confrontation, an officer holds no authority beyond that of any citizen plus rights delegated by the site owner. Force must be lawful, reasonable, proportionate, a last resort after de-escalation and withdrawal have been considered, and must cease the moment the threat ceases. Property is never worth a serious injury: allowing a person to leave with stolen goods while recording a description is almost always the correct decision.', 'Ntukigere usaka ahantu hashobora kuba hari umuntu wenyine: umukozi wenyine nta bufasha afite, nta muhamya kandi nta gahunda isobanutse yo gusohokamo. Subira ahantu hakureka ureba agace hakanaguha inzira yo kuhava, tanga raporo yihariye, kandi utegereze ubufasha mbere yo kwinjira muri babiri. Mu guhangana, umukozi nta bubasha afite burenze ubw''umuturage uwo ari we wese n''uburenganzira yahawe na nyir''ahantu. Imbaraga zigomba kuba zemewe, zishyize mu gaciro, zihuye n''akaga, ari bwo buryo bwa nyuma nyuma yo gutekereza kugabanya ubushyuhe no gusubira inyuma, kandi zigomba guhagarara ako kanya akaga kavuyeho. Ibintu ntibigera bihwanye n''ikomere rikomeye: kwemerera umuntu kugenda n''ibyibwe mu gihe wandika uko asa hafi buri gihe ni cyo cyemezo gikwiye.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-111', m_KG_111_3, 'Quiz — Incident Response', 'Ikizamini — Gutabara Ikibazo', 'quiz', 70, 3)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What is the fixed priority sequence in any incident?', 'Ni uruhe rutonde rw''ibanze rudahinduka mu kibazo cyose?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Protect life, contain the situation, notify', 'Kurinda ubuzima, kugarura ikibazo, gutangaza', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'By whether the standard holds on ordinary days, not exceptional ones', 'N''uko urwego rugumaho ku minsi isanzwe, atari idasanzwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Only after the incoming officer has arrived, been briefed and confirmed understanding', 'Nyuma gusa y''uko uje ageze, amenyeshejwe kandi yemeje ko yumvise', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Ambiguity about who holds decision authority', 'Kutamenya ufite ububasha bwo gufata icyemezo', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What should you do in the first sixty seconds if you are genuinely unsure?', 'Ukora iki mu masegonda mirongo itandatu ya mbere niba utazi neza?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To support — clearing routes, access, information — not to keep directing', 'Gushyigikira — gufungura inzira, abinjira, amakuru — atari gukomeza kuyobora', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'No backup, no witness and no clear exit plan', 'Nta bufasha, nta muhamya kandi nta nzira isobanutse', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Those who talk adopt each other''s version unconsciously', 'Abavugana bemera verisiyo za bagenzi babo batabishaka', false, 3);
