do $$ declare m_KG_111_6 uuid; a_id uuid; q_id uuid; begin
  if not exists (select 1 from public.courses where id = 'KG-111') then return; end if;
  insert into public.modules (course_id, number, title, title_rw, intro, intro_rw, sort_order)
  values ('KG-111', 6, 'Post-Incident Review and Continuous Improvement', 'Isuzuma Nyuma y''Ikibazo no Gukomeza Kunoza', 'This final module covers what happens after an incident closes: the structured review, learning from near-misses, supporting staff, and the professional standards that govern operational work.', 'Iki gice cya nyuma kigaruka ku bibaho nyuma y''uko ikibazo gisojwe: isuzuma riteguye, kwiga ku byari hafi kubaho, gufasha abakozi, n''amabwiriza y''umwuga agenga akazi k''ibikorwa.', 6)
  returning id into m_KG_111_6;
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_6, '6.1', 'Conducting a Structured Post-Incident Review', 'Gukora Isuzuma Riteguye Nyuma y''Ikibazo', 'text', 'The review exists to change a control, not to identify a person to blame, because a review perceived as blame-seeking produces defensive accounts and destroys the information it depends on. It follows a structure rather than an open discussion: what was supposed to happen, what actually happened, where did the two diverge, and was the control absent, poorly designed, or present but not followed. Those three states require completely different remedies, and conflating them produces a corrective action that does not correct anything. Conduct the review while recollection is fresh, include the officers who were actually present, and produce a written record with named actions and dates.', 'Isuzuma ririho kugira ngo hahinduke igenzura, atari ukumenya umuntu wo guhana, kuko isuzuma rifatwa nk''irishaka guhana ritanga ibisobanuro byo kwirwanaho kandi rigasenya amakuru rishingiyeho. Rikurikiza imiterere aho kuba ikiganiro gifunguye: ni iki cyagombye kuba, ni iki cyabaye koko, ni hehe byombi byatandukaniye, kandi ese igenzura ryari ridahari, ryateguwe nabi, cyangwa ryari rihari ariko ntirikurikizwe. Iyo mimerere itatu isaba ibisubizo bitandukanye burundu, kandi kubivanga bitanga igikorwa cyo gukosora kidakosora ikintu. Kora isuzuma mu gihe kwibuka gukiri kunoze, ushyiremo abakozi bari bahari koko, kandi ukore inyandiko ifite ibikorwa byagenwe n''amatariki.', 12, 1);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_6, '6.2', 'Learning from Near-Misses', 'Kwiga ku Byari Hafi Kubaho', 'text', 'A near-miss contains exactly the same lesson as an incident, at no human cost, and is therefore the cheapest learning any operation will ever receive. It is also the most commonly discarded, because nothing happened and there is no pressure to review it. Build reporting of near-misses into the routine and treat a reported near-miss as a contribution rather than an admission — an operation where reporting a near-miss brings criticism will simply stop receiving them, and will then be surprised by the incident that follows. Feed every near-miss finding into the same corrective action process as an actual incident.', 'Ikintu cyari hafi kubaho kirimo isomo rimwe rusa n''iry''ikibazo, nta gihombo cy''ubuzima, bityo ni bwo bumenyi buhendutse kurusha ubundi ibikorwa bizigera bibona. Ni na cyo gikunze kujugunywa kurusha ibindi, kuko nta cyabaye kandi nta gitutu cyo kugisuzuma. Shyira gutanga raporo ku byari hafi kubaho mu bisanzwe kandi ufate raporo yatanzwe nk''uruhare aho kuyifata nk''ukwemera ikosa — ibikorwa aho gutanga raporo ku cyari hafi kubaho bizana kunengwa bizahita bihagarika kubona izo raporo, hanyuma bikazatungurwa n''ikibazo gikurikiraho. Shyira buri kintu cyabonetse mu byari hafi kubaho mu nzira imwe yo gukosora n''iy''ikibazo cyabaye.', 12, 2);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_6, '6.3', 'Supporting Officers After a Serious Incident', 'Gufasha Abakozi Nyuma y''Ikibazo Gikomeye', 'text', 'Officers who deal with a serious incident — a fatality, a serious injury, violence, a fire — carry it afterwards, and an operation that ignores this loses good people and stops receiving honest reports. Practical measures: check on each person involved individually rather than addressing the team collectively; do not require an officer to continue a shift alone immediately after a serious event; make it explicitly acceptable to say that something affected you; and ensure officers know what support is available. A supervisor who treats a serious incident as routine communicates that distress is unprofessional, and officers will then conceal it, which is worse for them and worse for the operation.', 'Abakozi bacyuye ikibazo gikomeye — urupfu, gukomereka bikomeye, urugomo, inkongi — bakigumana nyuma, kandi ibikorwa bibirengagiza bitakaza abantu beza kandi bikahagarika kubona raporo z''ukuri. Ingamba zifatika: baza buri muntu wabigizemo uruhare ku giti cye aho kuvugana n''itsinda ryose; ntugasabe umukozi gukomeza akazi wenyine ako kanya nyuma y''ikintu gikomeye; tuma bigaragara ko byemewe kuvuga ko ikintu cyakugizeho ingaruka; kandi wemeze ko abakozi bazi ubufasha buhari. Umuyobozi ufata ikibazo gikomeye nk''igisanzwe agaragaza ko kubabara ari ukutagira ubunyamwuga, kandi abakozi bazahita babihisha, ari bibi kuri bo kandi bibi ku bikorwa.', 12, 3);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_6, '6.4', 'Professional and Legal Standards in Operations', 'Amabwiriza y''Umwuga n''Ay''Amategeko mu Bikorwa', 'text', 'A security officer holds no authority beyond that of any citizen plus rights delegated by the site owner, and must know that boundary precisely because exceeding it exposes the officer criminally and the organisation civilly. Force must be lawful, reasonable, proportionate, a last resort and must cease when the threat ceases. Detention carries significant legal risk and follows the specific rules of the jurisdiction rather than assumption. Beyond the legal minimum, professional standards require: honest reporting even where the report is inconvenient; treating every person equally regardless of appearance or perceived status; declining any gift that creates an expectation; and reporting a colleague''s serious misconduct, because silence in an operational environment is participation.', 'Umukozi w''umutekano nta bubasha afite burenze ubw''umuturage uwo ari we wese n''uburenganzira yahawe na nyir''ahantu, kandi agomba kumenya uwo mupaka neza kuko kuwurenga byiteza umukozi ibyago by''ubushinjacyaha n''ikigo ibirego. Imbaraga zigomba kuba zemewe, zishyize mu gaciro, zihuye n''akaga, ari ubwa nyuma kandi zigomba guhagarara akaga kavuyeho. Gufunga umuntu bifite ibyago bikomeye by''amategeko kandi bikurikiza amategeko yihariye y''aho ukorera aho gushingira ku kwiyumvisha. Hejuru y''ibisabwa n''amategeko, amabwiriza y''umwuga asaba: gutanga raporo z''ukuri n''aho raporo idashimishije; gufata buri muntu kimwe utitaye ku ko agaragara cyangwa urwego rukekwa; kwanga impano iyo ari yo yose itera icyizere; no gutanga raporo ku myitwarire mibi ikomeye ya mugenzi wawe, kuko guceceka mu bikorwa ari ukugira uruhare.', 12, 4);
  insert into public.lessons (module_id, number, title, title_rw, kind, body, body_rw, duration_minutes, sort_order)
  values (m_KG_111_6, '6.5', 'Continuous Improvement and Professional Development', 'Gukomeza Kunoza n''Iterambere ry''Umwuga', 'text', 'An operation that does not change in response to what it learns will keep producing the same failures. Build a cycle: collect evidence from occurrence books, incident and near-miss reports, supervisory observations and audits; identify what the evidence indicates should change; make a specific change with an owner and date; and verify it produced the intended effect rather than assuming. Capture changes in the written post orders and procedures so they outlast the individuals who introduced them. For the individual officer, the progression runs from officer to shift supervisor to operations manager to security manager, and the strongest development habit is documentation: a portfolio of incidents handled, reports written and improvements implemented is what distinguishes a candidate at interview.', 'Ibikorwa bitahinduka bishingiye ku byo byigiye bizakomeza gutanga amakosa amwe. Ubaka uruziga: kusanya ibimenyetso mu bitabo by''ibibaye, raporo z''ibibazo n''iz''ibyari hafi kubaho, ibyabonywe n''abagenzuzi n''amagenzura; menya icyo ibimenyetso byerekana ko cyagombye guhinduka; kora impinduka yihariye ifite uwayishinzwe n''itariki; kandi wemeze ko yatanze icyari kigenewe aho kwiyumvisha. Andika impinduka mu mabwiriza y''aho ukorera n''inzira z''akazi kugira ngo zikurusha abantu bazizanye. Ku mukozi ku giti cye, inzira igenda ivuye ku mukozi ijya ku muyobozi w''akazi, ijya ku muyobozi w''ibikorwa, ijya ku muyobozi w''umutekano, kandi umuco ukomeye w''iterambere ni inyandiko: ububiko bw''ibibazo wacyuye, raporo wanditse n''impinduka washyize mu bikorwa ni byo bitandukanya ukandida mu kiganiro.', 12, 5);
  insert into public.assessments (course_id, module_id, title, title_rw, kind, pass_mark, sort_order)
  values ('KG-111', m_KG_111_6, 'Quiz — Post-Incident Review and Continuous Improvement', 'Ikizamini — Isuzuma Nyuma y''Ikibazo no Gukomeza Kunoza', 'quiz', 70, 6)
  returning id into a_id;
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 1, 'mcq', 'What is the purpose of a post-incident review?', 'Ni iyihe ntego y''isuzuma nyuma y''ikibazo?', 1, 1) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To change a control, not to identify a person to blame', 'Guhindura igenzura, atari kumenya umuntu wo guhana', true, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'By whether the standard holds on ordinary days, not exceptional ones', 'N''uko urwego rugumaho ku minsi isanzwe, atari idasanzwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Only after the incoming officer has arrived, been briefed and confirmed understanding', 'Nyuma gusa y''uko uje ageze, amenyeshejwe kandi yemeje ko yumvise', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Ambiguity about who holds decision authority', 'Kutamenya ufite ububasha bwo gufata icyemezo', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why is a near-miss the cheapest learning an operation receives?', 'Kuki ikintu cyari hafi kubaho ari bwo bumenyi buhendutse?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To support — clearing routes, access, information — not to keep directing', 'Gushyigikira — gufungura inzira, abinjira, amakuru — atari gukomeza kuyobora', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Only when an immediate greater danger requires it', 'Gusa igihe akaga gakomeye kegereje kabisabye', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Evidence frequently sits outside where the incident visibly occurred', 'Ibimenyetso akenshi biba hanze y''aho cyagaragariye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It contains the same lesson at no human cost', 'Kirimo isomo rimwe nta gihombo cy''ubuzima', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What happens when a supervisor treats a serious incident as routine?', 'Ni iki kibaho iyo umuyobozi afata ikibazo gikomeye nk''igisanzwe?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Inference — replace with the observation that produced it', 'Icyiyumvishijwe — simbuza icyabonetse cyagiteye', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'To change a control, not to identify a person to blame', 'Guhindura igenzura, atari kumenya umuntu wo guhana', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Officers learn to conceal distress, which is worse for them and the operation', 'Abakozi biga guhisha imibabaro, ari bibi kuri bo n''ibikorwa', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Those who talk adopt each other''s version unconsciously', 'Abavugana bemera verisiyo za bagenzi babo batabishaka', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'Why must changes be captured in written post orders?', 'Kuki impinduka zigomba kwandikwa mu mabwiriza y''aho ukorera?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Location, observation and requirement stated specifically', 'Ahantu, icyabonetse n''icyo usaba bivuzwe neza', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'So they outlast the individuals who introduced them', 'Kugira ngo zikurushe abantu bazizanye', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It contains the same lesson at no human cost', 'Kirimo isomo rimwe nta gihombo cy''ubuzima', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The details that differ between posts are exactly what causes failures', 'Ibitandukanye hagati y''imirimo ni byo bitera ibibazo', false, 4);
end $$;
