  values (q_id, 'The principal cannot be hardened — they must continue living and working normally', 'Uwo barinda ntashobora gukomezwa — agomba gukomeza kubaho busanzwe', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Their assigned arc of responsibility, not the principal', 'Igice cy''inshingano yahawe, atari uwo barinda', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Heavy investment close to the principal with nothing at the information layer', 'Gushora byinshi hafi y''uwo barinda nta kintu ku rwego rw''amakuru', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'What is the adversary''s most valuable asset?', 'Ni uwuhe mutungo w''agaciro kanini w''umwanzi?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Vulnerability — a threat exists independently of you', 'Intege nke — iterabwoba ribaho ridashingiye kuri wowe', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'As an integrity failure rather than a mistake', 'Nk''ikosa ry''ubudahemuka aho kuba ikosa gusa', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'By what leaders do, not by what they publish', 'N''ibyo abayobozi bakora, atari ibyo batangaza', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Predictability — therefore variation is the officer''s asset', 'Kumenyekana — bityo ihinduka ni umutungo w''umukozi', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Why is anticipation preferable to tension as a mindset?', 'Kuki guteganya kuruta umuvuduko nk''imyumvire?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The principal — the specialist advises on risk', 'Uwo barinda — umunyamwuga agira inama ku byago', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Predictability — therefore variation is the officer''s asset', 'Kumenyekana — bityo ihinduka ni umutungo w''umukozi', false, 2);
