  values (q_id, 'Tension cannot be maintained; anticipation can', 'Umuvuduko ntushobora kugumaho; guteganya birashobora', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Documentation and discretion', 'Inyandiko n''ubushishozi', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What is the most common layering failure in practice?', 'Ni irihe kosa rikunze kubaho mu nzego?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An adversary studying a detail will study its members', 'Umwanzi wiga itsinda azabiga ku bawugize', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Heavy investment close to the principal with nothing at the information layer', 'Gushora byinshi hafi y''uwo barinda nta kintu ku rwego rw''amakuru', true, 2);
