  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Report it immediately — the approach itself is intelligence', 'Tangaho raporo ako kanya — ukwegerwa ubwako ni amakuru', true, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
