  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is instrumental, therefore deterred by difficulty', 'Ni iry''ugukoresha, bityo rikumirwa n''ingorane', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
