  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What is the highest-value application of OSINT in protective work?', 'Ni irihe koreshwa rifite agaciro kanini rya OSINT mu murimo wo kurinda?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
