  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The process takes time and leaves traces that can be found', 'Inzira itwara igihe kandi isiga ibimenyetso bishobora kuboneka', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'There is no reliable demographic profile, but there is a reliable behavioural sequence', 'Nta miterere y''abantu yizewe, ariko hari urutonde rw''imyitwarire rwizewe', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Assessing what an adversary could learn about the principal effortlessly', 'Gusuzuma icyo umwanzi yamenya ku wo barinda nta mbaraga', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why classify a threat actor by motivation?', 'Kuki utondeka utera iterabwoba ukurikije icyifuzo?', 1, 2) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Family, household staff, assistants and children — not the principal', 'Umuryango, abakozi bo mu rugo, abafasha n''abana — atari uwo barinda', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'It is instrumental, therefore deterred by difficulty', 'Ni iry''ugukoresha, bityo rikumirwa n''ingorane', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Indefinite retention — a compliance and an analytical failure', 'Kubika nta gihe ntarengwa — ikosa ryo kubahiriza n''iryo gusesengura', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Motivation predicts method and target selection', 'Icyifuzo giteganya uburyo no guhitamo uwibasirwa', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Why should you never engage a stalking individual?', 'Kuki utagomba guhangana n''ukurikirana?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Between people who make threats and people who pose them', 'Hagati y''abatanga iterabwoba n''abaritera', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
