  values (q_id, 'An ordinary conversation held where it could be overheard', 'Ikiganiro gisanzwe cyabereye aho cyashoboraga kumvwa', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'The human-layer test — it produces evidence rather than assurance', 'Gupima urwego rw''abantu — bitanga ibimenyetso aho gutanga icyizere', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Nobody is expected to detect a skilled pretext — the rule must be absolute', 'Nta muntu utegerejweho kumenya impamvu y''inzobere — itegeko rigomba kuba ntarengwa', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What should be assumed about anything provided to an external party?', 'Ni iki cyiyumvishwa ku kintu cyose gitanzwe hanze?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'An ordinary conversation held where it could be overheard', 'Ikiganiro gisanzwe cyabereye aho cyashoboraga kumvwa', false, 1);
