  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Command and working the principal — they require opposite actions at the same moment', 'Ubuyobozi no gukorera uwo barinda — bisaba ibikorwa bihabanye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They know every movement in advance, hear every conversation and have unsupervised vehicle access', 'Bazi buri rugendo mbere, bumva buri kiganiro, bafite ukwinjira mu modoka', true, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'What is the common failure mode of access control?', 'Ni ubuhe buryo busanzwe bwo kunanirwa kw''igenzura ry''abinjira?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Consistently choosing the most secure route makes it predictable', 'Guhora uhitamo ifite umutekano bituma imenyekana', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'They know every movement in advance, hear every conversation and have unsupervised vehicle access', 'Bazi buri rugendo mbere, bumva buri kiganiro, bafite ukwinjira mu modoka', false, 2);
