  values (q_id, 'When the practice changes and stays changed', 'Igihe imikorere ihindutse ikaguma yahindutse', false, 4);
  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 4, 'mcq', 'What does a single visible credentialing exception establish?', 'Kirengagizwa kimwe kigaragara ku mpushya gishyiraho iki?', 1, 4) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'A total invites a percentage cut; risk decisions invite a decision on each line', 'Igiteranyo gitumira gucibwa; ibyemezo bitumira icyemezo kuri buri murongo', false, 1);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'That the system is advisory', 'Ko sisitemu ari inama', true, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
