  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 2, 'mcq', 'Why present a budget as risk decisions rather than as a total?', 'Kuki utanga ingengo y''imari nk''ibyemezo by''ibyago aho kuyitanga nk''igiteranyo?', 1, 2) returning id into q_id;
