  insert into public.questions (assessment_id, number, kind, prompt, prompt_rw, points, sort_order)
  values (a_id, 3, 'mcq', 'Which two detail functions cannot be held by the same officer during an incident?', 'Ni iyihe mirimo ibiri itashobora kuba ku mukozi umwe mu kibazo?', 1, 3) returning id into q_id;
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
