  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Complacency — a control that has quietly stopped being applied', 'Kwiringira — igenzura ryahagaritse gukoreshwa mu bwiherero', false, 4);
