  values (q_id, 'A commander absorbed in performing a task personally has stopped commanding', 'Umuyobozi wibanda ku murimo ku giti cye yahagaritse kuyobora', false, 2);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Officers who understand why comply durably; a rule alone is complied with until inconvenient', 'Abasobanukiwe impamvu bakurikiza birambye; itegeko rikurikizwa kugeza ribangamiye', false, 3);
  insert into public.question_options (question_id, label, label_rw, is_correct, sort_order)
  values (q_id, 'Directive — there is no time to build consensus while a situation is developing', 'Gutegeka — nta gihe cyo kubaka ubwumvikane ibintu bigenda bikura', false, 4);
