-- ---------- What actually landed ----------
do $$
declare r record;
begin
  raise notice '--- Kagoma course content ---';
  for r in
    select c.id,
           (select count(*) from public.modules m where m.course_id = c.id)     as modules,
           (select count(*) from public.lessons l
              join public.modules m on m.id = l.module_id
             where m.course_id = c.id)                                          as lessons,
           (select count(*) from public.assessments a where a.course_id = c.id) as assessments
    from public.courses c order by c.sort_order, c.id
  loop
    raise notice '% : % modules, % lessons, % assessments',
      rpad(r.id, 8), r.modules, r.lessons, r.assessments;
  end loop;
end $$;
